const DB={daes:[{id:'AS',name:'DAE ÁSIA',region:'Sobrevoo urbano de Osaka',coord:'Osaka / sobrevoo urbano',x:80.8,y:33.7,status:'INTERVENÇÃO',home:true,course:'067° / NE',rotation:'-113deg',mission:'Intervenção emergencial · Osaka',vector:'Osaka / espaço aéreo urbano',aircraft:'284',helicopters:'91',support:'46',readiness:'PRONTIDÃO MÁXIMA',activity:'Plataforma em sobrevoo de Osaka; ala aérea em operação e unidades de Segurança atuando na cidade.'},{id:'EU',name:'DAE EUROPA',region:'Mar Negro · ao norte da costa turca',coord:'42°06′ N · 31°40′ L',x:54.2,y:28.8,status:'APOIO REGIONAL',course:'105° / L',rotation:'-75deg',mission:'Suporte à operação no Afeganistão',vector:'Mar Negro / corredor turco',aircraft:'196',helicopters:'64',support:'33',readiness:'PRONTIDÃO REGULAR',activity:'Apoio aéreo, evacuação médica e abastecimento às forças que combatem os Blood Bersekers. Plataforma posicionada fora do Afeganistão.'},{id:'AF',name:'DAE ÁFRICA',region:'Oceano Índico',coord:'17°34′ S · 39°05′ L',x:58.5,y:60,status:'OPERACIONAL',course:'210° / SO',rotation:'30deg',mission:'Cobertura da costa oriental',vector:'Oceano Índico / setor oeste',aircraft:'172',helicopters:'58',support:'27',readiness:'PRONTIDÃO REGULAR',activity:'Revezamento de equipes e inspeção programada dos hangares.'},{id:'AN',name:'DAE AMÉRICA NORTE',region:'Pacífico Norte',coord:'37°19′ N · 138°44′ O',x:19,y:26,status:'OPERACIONAL',course:'135° / SE',rotation:'-45deg',mission:'Vigilância e deslocamento',vector:'Pacífico Norte / setor leste',aircraft:'231',helicopters:'73',support:'38',readiness:'PRONTIDÃO REGULAR',activity:'Esquadrões de reconhecimento em patrulha.'},{id:'ASU',name:'DAE AMÉRICA SUL',region:'Atlântico Sul',coord:'24°51′ S · 42°18′ O',x:36,y:65,status:'OPERACIONAL',course:'040° / NE',rotation:'-140deg',mission:'Patrulha continental',vector:'Atlântico Sul / setor oeste',aircraft:'183',helicopters:'61',support:'29',readiness:'PRONTIDÃO REGULAR',activity:'Manutenção de frota concluída; rotas regulares restabelecidas.'}],records:[{"id": "PES-2501", "title": "Major Takeshi Kanzaki / Chefe local de Segurança", "category": "Pessoal", "origin": "SEGURANÇA SDAI / DAE ÁSIA", "access": "Todas as divisões", "level": 2, "recordType": "employee", "summary": "Chefia a Segurança da DAE ÁSIA. Formal, rigoroso com registros e intolerante a ordens sem origem verificável. Coordena postos, escoltas e resposta interna; considera a manutenção do controle uma prioridade mesmo quando a doutrina da SDAI impõe medidas extremas.", "detail": "Cadastro operacional de referência. Atribuições locais da DAE ÁSIA; documentos administrativos completos no diretório de Recursos Humanos.", "employee": {"name": "Takeshi Kanzaki", "displayTitle": "Major Takeshi Kanzaki", "japaneseName": "神崎 武", "nativeLang": "ja", "age": "52 anos / cadastro de 2019", "nationality": "Japonesa", "birthplace": "Yokohama, Japão", "role": "Chefe local de Segurança", "division": "Segurança SDAI", "station": "DAE ÁSIA / Segurança e instalações sob sua responsabilidade", "supervision": "Comando regional da DAE ÁSIA", "appointment": "Quadro regular da SDAI / serviço ativo", "capture": "2002 / quadro operacional", "previousRole": "Serviço militar japonês / proteção de instalações", "clearance": "Permissões próprias de função / não transferidas ao consulente", "status": "Em serviço / lotação na DAE ÁSIA", "serviceLabel": "SERVIÇO ATIVO / QUADRO REGULAR", "emblemKey": "seguranca", "directoryLabel": "SEGURANÇA SDAI / CADASTRO FUNCIONAL", "personnelKind": "PESSOAL / CHEFIA LOCAL", "personalLabel": "INFORMAÇÕES DO FUNCIONÁRIO", "specialty": "Proteção de instalações / coordenação de efetivos", "custodyRegime": "Serviço regular / sujeito à cadeia de comando", "custodyTitle": "VÍNCULO FUNCIONAL / QUADRO REGULAR", "custodyNote": "Integra o quadro regular da SDAI, com atribuições de serviço e supervisão formal. As permissões do cargo são pessoais e delimitadas; consultar esta ficha não concede acesso aos setores ou autoridade para emitir ordens em seu nome.", "currentWork": "Revisando a distribuição de postos e escoltas durante a intervenção em Osaka, a disponibilidade das equipes e a aplicação das determinações da Segunda Fase. Mantém planos de reação para alterações do estado de segurança a bordo.", "quickSummary": "Chefia a Segurança da DAE ÁSIA. Formal, rigoroso com registros e intolerante a ordens sem origem verificável. Coordena postos, escoltas e resposta interna; considera a manutenção do controle uma prioridade mesmo quando a doutrina da SDAI impõe medidas extremas.", "projects": [{"code": "SEG-POSTOS", "name": "Postos e passagens", "work": "Conferir responsáveis por acessos, rendições e deslocamentos entre setores.", "state": "EM ATIVIDADE"}, {"code": "SEG-ESC", "name": "Escoltas e contenção", "work": "Articular a Segurança com a custódia científica e a disponibilidade das equipes especializadas.", "state": "EM ATIVIDADE"}, {"code": "SEG-AS", "name": "Prontidão interna", "work": "Manter a resposta de alerta e bloqueio preparada, conforme o estado efetivamente declarado.", "state": "EM ATIVIDADE"}], "identifications": [], "sections": [{"title": "PERFIL / CHEFIA DE SEGURANÇA", "paragraphs": ["Kanzaki ingressou na SDAI após atuar na proteção de instalações militares. A experiência fez dele um organizador de postos e cadeias de responsabilidade, mais conhecido por conferir autorizações do que por discursos ao efetivo.", "Fala de maneira curta e costuma exigir que o responsável por uma ordem seja identificado no registro. O cuidado é procedimental: não representa oposição à doutrina de captura e eliminação da SDAI."]}, {"title": "AUTORIDADE / ESCOPO LOCAL", "paragraphs": ["Responde pela coordenação local da Segurança na DAE ÁSIA, dentro das determinações do comando regional. Pode distribuir equipes, organizar escoltas e exigir conferências de acesso; decisões do Alto Comando continuam superiores à sua função.", "Infantaria padrão, equipes de elite, Advancers e Aniquiladores possuem atribuições e responsáveis próprios. Os Advancers são uma unidade específica com jetpack; a ficha não os converte em sinônimo de elite nem torna todas essas unidades divisões administrativas independentes."]}, {"title": "ROTINA / CONTROLE E REGISTRO", "paragraphs": ["Recebe relatórios de mudança de turno, verifica postos sem substituto e cruza pedidos de trânsito com a necessidade de escolta. Gosta de documentos curtos com horário, setor e responsável; devolve registros com assinaturas ou origens indefinidas.", "Diante de alteração para alerta ou bloqueio, aplica o protocolo correspondente. Esta ficha não declara uma invasão adicional: descreve sua responsabilidade conforme o estado da plataforma."]}, {"title": "SEGUNDA FASE / CUMPRIMENTO DE DIRETRIZES", "paragraphs": ["Coordena a aplicação das determinações de Segurança da Segunda Fase e a disponibilidade de efetivos para os procedimentos autorizados. A utilidade de um contido não é tratada por ele como permissão para ignorar uma ordem superior.", "O controle documental convive com a violência institucional da SDAI. Sua exigência de registros busca preservar a cadeia de comando e a responsabilidade interna, sem suspender a política da organização."]}, {"title": "RELAÇÕES DE SERVIÇO", "paragraphs": ["Junpei Kurose responde a Kanzaki pela parte de Segurança da custódia científica. Naoko Senda informa necessidades laboratoriais; Arvensis / Marina Azevedo fornece avaliações de risco e vínculos de interesse.", "Não decide conclusões científicas e não pode reclassificar por conta própria a identidade de um módulo. Pareceres e ordens operacionais seguem registros distintos."]}, {"title": "ATENDIMENTO / LIMITE DO CADASTRO", "paragraphs": ["O contato funcional deve seguir a chefia de setor ou o canal interno de Segurança. Seu retrato facilita o reconhecimento da autoridade; uma ordem recebida informalmente ainda exige verificação pela cadeia responsável.", "A ficha do AS-07 contém atribuições e contatos de referência. Escalas completas, dados pessoais reservados e a lotação integral do efetivo permanecem no sistema administrativo de Recursos Humanos."]}], "referencesTitle": "RELAÇÕES DE SERVIÇO / CONTATOS DE REFERÊNCIA", "references": [{"id": "PES-2504", "label": "Junpei Kurose / custódia científica →"}, {"id": "PES-2502", "label": "Naoko Senda / chefia de P&D →"}, {"id": "PES-2503", "label": "Arvensis / Marina Azevedo / Inteligência →"}], "referencesNote": "As referências indicam relação funcional. Os registros individuais mantêm suas condições de acesso.", "footer": "PES-2501 / DAE ÁSIA · QUADRO REGULAR · CHEFIA LOCAL · CADASTRO OPERACIONAL / 2019", "photo": "assets/e37a90e7878b1046fcda04e5.png", "fields": [["CARGO", "Chefe local de Segurança"], ["DIVISÃO", "Segurança SDAI"], ["LOTAÇÃO", "DAE ÁSIA / Segurança e instalações sob sua responsabilidade"], ["SUPERIOR FUNCIONAL", "Comando regional da DAE ÁSIA"], ["VÍNCULO", "Quadro regular da SDAI / serviço ativo"], ["INGRESSO NA SDAI", "2002 / quadro operacional"], ["EXPERIÊNCIA ANTERIOR", "Serviço militar japonês / proteção de instalações"], ["PERMISSÕES", "Permissões próprias de função / não transferidas ao consulente"]]}},{"id": "PES-2502", "title": "Dra. Naoko Senda / Chefe local de Pesquisa e Desenvolvimento", "category": "Pessoal", "origin": "P&D SDAI / DAE ÁSIA", "access": "Todas as divisões", "level": 2, "recordType": "employee", "summary": "Dirige a P&D da DAE ÁSIA. Cientista do quadro regular, organiza prioridades, valida revisões e administra o trabalho dos pesquisadores retidos. Trata a precisão científica como recurso institucional e mantém as pesquisas subordinadas às determinações da SDAI.", "detail": "Cadastro operacional de referência. Atribuições locais da DAE ÁSIA; documentos administrativos completos no diretório de Recursos Humanos.", "employee": {"name": "Naoko Senda", "displayTitle": "Dra. Naoko Senda", "japaneseName": "千田 直子", "nativeLang": "ja", "age": "55 anos / cadastro de 2019", "nationality": "Japonesa", "birthplace": "Sendai, Japão", "role": "Chefe local de Pesquisa e Desenvolvimento", "division": "P&D SDAI", "station": "DAE ÁSIA / Distrito de Pesquisa", "supervision": "Coordenação regional / direção técnica de P&D", "appointment": "Quadro regular da SDAI / serviço ativo", "capture": "2004 / recrutamento científico", "previousRole": "Neuroengenharia e avaliação de interfaces clínicas", "clearance": "Permissões próprias de função / não transferidas ao consulente", "status": "Em serviço / lotação na DAE ÁSIA", "serviceLabel": "SERVIÇO ATIVO / QUADRO REGULAR", "emblemKey": "pesquisa", "directoryLabel": "P&D SDAI / CADASTRO FUNCIONAL", "personnelKind": "PESSOAL / CHEFIA LOCAL", "personalLabel": "INFORMAÇÕES DA FUNCIONÁRIA", "specialty": "Neuroengenharia / revisão científica / gestão de pesquisa", "custodyRegime": "Serviço regular / sujeito à cadeia de comando", "custodyTitle": "VÍNCULO FUNCIONAL / QUADRO REGULAR", "custodyNote": "Integra o quadro regular da SDAI, com atribuições de serviço e supervisão formal. As permissões do cargo são pessoais e delimitadas; consultar esta ficha não concede acesso aos setores ou autoridade para emitir ordens em seu nome.", "currentWork": "Consolidando a fila de pareceres e a preservação dos registros exigidos pela Segunda Fase. Supervisiona as entregas de Reika Mizuhara e a revisão do acervo INTERAURA; acompanha a ausência de Ariella como perda de acesso a uma fonte que nunca colaborou.", "quickSummary": "Dirige a P&D da DAE ÁSIA. Cientista do quadro regular, organiza prioridades, valida revisões e administra o trabalho dos pesquisadores retidos. Trata a precisão científica como recurso institucional e mantém as pesquisas subordinadas às determinações da SDAI.", "projects": [{"code": "PD-PARECER", "name": "Revisão de pareceres", "work": "Conferir a documentação que sustenta identificações e separar confirmação de hipótese.", "state": "EM ATIVIDADE"}, {"code": "PD-LEG", "name": "Acervo e interfaces legadas", "work": "Ordenar demandas de arquivos e equipamentos, sem presumir recuperação integral do conhecimento da INTERAURA.", "state": "EM ATIVIDADE"}, {"code": "PD-FASE", "name": "Preservação de registros", "work": "Consolidar cópias e pendências científicas antes dos encerramentos determinados pela Segunda Fase.", "state": "EM ATIVIDADE"}], "identifications": [], "sections": [{"title": "PERFIL / QUADRO CIENTÍFICO REGULAR", "paragraphs": ["Senda foi recrutada pela SDAI em 2004 após trabalhar com avaliação de interfaces clínicas. Não integrava a antiga INTERAURA e não está registrada como ex-cobaia ou cientista capturada.", "Tem maneiras contidas, lê a fundamentação antes da conclusão e corrige termos que apresentem hipótese como certeza. Essa disciplina não implica acolhimento das objeções morais feitas pelos pesquisadores sob sua supervisão."]}, {"title": "ATRIBUIÇÕES / DIREÇÃO TÉCNICA LOCAL", "paragraphs": ["Organiza a fila de trabalho da P&D na DAE ÁSIA, solicita revisão de relatórios e distribui tarefas científicas autorizadas. Pode registrar limitações técnicas, mas não substituir a autoridade do Alto Comando sobre as diretrizes da Segunda Fase.", "O cargo coordena recursos e valida o trabalho contemporâneo da SDAI. Não lhe transfere autoria dos projetos antigos de Adam e Ariella Chiyomi, nem o conhecimento de Akira Hakurei sobre Cryptum e a Armadura Hakurei."]}, {"title": "PESQUISADORES RETIDOS / TRABALHO SOB SUPERVISÃO", "paragraphs": ["Acompanha a produtividade dos antigos cientistas da INTERAURA empregados em regime de custódia. A manutenção de privilégios é tratada como instrumento de administração do trabalho, em conjunto com a Segurança.", "Reconhece a consistência dos pareceres de Reika Mizuhara. As identificações de MOD-11, MOD-28 e MOD-67 continuam assinadas por Reika; a posição de Senda não a torna autora dessas confirmações."]}, {"title": "REIKA / OBJEÇÕES E CONTINUIDADE DO SERVIÇO", "paragraphs": ["Registra as advertências de Reika contra a execução coletiva, mas as considera sem comprovação suficiente para fundamentar uma mudança de protocolo. A insistência é recebida com impaciência e tentativas de encerrar o assunto.", "A chefia mantém as demandas de pesquisa e documentação. O nervosismo e o aparente trauma de Reika não são apresentados como causa de incompetência técnica ou como diagnóstico estabelecido."]}, {"title": "ARIELLA / FONTE NUNCA COOPERANTE", "paragraphs": ["Ariella permaneceu silenciosa e não prestou auxílio durante os aproximadamente 19 anos de custódia. Para Senda, o cadastro representa uma fonte de conhecimento à qual a SDAI nunca conseguiu acesso efetivo, não uma pesquisadora que deixou trabalhos em andamento.", "Após a queda do transporte, Ariella permanece desaparecida. A determinação de impedir contato com ex-cobaias deve ser observada; Senda não conhece, por este cadastro, a localização atual ou os acontecimentos posteriores ao acidente."]}, {"title": "SEGUNDA FASE / LIMITES CIENTÍFICOS", "paragraphs": ["A coordenação preserva registros e apresenta necessidades técnicas pela cadeia superior. Não dispõe de autoridade para transformar utilidade científica em dispensa de execução de um ex-cobaia contido.", "Mecanismos auríticos desconhecidos continuam assim classificados. A ficha não atribui ao departamento poderes para localizar todos os módulos, recuperar memórias ou explicar o Encouraçado apenas por consulta aos arquivos."]}], "referencesTitle": "RELAÇÕES DE SERVIÇO / CONTATOS DE REFERÊNCIA", "references": [{"id": "PES-2418", "label": "Reika Mizuhara / identificação modular →"}, {"id": "PES-2417", "label": "Ariella Chiyomi / desaparecida →"}, {"id": "PES-2504", "label": "Junpei Kurose / supervisão da custódia →"}, {"id": "LEG-0008", "label": "Acervo do Projeto de Integração Modular →"}], "referencesNote": "As referências indicam relação funcional. Os registros individuais mantêm suas condições de acesso.", "footer": "PES-2502 / DAE ÁSIA · QUADRO REGULAR · CHEFIA LOCAL · CADASTRO OPERACIONAL / 2019", "photo": "assets/8213ded307fcb6afe18922ea.png", "fields": [["CARGO", "Chefe local de Pesquisa e Desenvolvimento"], ["DIVISÃO", "P&D SDAI"], ["LOTAÇÃO", "DAE ÁSIA / Distrito de Pesquisa"], ["SUPERIOR FUNCIONAL", "Coordenação regional / direção técnica de P&D"], ["VÍNCULO", "Quadro regular da SDAI / serviço ativo"], ["INGRESSO NA SDAI", "2004 / recrutamento científico"], ["EXPERIÊNCIA ANTERIOR", "Neuroengenharia e avaliação de interfaces clínicas"], ["PERMISSÕES", "Permissões próprias de função / não transferidas ao consulente"]]}},{"id": "PES-2503", "title": "Arvensis / Marina Azevedo / chefia de Inteligência", "category": "Pessoal", "origin": "INTELIGÊNCIA SDAI / DAE ÁSIA", "access": "Todas as divisões", "level": 2, "recordType": "employee", "summary": "Marina Azevedo, brasileira, conhecida na chefia como Arvensis. Dirige a Inteligência na DAE ÁSIA e emitiu a ordem de iniciar a Segunda Fase da Lua Crescente Vermelha depois que Ariella desapareceu após a queda do transporte. É metódica na análise e implacável na condução das determinações da SDAI. Possui autorização expressa do Alto Comando para comandar o protocolo Lua Crescente Vermelha.", "detail": "Cadastro de chefia / nome civil Marina Azevedo. Ordem de abertura da Segunda Fase emitida após o desaparecimento de Ariella no acidente do transporte.", "employee": {"name": "Marina Azevedo", "displayTitle": "Arvensis / Marina Azevedo", "japaneseName": "ARVENSIS / APELIDO DE CHEFIA", "nativeLang": "pt-BR", "age": "Não divulgada neste cadastro", "nationality": "Brasileira", "birthplace": "Rio de Janeiro, Rio de Janeiro / Brasil", "role": "Chefia de Inteligência / Arvensis", "division": "Inteligência SDAI", "station": "DAE ÁSIA / Distrito de Comando", "supervision": "Alto Comando / autorização especial para comandar a Lua Crescente Vermelha", "appointment": "Quadro regular da SDAI / serviço ativo", "capture": "2007 / quadro de análise", "previousRole": "Análise de informação e investigações de redes transnacionais", "clearance": "Autorização do Alto Comando para comandar o protocolo Lua Crescente Vermelha", "status": "Em serviço / lotação na DAE ÁSIA", "serviceLabel": "SERVIÇO ATIVO / CHEFIA ARVENSIS", "emblemKey": "inteligencia", "directoryLabel": "INTELIGÊNCIA SDAI / CADASTRO FUNCIONAL", "personnelKind": "PESSOAL / CHEFIA DE INTELIGÊNCIA", "personalLabel": "INFORMAÇÕES DA FUNCIONÁRIA", "specialty": "Inteligência operacional / avaliação de risco / coordenação do protocolo", "custodyRegime": "Serviço regular / sujeito à cadeia de comando", "custodyTitle": "VÍNCULO FUNCIONAL / QUADRO REGULAR", "custodyNote": "Integra o quadro regular da SDAI, com atribuições de serviço e supervisão formal. As permissões do cargo são pessoais e delimitadas; consultar esta ficha não concede acesso aos setores ou autoridade para emitir ordens em seu nome.", "currentWork": "Coordenando a Inteligência e o acompanhamento da Segunda Fase, cuja abertura ordenou após a queda do transporte e o desaparecimento de Ariella Chiyomi. Cruza os informes de Osaka, acompanha a busca pela cientista e a distribuição das restrições de contato com ex-cobaias.", "quickSummary": "Marina Azevedo, brasileira, conhecida na chefia como Arvensis. Dirige a Inteligência na DAE ÁSIA e emitiu a ordem de iniciar a Segunda Fase da Lua Crescente Vermelha depois que Ariella desapareceu após a queda do transporte. É metódica na análise e implacável na condução das determinações da SDAI. Possui autorização expressa do Alto Comando para comandar o protocolo Lua Crescente Vermelha.", "projects": [{"code": "INT-FASE", "name": "Segunda Fase / ordem de ativação", "work": "Conduzir o protocolo por autorização expressa do Alto Comando. Aplicar as medidas já previstas na Segunda Fase, incluindo as execuções programadas dos ex-cobaias contidos e congelados, conforme os registros individuais.", "state": "PROTOCOLO EM VIGOR"}, {"code": "INT-ARI", "name": "Queda e desaparecimento de Ariella", "work": "Obter avistamento verificável ou localização de Ariella para confirmar seu estado após a queda. Classificação: desaparecida em ação, sem confirmação de vida ou morte. Impedir contato com ex-cobaias.", "state": "PRIORIDADE ATUAL"}, {"code": "INT-OSK", "name": "Alvos e vínculos em Osaka", "work": "Revisar integrantes, apoios observados e hipóteses de ligação entre os alvos, sem converter suspeitas em identidade confirmada.", "state": "EM ATIVIDADE"}], "identifications": [], "sections": [{"title": "IDENTIFICAÇÃO / CHEFIA ARVENSIS", "paragraphs": ["Marina Azevedo é brasileira, carioca, natural da cidade do Rio de Janeiro e utiliza Arvensis como apelido de chefia nos registros e encaminhamentos da Inteligência. O codinome identifica a mesma funcionária, não uma segunda pessoa ou uma unidade independente.", "Seu nome civil permanece no cadastro funcional para identificação administrativa. Entre as equipes, a assinatura Arvensis é associada a avaliações curtas, exigência de fontes verificáveis e decisões operacionais de alto impacto. Sua aparência não é apresentada como prova de capacidade aurítica."]}, {"title": "TRAJETÓRIA / ANÁLISE E DIREÇÃO DE INFORMAÇÃO", "paragraphs": ["Ingressou na SDAI em 2007 com experiência em análise de informação e investigações de redes transnacionais. Desenvolveu sua atuação comparando documentos incompletos, movimentação de recursos e vínculos entre operadores que usavam estruturas civis como cobertura.", "Costuma pedir a origem do informe antes de ouvir sua interpretação. O rigor não decorre de oposição às práticas da SDAI: busca produzir decisões que a instituição consiga executar e sustentar internamente."]}, {"title": "AUTORIDADE / ORDEM DE INICIAR A SEGUNDA FASE", "paragraphs": ["O Alto Comando concedeu a Arvensis autorização expressa para comandar o protocolo Lua Crescente Vermelha. Sua posição na Inteligência e sua importância institucional sustentam essa delegação. A autorização permite conduzir o protocolo e determinar sua ativação, sem exigir que ocupe uma cadeira no Alto Comando.", "Foi Arvensis quem ordenou iniciar a Segunda Fase da Lua Crescente Vermelha após a queda do transporte SDAI e o desaparecimento de Ariella Chiyomi, que estava a bordo. Sua atuação é registrada como emissão da ordem de abertura, não apenas retransmissão de um comunicado.", "O desaparecimento rompeu a continuidade de custódia sobre uma cientista central ao antigo Projeto de Integração Modular. Arvensis passou a tratar a perda de controle e a possibilidade de contato com ex-cobaias como prioridade para a Inteligência. A possibilidade de contato não comprova que esse contato já tenha ocorrido.", "A ativação não decorre da queda da DAE ÁSIA: o veículo acidentado foi o transporte. A plataforma principal permanece operacional. A ficha não atribui a Arvensis a causa do acidente nem identifica seus responsáveis."]}, {"title": "PROTOCOLO / ORDENS INDIVIDUAIS E RESTRIÇÕES", "paragraphs": ["A execução dos ex-cobaias contidos e congelados já estava prevista na Segunda Fase da Lua Crescente Vermelha. Ao ordenar sua ativação, Arvensis colocou em vigor essa determinação preexistente; não criou uma nova política de execução. O prazo de dez horas permanece pendente no momento registrado pelo terminal.", "As ordens continuam individuais. Onaya permanece com captura viva; o Encouraçado deve ser contido e capturado; a Mascarada mantém captura prioritária. A classificação do grupo como terrorista não cria uma ordem única de eliminação para todos os associados.", "A proibição de contato de Ariella com qualquer ex-cobaia integra as determinações vigentes. O registro de Arvensis não autoriza suspender restrições territoriais ou acordos bilaterais alheios ao protocolo."]}, {"title": "GRUPO DE OSAKA / VÍNCULOS DISTINTOS", "paragraphs": ["Arvensis distingue participação no grupo de apoio observado ou vínculo em investigação. O Caveira permanece independente, embora tenha auxiliado o grupo pela primeira vez durante o massacre do Clube da Noite.", "O vínculo do grupo com um Contemplador não identificado continua confirmado. A existência dessa direção externa não estabelece que Ariella ou o Caveira sejam a entidade. A identidade do Contemplador e o paradeiro de Ariella são pendências distintas."]}, {"title": "PENDÊNCIAS / IDENTIDADE E CORRESPONDÊNCIA", "paragraphs": ["A correspondência de Hiriko com MOD-49-1 permanece sob revisão. O óbito do MOD-49 original não comprova morte de Hiriko, e a assinatura de uma chefia não substitui o cruzamento de identidade.", "Os dois perfis de Taiyo continuam separados. A natureza do Encouraçado e a identidade de seu eventual operador não foram confirmadas. Avaliações de risco não devem preencher essas lacunas com capacidades ou filiações não demonstradas."]}, {"title": "CONDUTA / DECISÃO E OBJETIVOS DA SDAI", "paragraphs": ["É contida nas manifestações e firme ao transmitir determinações. A precisão dos relatórios serve aos objetivos da SDAI e pode coexistir com decisões extremas; não representa neutralidade política nem oposição à política da organização.", "Informações sobre a perda de custódia de Ariella recebem prioridade. Arvensis exige que a ausência de localização não seja convertida automaticamente em morte, resgate confirmado ou filiação ao grupo de Osaka.", "A situação de Ariella permanece classificada como desaparecida em ação. A SDAI ainda não confirmou se sobreviveu ao acidente ou morreu. A Inteligência aguarda avistamento verificável ou localização que permita esclarecer seu estado; até lá, informes conflitantes não encerram a busca."]}, {"title": "RELAÇÕES DE SERVIÇO / INTELIGÊNCIA E EXECUÇÃO", "paragraphs": ["Takeshi Kanzaki coordena a aplicação das medidas de Segurança dentro de sua cadeia. Naoko Senda conduz as avaliações técnicas da P&D, e Junpei Kurose responde pela supervisão da custódia científica nos limites de seu cargo.", "A chefia de Inteligência consolida fontes e transmite determinações pelos canais responsáveis. A autoria da ordem de abertura da Segunda Fase não torna Arvensis autora dos pareceres científicos de Reika nem testemunha pessoal de todas as ocorrências registradas."]}], "referencesTitle": "RELAÇÕES DE SERVIÇO / CONTATOS DE REFERÊNCIA", "references": [{"id": "FAC-0010", "label": "Grupo de Osaka / composição e vínculos →"}, {"id": "PES-2417", "label": "Ariella Chiyomi / restrição de contato →"}, {"id": "ATV-0049", "label": "Hiriko / identidade em revisão →"}, {"id": "PES-2501", "label": "Takeshi Kanzaki / Segurança →"}], "referencesNote": "As referências indicam relação funcional. Os registros individuais mantêm suas condições de acesso.", "footer": "PES-2503 / ARVENSIS · INTELIGÊNCIA SDAI · ORDEM DE ABERTURA DA SEGUNDA FASE REGISTRADA / 2019", "photo": "assets/3f1a1527245f7fd6c9733569.png", "fields": [["NOME CIVIL", "Marina Azevedo"], ["APELIDO DE CHEFIA", "Arvensis"], ["CARGO", "Chefia de Inteligência / Arvensis"], ["DIVISÃO", "Inteligência SDAI"], ["LOTAÇÃO", "DAE ÁSIA / Distrito de Comando"], ["VÍNCULO", "Quadro regular da SDAI / serviço ativo"], ["INGRESSO NA SDAI", "2007 / quadro de análise"], ["PERMISSÕES", "Autorização do Alto Comando para comandar o protocolo Lua Crescente Vermelha"]]}},{"id": "PES-2504", "title": "Junpei Kurose / Supervisor da custódia científica", "category": "Pessoal", "origin": "SEGURANÇA SDAI / INTERFACE COM P&D / DAE ÁSIA", "access": "Todas as divisões", "level": 2, "recordType": "employee", "summary": "Supervisiona a rotina de Segurança da custódia científica. Controla escoltas, permissões e entregas de turno. É impaciente com discussões que considera repetitivas e tende a reduzir os pesquisadores retidos às tarefas e condições impostas pela SDAI.", "detail": "Cadastro operacional de referência. Atribuições locais da DAE ÁSIA; documentos administrativos completos no diretório de Recursos Humanos.", "employee": {"name": "Junpei Kurose", "displayTitle": "Junpei Kurose", "japaneseName": "黒瀬 淳平", "nativeLang": "ja", "age": "43 anos / cadastro de 2019", "nationality": "Japonesa", "birthplace": "Kobe, Japão", "role": "Supervisor da custódia científica", "division": "Segurança SDAI / interface com P&D", "station": "DAE ÁSIA / Segurança e instalações sob sua responsabilidade", "supervision": "Takeshi Kanzaki / articulação técnica com Naoko Senda", "appointment": "Quadro regular da SDAI / serviço ativo", "capture": "2006 / serviço de Segurança", "previousRole": "Controle de acesso e escolta de pessoal sensível", "clearance": "Permissões próprias de função / não transferidas ao consulente", "status": "Em serviço / lotação na DAE ÁSIA", "serviceLabel": "SERVIÇO ATIVO / QUADRO REGULAR", "emblemKey": "seguranca", "directoryLabel": "SEGURANÇA SDAI / INTERFACE COM P&D / CADASTRO FUNCIONAL", "personnelKind": "PESSOAL / SUPERVISÃO LOCAL", "personalLabel": "INFORMAÇÕES DO FUNCIONÁRIO", "specialty": "Escoltas / registros de custódia / controle de acessos", "custodyRegime": "Serviço regular / sujeito à cadeia de comando", "custodyTitle": "VÍNCULO FUNCIONAL / QUADRO REGULAR", "custodyNote": "Integra o quadro regular da SDAI, com atribuições de serviço e supervisão formal. As permissões do cargo são pessoais e delimitadas; consultar esta ficha não concede acesso aos setores ou autoridade para emitir ordens em seu nome.", "currentWork": "Conferindo escoltas e acessos dos cientistas retidos, os registros anteriores ao transporte de Ariella e as pendências de custódia durante a Segunda Fase. Mantém separadas a supervisão do trabalho de Reika e a ausência de cooperação de Ariella.", "quickSummary": "Supervisiona a rotina de Segurança da custódia científica. Controla escoltas, permissões e entregas de turno. É impaciente com discussões que considera repetitivas e tende a reduzir os pesquisadores retidos às tarefas e condições impostas pela SDAI.", "projects": [{"code": "CST-ROT", "name": "Rotina e escoltas", "work": "Conferir deslocamentos autorizados e passagens de responsabilidade entre equipes.", "state": "EM ATIVIDADE"}, {"code": "CST-ARI", "name": "Histórico de transferência", "work": "Revisar os registros disponíveis anteriores à queda, sem afirmar a recaptura de Ariella.", "state": "EM ATIVIDADE"}, {"code": "CST-FASE", "name": "Cumprimento de determinações", "work": "Conferir acessos e devolução de materiais nos serviços encerrados, conforme ordens dos setores responsáveis.", "state": "EM ATIVIDADE"}], "identifications": [], "sections": [{"title": "PERFIL / SUPERVISÃO DE CUSTÓDIA", "paragraphs": ["Kurose entrou na SDAI em 2006 e passou por postos de controle de acesso antes de assumir supervisão de rotina da custódia científica. Seu cargo é de Segurança, articulado com a equipe de P&D.", "É direto, pouco paciente com explicações longas e preocupado em não deixar um turno sem responsável formal. Não é ex-cobaia nem cientista recuperado da INTERAURA."]}, {"title": "RESPONSABILIDADES / SEGURANÇA E PESQUISA", "paragraphs": ["Conferir escoltas, controlar deslocamentos e registrar a entrega de pessoas e materiais entre setores faz parte de seu trabalho. Necessidades técnicas são encaminhadas à P&D; o supervisor não assina identificações modulares em nome da pesquisadora.", "Responde a Kanzaki na cadeia de Segurança e articula as exigências laboratoriais com Senda. Não substitui as autoridades de comando em ordens de transferência, liberação ou execução."]}, {"title": "REIKA / PRIVILÉGIOS CONDICIONAIS", "paragraphs": ["A rotina de Mizuhara inclui trabalho autorizado e privilégios condicionados ao serviço. Kurose verifica a parte de acesso e escolta, enquanto a qualidade dos pareceres permanece sob avaliação científica.", "Considera suas objeções à Segunda Fase repetitivas e incômodas. Procura interrompê-la e fazê-la retornar às tarefas. A impaciência não elimina o fato de ela continuar produtiva e não constitui, neste cadastro, uma punição disciplinar formal."]}, {"title": "ARIELLA / TRATAMENTO DISTINTO", "paragraphs": ["O histórico de Ariella é de prisão e silêncio, sem colaboração obtida durante aproximadamente 19 anos. Kurose não participou de todo esse período; sua função atual não o transforma em responsável retrospectivo por cada tentativa realizada pela SDAI.", "A expressão vazia e a ausência de resposta causavam desconforto às equipes que lidavam com ela. O supervisor trata isso como comportamento registrado, sem atribuir efeito sobrenatural ao olhar ou afirmar um diagnóstico."]}, {"title": "QUEDA DO TRANSPORTE / CUSTÓDIA INTERROMPIDA", "paragraphs": ["Ariella estava no transporte que caiu em Osaka e segue desaparecida em ação, sem confirmação de vida ou morte. O cadastro não estabelece a participação pessoal de Kurose naquela escolta, nem confirma um agente ou equipe como responsável pela perda de custódia.", "Sua demanda atual é conferir registros e encaminhar divergências pela cadeia competente. Não há recaptura ou óbito que ele possa declarar apenas pela ausência de informação posterior."]}, {"title": "SEGUNDA FASE / ACESSOS E LIMITES", "paragraphs": ["Os encerramentos de serviço devem ser acompanhados pela conferência dos acessos e equipamentos vinculados à custódia. O emprego de Runeko como agente dupla continua assunto da cadeia operacional competente, sem transferência automática de comando para Kurose.", "A proibição de contato de Ariella com ex-cobaias permanece aplicável. O supervisor não pode autorizar uma exceção em troca de informação ou de cooperação científica."]}], "referencesTitle": "RELAÇÕES DE SERVIÇO / CONTATOS DE REFERÊNCIA", "references": [{"id": "PES-2501", "label": "Takeshi Kanzaki / superior de Segurança →"}, {"id": "PES-2502", "label": "Naoko Senda / coordenação científica →"}, {"id": "PES-2418", "label": "Reika Mizuhara / rotina supervisionada →"}, {"id": "PES-2417", "label": "Ariella Chiyomi / desaparecida →"}], "referencesNote": "As referências indicam relação funcional. Os registros individuais mantêm suas condições de acesso.", "footer": "PES-2504 / DAE ÁSIA · QUADRO REGULAR · SUPERVISÃO LOCAL · CADASTRO OPERACIONAL / 2019", "photo": "assets/f803e15d7828fd047b94ab0c.png", "fields": [["CARGO", "Supervisor da custódia científica"], ["DIVISÃO", "Segurança SDAI / interface com P&D"], ["LOTAÇÃO", "DAE ÁSIA / Segurança e instalações sob sua responsabilidade"], ["SUPERIOR FUNCIONAL", "Takeshi Kanzaki / articulação técnica com Naoko Senda"], ["VÍNCULO", "Quadro regular da SDAI / serviço ativo"], ["INGRESSO NA SDAI", "2006 / serviço de Segurança"], ["EXPERIÊNCIA ANTERIOR", "Controle de acesso e escolta de pessoal sensível"], ["PERMISSÕES", "Permissões próprias de função / não transferidas ao consulente"]]}},{"id": "PES-2418", "title": "Dra. Reika Mizuhara / pesquisadora de P&D", "category": "Pessoal", "origin": "P&D SDAI / QUADRO CIENTÍFICO LEGADO", "access": "Todas as divisões", "level": 2, "recordType": "employee", "summary": "Cientista japonesa da antiga INTERAURA, capturada em 2000 e mantida sob custódia na P&D SDAI. Confirmou MOD-11, MOD-28 e MOD-67. Produtiva e reservada, apresenta nervosismo na fala e sinais aparentes de trauma. Adverte contra a eliminação coletiva dos ex-cobaias na Segunda Fase.", "detail": "Cadastro funcional ativo. Colaboração técnica compulsória; privilégios condicionados ao cumprimento das atribuições. Neutralidade declarada não equivale a liberdade ou adesão ideológica.", "employee": {"name": "Reika Mizuhara", "japaneseName": "水原 玲香", "age": "46 anos / cadastro de 2019", "nationality": "Japonesa", "birthplace": "Kyoto, Japão", "civilStatus": "Dados civis complementares reservados", "role": "Pesquisadora sênior / identificação e compatibilidade modular", "division": "Pesquisa e Desenvolvimento / P&D", "station": "DAE ÁSIA / Distrito de Pesquisa", "supervision": "Coordenação científica de P&D / custódia da Segurança SDAI", "appointment": "Vínculo técnico compulsório / colaboração supervisionada", "status": "Em serviço / sob custódia administrativa", "previousRole": "INTERAURA / documentação clínica e registro de módulos", "capture": "Primeiro semestre de 2000 / operações pós-Incidente", "clearance": "Acesso técnico setorial / acompanhado; sem prerrogativa de comando", "review": "Acompanhamento contínuo de produtividade e conduta", "photo": "assets/cf38d2a494faa5f671362c24.png", "projects": [{"code": "ID-MOD", "name": "Identificação de ex-cobaias", "work": "Confrontar registros clínicos recuperados, sinais físicos e históricos de procedimentos. Emitir pareceres de correspondência modular e registrar lacunas documentais.", "state": "EM ATIVIDADE"}, {"code": "ARQ-INT", "name": "Reconstrução do acervo INTERAURA", "work": "Reordenar fragmentos do Projeto de Integração Modular; separar códigos antigos, nomes declarados e hipóteses ainda não verificadas.", "state": "EM REVISÃO"}, {"code": "COMP-MOD", "name": "Compatibilidade e preservação de registros", "work": "Avaliar interfaces de diagnóstico recuperadas e a integridade de dados de sessões antigas, em coordenação com a equipe de equipamentos legados.", "state": "ANÁLISE SUPERVISIONADA"}, {"code": "CON-SEG", "name": "Revisão científica de contenção", "work": "Conferir cadastros e condições documentadas de contidos. Preparar o encerramento e a preservação dos arquivos solicitados pela Segunda Fase, sem poder de suspender ordens operacionais.", "state": "PRIORIDADE ATUAL"}, {"code": "INT-LOGIN", "name": "Computador INTERAURA / credencial desaparecida", "work": "Ajudou a SDAI com seu antigo login, permitindo consultas valiosas. O cadastro deixou de ser reconhecido; a causa permanece em investigação, sem autoria de exclusão demonstrada.", "state": "ACESSO ANTERIOR PERDIDO"}], "identifications": [{"id": "ATV-0011", "name": "Billy Black / MOD-11", "note": "Correspondência modular confirmada após captura; nome declarado pelo contido não equivale a identidade civil verificada. Registro anterior à criogenia de 14/06/2000."}, {"id": "CNT-0067", "name": "Gabrijela Vlasic / MOD-67", "note": "Correspondência com o registro legado confirmada após avaliação sob custódia, antes da criogenia de 22/06/2000."}, {"id": "CNT-0028", "name": "Runeko / MOD-28", "note": "Confirmação após a captura na primeira perseguição posterior ao massacre do Clube da Noite. O parecer identifica o módulo; não determina filiação à Siegel ou ao grupo de Osaka."}], "sections": [{"title": "PERFIL FUNCIONAL / ESPECIALIDADE", "paragraphs": ["Reika Mizuhara é uma pesquisadora japonesa com formação em neurofisiologia aplicada e experiência em documentação de integração biológica e tecnológica. Seu trabalho concentra-se em reconhecer correspondências entre pessoas sob custódia e os registros fragmentados dos antigos módulos da INTERAURA.", "É metódica nas avaliações e costuma devolver relatórios com anotações à margem antes de assiná-los. Faz mais do que fala: mantém produtividade elevada e entrega registros organizados, mas demonstra nervosismo sempre que precisa se expressar verbalmente. A voz hesita, as frases são interrompidas por pausas e as palavras parecem escolhidas com receio. O comportamento sugere trauma, sem diagnóstico ou origem confirmados neste cadastro. Emprega nomes declarados junto dos códigos de módulo, preservando ambos no arquivo; isso não verifica, por si só, a identidade civil."]}, {"title": "ANTECEDENTES / ANTIGA INTERAURA", "paragraphs": ["Integrava, desde 1996, o núcleo de documentação clínica ligado ao Projeto de Integração Modular. Acompanhava a catalogação de respostas neurológicas, a comparação de prontuários e a revisão dos registros produzidos após os procedimentos. Não era diretora do projeto nem detinha autoridade equivalente à de Adam ou Ariella Chiyomi.", "Sobreviveu ao Incidente de 29/12/1999 e deixou a instalação durante sua desorganização. Parte de seu conhecimento decorre de experiência direta; outra parte depende de arquivos recuperados posteriormente. Sua passagem pela INTERAURA não lhe concede conhecimento integral sobre todos os cem módulos, sobre os módulos alfabéticos ou sobre todos os projetos da corporação."]}, {"title": "CAPTURA / INCORPORAÇÃO À SDAI", "paragraphs": ["Foi localizada no primeiro semestre de 2000, já após a constituição da SDAI, durante a busca por pessoal científico da antiga INTERAURA. Interrogada sobre registros de integração e identificação de cobaias, demonstrou utilidade imediata na leitura de arquivos danificados.", "A SDAI reteve a pesquisadora e passou a empregá-la em avaliações técnicas. Sua permanência no quadro não decorre de contratação livre: o vínculo foi estabelecido sob custódia e mantido pela necessidade de acesso ao seu conhecimento. A cronologia de captura antecede os pareceres de identificação emitidos antes das criogenias de junho de 2000."]}, {"title": "CUSTÓDIA / PRIVILÉGIOS CONDICIONAIS", "paragraphs": ["Pesquisadores recuperados da INTERAURA são mantidos, na prática, como prisioneiros com privilégios. Mizuhara dispõe de alojamento individual no setor supervisionado, alimentação regular, acompanhamento médico e material de consulta autorizado. Trabalha em laboratório equipado e pode solicitar insumos por intermédio de sua coordenação.", "Os benefícios dependem da entrega de pesquisas, da preservação de registros e da observância das ordens de serviço. A pesquisadora não escolhe livremente sua lotação, não pode deixar a DAE e não possui comunicação externa sem autorização. Transferências de setor exigem registro e acompanhamento quando determinado pela Segurança.", "O jaleco, a identificação funcional e o acesso a instrumentos não anulam a custódia. O emblema de P&D indica lotação científica; não representa patente militar, liberdade pessoal ou autorização de comando."]}, {"title": "POSTURA INSTITUCIONAL / NEUTRALIDADE DECLARADA", "paragraphs": ["Mizuhara mantém reserva diante da legitimidade da SDAI e evita adesão pública à sua propaganda. A neutralidade declarada é uma postura de sobrevivência sob custódia, compatível com o cumprimento rigoroso do trabalho; não significa ausência de opinião, tranquilidade emocional ou concordância com todas as ordens.", "Sua conduta verbal é visivelmente nervosa, mesmo em assuntos rotineiros. Fala pouco, hesita e por vezes refaz uma frase antes de concluí-la. Os registros descrevem sinais aparentes de trauma, sem estabelecer causa, responsável ou diagnóstico clínico. Sua capacidade de executar pesquisas permanece preservada: a insegurança na fala não é tratada como incapacidade técnica.", "Desde a declaração da Segunda Fase da Lua Crescente Vermelha, tenta reiteradamente argumentar que eliminar todos os ex-cobaias será uma decisão péssima, prejudicará a própria SDAI e poderá provocar problemas maiores. Não consegue comprovar esse temor: trata-se de uma convicção apreensiva, não de uma conclusão demonstrada por pesquisa. Fala com nervosismo, hesita e procura terminar o raciocínio, embora continue trabalhando sob supervisão.", "Não há sabotagem, fuga ou colaboração clandestina comprovadas neste cadastro. A colaboração prestada não comprova adesão ideológica, e as objeções verbais não demonstram, por si só, preparação de uma ação contra a SDAI. A existência desses registros não constitui aceitação do pedido pelo comando.", "Os supervisores passaram a considerar suas objeções repetitivas e incômodas e procuram mantê-la calada durante as discussões sobre o protocolo. Interrompem suas tentativas de insistir no assunto e a direcionam de volta ao trabalho. A postura registra impaciência com suas manifestações, sem punição disciplinar específica ou alteração das ordens de execução."]}, {"title": "MÉTODO / ALCANCE DOS PARECERES", "paragraphs": ["A identificação combina sinais físicos, histórico de procedimentos, fragmentos de prontuários, respostas registradas e, quando disponível e pertinente, comparação de material de referência. Sem amostras ou documentação adequadas, a avaliação permanece limitada. Aparência semelhante ou habilidade aurítica parecida não bastam isoladamente.", "Os pareceres distinguem correspondência confirmada, compatibilidade parcial e identificação inconclusiva. Reconhecer um módulo não recupera automaticamente memórias, não comprova lealdade e não estabelece natureza ou capacidade que os registros não sustentem.", "As identificações de MOD-11, MOD-28 e MOD-67 estão atribuídas a ela nas respectivas fichas. Isso não encerra outras investigações: a identificação de Hiriko permanece em revisão nos termos de seu dossiê, sem conversão automática de MOD-49 em MOD-49-1."]}, {"title": "ROTINA / LOCAL DE TRABALHO", "paragraphs": ["Atua no Distrito de Pesquisa da DAE ÁSIA, em períodos de laboratório e revisão documental distribuídos pela coordenação. A posição indicada é lotação funcional, não rastreamento em tempo real. Chamadas à Contenção dependem da autorização do setor responsável.", "Antes de uma avaliação, solicita a ficha de admissão, os registros já disponíveis e as limitações de aproximação. Após cada sessão, entrega uma cópia do parecer à coordenação e outra ao arquivo científico. A Segurança recebe as informações operacionais pertinentes; a pesquisadora não controla a destinação final dos contidos."]}, {"title": "SEGUNDA FASE / PRIORIDADES DE SERVIÇO", "paragraphs": ["Com a declaração da Segunda Fase da Lua Crescente Vermelha, recebeu prioridade para revisar identificações pendentes, consolidar versões dos prontuários e preservar os registros requeridos pelas determinações de encerramento. As execuções indicadas em dez horas nas fichas de contenção permanecem pendentes nesta atualização.", "Mizuhara tenta falar repetidamente contra a eliminação de todos os ex-cobaias. Sente que a medida será uma decisão péssima para a SDAI e teme problemas maiores, mas não dispõe de comprovação para essa avaliação. Sua apreensão não é tratada como informação privilegiada, conhecimento de um mecanismo oculto ou previsão confirmada. A supervisão considera a insistência incômoda, tenta encerrar suas intervenções e exige que retome as tarefas. O trabalho prossegue sem alteração das ordens vigentes.", "Pode registrar objeções científicas e pedidos de complementação, mas não possui poder para suspender execuções, encerrar a custódia de ex-cobaias ou alterar decisões do Alto Comando. As ordens de agente dupla e de encerramento de Runeko pertencem à cadeia operacional competente. Sua advertência não altera as diretrizes atualmente exibidas nas fichas de contenção.", "Mizuhara está cadastrada como funcionária científica sob custódia, não como módulo experimental. Este registro não lhe atribui a ordem de execução aplicada aos ex-cobaias contidos. Sua permanência no quadro continua sujeita à avaliação da SDAI."]}, {"title": "ACESSOS / RESTRIÇÕES DE FUNÇÃO", "paragraphs": ["Recebe permissões setoriais para os arquivos e equipamentos necessários a cada tarefa. Essas permissões são supervisionadas e não constituem acesso irrestrito à rede, ao Alto Comando, aos sistemas de navegação ou aos meios de fuga. Não pode autorizar liberações, transferências ou intervenções armadas.", "Este cadastro é consultável por credenciais operacionais de nível 2. A consulta à ficha não transfere ao leitor as permissões laboratoriais da pesquisadora nem desbloqueia a documentação restrita dos equipamentos legados."]}, {"title": "AVALIAÇÃO DE SERVIÇO / OBSERVAÇÕES DA COORDENAÇÃO", "paragraphs": ["Produção considerada consistente nas atividades de identificação e reconstrução de registros. Evita preencher lacunas com suposições e tende a exigir segunda conferência antes de vincular um indivíduo a um módulo. Executa mais do que verbaliza; nervosismo e hesitação aparecem principalmente quando precisa apresentar suas conclusões em voz alta.", "Os relatos de comportamento registram aparente trauma, nervosismo na fala e manifestações reiteradas contra as execuções da Segunda Fase. Sua advertência permanece sem comprovação. Os supervisores procuram silenciar suas intervenções por considerá-las repetitivas e inoportunas. Não há diagnóstico clínico consolidado ou punição disciplinar específica registrada; a postura da supervisão não representa acolhimento do pedido.", "Mantêm-se tarefas delimitadas, revisão por outro pesquisador e acompanhamento de custódia. A manutenção dos privilégios segue condicionada ao serviço. O cadastro não declara absolvição por seu trabalho anterior na INTERAURA, confiança política irrestrita ou acolhimento das objeções pelo Alto Comando."]}, {"title": "IIM / TENTATIVAS SEM RESULTADO", "paragraphs": ["Foi empregada na investigação da IIM, interface criada por Ariella e Adam Chiyomi. A SDAI não conseguiu obter operação útil do equipamento. Apesar da insistência e dos incentivos da supervisão, Reika aparentou não se empenhar nesse estudo de propósito. A impressão não comprova sabotagem nem domínio oculto da interface.", "A ausência de avanço na IIM é distinta dos pareceres de identificação que efetivamente produziu. As confirmações de MOD-11, MOD-28 e MOD-67 permanecem válidas e não decorreram de operação bem-sucedida da cadeira. Consultar LEG-0041."]}, {"title": "COMPUTADOR INTERAURA / ACESSO ANTERIOR E PERDA DO CADASTRO", "paragraphs": ["Forneceu seu antigo login e auxiliou a SDAI a obter informações valiosas da rede da INTERAURA. Essa colaboração efetivamente prestada é distinta da ausência de resultados na investigação da IIM.", "O cadastro desapareceu e a credencial não permite mais autenticação. A SDAI não determinou se houve falha crítica do servidor ou exclusão manual. O fato de o login pertencer a Reika não comprova sua responsabilidade pelo desaparecimento. Os servidores ainda não foram totalmente recuperados; uma futura expedição à antiga base subterrânea será necessária. Consultar LEG-0042. A perda do login encerrou o acesso da SDAI à rede, inclusive a consulta a novos dados e o acompanhamento de atualizações; as cópias anteriormente preservadas continuam disponíveis."]}], "currentWork": "Revisando identificações e prontuários dos ex-cobaias sob custódia, consolidando arquivos da INTERAURA e preservando registros solicitados pela Segunda Fase. Continua entregando o trabalho, embora tente advertir contra a execução coletiva.", "quickSummary": "Cientista japonesa da antiga INTERAURA, mantida pela SDAI como pesquisadora de P&D sob custódia e com privilégios condicionais. Competente e produtiva, é reservada, nervosa ao falar e aparentemente traumatizada. Considera a eliminação dos ex-cobaias uma decisão péssima, mas não consegue comprovar seu temor.", "references": [{"id": "LEG-0008", "label": "Arquivos do Projeto de Integração Modular →"}, {"id": "LEG-0041", "label": "IIM / estudo e custódia do equipamento →"}, {"id": "LEG-0042", "label": "Computador INTERAURA / perda do cadastro de acesso →"}]}},{"id": "LEG-0041", "title": "IIM / Interface de Integração Modular", "category": "Ativos Legados", "origin": "INTERAURA", "access": "P&D", "level": 4, "recordType": "legacyEquipment", "summary": "Interface original criada por Ariella e Adam Chiyomi. Cadeira de diagnóstico e reconfiguração de ex-cobaias da INTERAURA; nenhuma operação útil obtida pela SDAI. Exemplar preservado sob contenção tecnológica na DAE ÁSIA.", "detail": "Acervo INTERAURA / preservação prioritária. Pesquisa inconclusiva; acesso técnico P&D / nível 4.", "equipment": {"photo": "assets/dcb215b16df00d501aca2720.png", "emblem": "assets/c32cc27a9eca9e05b3c0dba3.png", "fields": [["DESIGNAÇÃO", "IIM - Interface de Integração Modular"], ["AUTORES", "Ariella Chiyomi / Adam Chiyomi"], ["ORIGEM", "INTERAURA / Projeto de Integração Modular"], ["CUSTÓDIA", "DAE ÁSIA / Complexo de Ativos Legados"], ["ESTUDO SDAI", "Sem operação útil obtida"], ["DESTINAÇÃO", "Preservação para investigação futura"]], "sections": [{"title": "IDENTIFICAÇÃO / INTERFACE DE INTEGRAÇÃO MODULAR", "paragraphs": ["A IIM - Interface de Integração Modular - é um equipamento original da INTERAURA desenvolvido por Ariella Chiyomi em conjunto com Adam Chiyomi para o Projeto de Integração Modular. Nos registros informais do projeto, é referida simplesmente como a cadeira. Foi recuperada após o Incidente e permanece sob custódia da SDAI.", "A estrutura reúne um assento adaptativo, apoios articulados, contatos próximos à cabeça, sensores distribuídos e conexões entre o corpo e os sistemas de leitura. O emblema original da INTERAURA permanece na carcaça como identificação de procedência. A incorporação ao inventário da SDAI não altera sua autoria.", "A designação módulo é mantida quando reproduz códigos e terminologia técnica da INTERAURA. Nos registros operacionais da SDAI, os indivíduos vinculados ao projeto são classificados como ex-cobaias, espécimes ou ativos experimentais. A custódia e a avaliação são conduzidas conforme essa classificação institucional."]}, {"title": "FINALIDADE LEGADA / DIAGNÓSTICO E RECONFIGURAÇÃO", "paragraphs": ["A documentação recuperada descreve diagnóstico profundo, leitura de alterações da integração, detecção de incompatibilidades e alteração de parâmetros dos ex-cobaias da INTERAURA. O equipamento teria sido concebido para interagir com a associação entre organismo, componentes integrados e atividade aurítica dos ex-cobaias.", "Essas funções pertencem aos registros da INTERAURA. A SDAI não conseguiu reproduzi-las de forma útil ou validada. Não há, neste dossiê, demonstração de recuperação de memórias, criação de poderes, reversão da integração ou restauração funcional de um ex-cobaia. O alcance real das modificações permanece desconhecido para a organização."]}, {"title": "RECUPERAÇÃO / VALOR DO EXEMPLAR ORIGINAL", "paragraphs": ["A unidade foi incorporada ao acervo de equipamentos recuperados da antiga corporação. Seu histórico completo de transporte e a localização interna detalhada permanecem em documentação restrita. A custódia atual pertence ao Complexo de Ativos Legados da DAE ÁSIA, sob responsabilidade conjunta de P&D e Segurança.", "A SDAI não conseguiu reconstruir uma interface equivalente nem substituir o exemplar original por um sistema próprio funcional. Não há autorização de descarte, desmontagem irreversível ou reaproveitamento de suas peças como componentes comuns."]}, {"title": "ESTUDOS SDAI / NENHUMA OPERAÇÃO ÚTIL OBTIDA", "paragraphs": ["A SDAI tentou estudar as capacidades da cadeira, interpretar seus controles e obter uma sequência de operação reproduzível. As tentativas não produziram diagnóstico modular validado nem reconfiguração bem-sucedida. O registro permanece sem resultado operacional aproveitável.", "Inspeções, documentação da carcaça e eventuais respostas de componentes auxiliares não equivalem a domínio da interface. Uma alimentação elétrica, um indicador ou uma resposta parcial não devem ser registrados como execução das funções descritas nos arquivos legados.", "A ausência de resultados não comprova que a cadeira seja incapaz de funcionar. Também não demonstra, por si só, defeito irreparável: permanecem abertas lacunas de procedimento, compatibilidade, alimentação aurítica e interpretação dos sistemas originais."]}, {"title": "ARIELLA CHIYOMI / CRIADORA SEM COLABORAÇÃO", "paragraphs": ["A condição de cocriadora tornou Ariella uma fonte prioritária para as tentativas de interpretação da IIM. A SDAI procurou obter sua ajuda durante a custódia, mas ela não forneceu qualquer palavra, instrução, procedimento ou auxílio. A inclusão de seu nome na pesquisa representa uma tentativa da organização, não serviço prestado pela cientista.", "Esse fracasso integra os aproximadamente 19 anos de silêncio e ausência de colaboração. Sua presença sob custódia não permitiu à SDAI operar o equipamento. Atualmente, Ariella está desaparecida em ação após a queda do transporte em Osaka, sem confirmação de vida ou morte; não está disponível para novas sessões. Adam Chiyomi, cocriador da IIM, está morto. Este registro não estabelece data, circunstâncias ou responsável por sua morte."]}, {"title": "REIKA MIZUHARA / APOIO TÉCNICO SEM AVANÇO", "paragraphs": ["Reika Mizuhara foi empregada nas tentativas de estudo e interpretação do equipamento. Apesar das solicitações, incentivos e insistência da supervisão para que ajudasse a fazer a pesquisa avançar, não houve resultado. Os responsáveis registraram a impressão de que ela não se empenhava nesse trabalho de propósito.", "A suspeita de falta deliberada de esforço é uma avaliação de conduta da SDAI, sem comprovação de sabotagem ou demonstração de que Reika conheça a sequência de operação. Ela não é autora da IIM e não possui domínio confirmado sobre sua interface. O episódio não invalida suas identificações científicas de MOD-11, MOD-28 e MOD-67, realizadas por outros meios.", "O nervosismo verbal e a aparente condição traumática da pesquisadora continuam registrados em sua ficha funcional. As dificuldades deste estudo não devem ser transformadas em diagnóstico clínico ou incapacidade geral para pesquisar."]}, {"title": "ALIMENTAÇÃO / SUBSISTEMA AURÍTICO", "paragraphs": ["Os registros técnicos associam a interação profunda com um ex-cobaia a um subsistema alimentado por energia aurítica armazenada em cápsulas. A alimentação elétrica convencional atende sistemas auxiliares, processamento e mecanismos, mas não substitui essa etapa aurítica.", "O conceito de alimentação não constitui uma ativação bem-sucedida pela SDAI. Compatibilidade de recipientes, parâmetros de fornecimento, consumo e sequência de uso não foram validados pela equipe. Não presumir que qualquer cápsula comercial, inclusive modelos encontrados no mercado negro, seja automaticamente adequada.", "Este registro não atribui a tecnologia da IIM aos Saqueadores nem estabelece que a INTERAURA empregava o padrão de cápsulas fabricado atualmente pela gangue. Não há informação consolidada nesta ficha sobre quem possa pretender obter energia ou recuperar a cadeira."]}, {"title": "PRESERVAÇÃO / CONTENÇÃO DO ATIVO", "paragraphs": ["A contenção da IIM é uma medida de custódia tecnológica: o objeto deve permanecer isolado de uso não autorizado e preservado para investigação futura. Não está classificado como organismo vivo nem como ex-cobaia. A importância do equipamento decorre de sua origem e do potencial ainda não compreendido de modificar os ex-cobaias da INTERAURA.", "Intervenções exigem autorização técnica, registro de responsáveis e acompanhamento da Segurança. Conservar conectores, módulos de leitura, circuitos e identificadores originais. Procedimentos invasivos dependem de análise que justifique o risco de perder um exemplar cuja interface a SDAI não sabe reconstruir.", "A presença de ex-cobaias no mesmo complexo não autoriza conectá-los ao equipamento. Ensaios com ex-cobaias exigem determinação específica; a descrição de uma função nos arquivos não fornece um procedimento seguro ou validado."]}, {"title": "SEGUNDA FASE / CUSTÓDIA MANTIDA", "paragraphs": ["A Segunda Fase da Lua Crescente Vermelha não transforma a IIM em material de descarte. A determinação de execução dos ex-cobaias contidos não é uma ordem de destruir equipamentos legados. A unidade permanece preservada para que pesquisas futuras possam esclarecer sua operação e o que é capaz de fazer com os ex-cobaias da INTERAURA.", "A guarda do equipamento não suspende execuções nem cria uma exceção individual para um ex-cobaia. A proibição de contato de Ariella com qualquer ex-cobaia permanece absoluta; a alegação de necessidade científica não autoriza reunir a criadora, um ex-cobaia e a cadeira."]}, {"title": "PARECER ATUAL / PRESERVAR SEM DECLARAR DOMÍNIO", "paragraphs": ["Estado do estudo: inconclusivo. Operação modular pela SDAI: não obtida. Reconstituição funcional da interface original: não obtida. Situação patrimonial: exemplar preservado sob contenção tecnológica.", "O valor estratégico permanece elevado apesar da ausência de resultados. Manter o ativo, os arquivos associados e o histórico de tentativas. Qualquer avanço futuro deve distinguir uma resposta observada de uma função efetivamente demonstrada."]}], "custodyEmblem": "assets/e4249b005919d080af0c4ce1.svg", "quickSummary": "Criada por Ariella e Adam Chiyomi, a IIM foi desenvolvida para diagnosticar e modificar a integração dos ex-cobaias da INTERAURA. A SDAI não conseguiu obter nenhuma operação útil: Ariella nunca colaborou, e as tentativas de estudo com Reika não avançaram. A cadeira permanece preservada sob contenção tecnológica na DAE ÁSIA para investigação futura."}},{"id": "LEG-0042", "title": "Computador da INTERAURA / estação INT-JP-04", "category": "Ativos Legados", "origin": "INTERAURA", "access": "P&D", "level": 4, "recordType": "legacyComputer", "summary": "Estação original com IROS 3.7.12. A SDAI obteve informações valiosas usando o login de Reika Mizuhara, mas o cadastro desapareceu. Servidores incompletos; recuperação exige futura expedição à base subterrânea abandonada e perigosa.", "detail": "Computador preservado / autenticação perdida. Falha crítica ou exclusão manual sob investigação.", "equipment": {"photo": "assets/8e727db90f280ee6a8a38838.png", "custodyEmblem": "assets/e4249b005919d080af0c4ce1.svg", "currentWork": "Estação preservada sob custódia. Após o desaparecimento do login de Reika, a SDAI perdeu o acesso à rede INTERAURA e não consegue consultar novos dados nem acompanhar suas atualizações. A causa permanece indeterminada.", "quickSummary": "Reika forneceu seu login e permitiu à SDAI extrair informações valiosas da rede INTERAURA. O desaparecimento do cadastro encerrou esse acesso, inclusive o acompanhamento de novas atualizações. Restam as cópias já preservadas. Parte dos servidores continua na base subterrânea abandonada e perigosa; recuperá-los exige uma futura expedição.", "fields": [["IDENTIFICADOR LEGADO", "INT-JP-04"], ["SISTEMA", "IROS 3.7.12 / INTERAURA"], ["CUSTÓDIA", "DAE ÁSIA / Complexo de Ativos Legados"], ["ACESSO ANTERIOR", "Login fornecido por Reika Mizuhara"], ["AUTENTICAÇÃO ATUAL", "Cadastro não localizado / login indisponível"], ["RECUPERAÇÃO", "Servidores incompletos / expedição futura necessária"]], "sections": [{"title": "IDENTIFICAÇÃO / ESTAÇÃO ORIGINAL DA INTERAURA", "paragraphs": ["O ativo consiste em uma estação de trabalho original da INTERAURA, recuperada e mantida no Complexo de Ativos Legados da DAE ÁSIA. O conjunto conserva monitor de tubo, unidade de processamento, teclado físico e o identificador corporativo de origem. A aparência envelhecida não deve ser tomada como ausência de valor estratégico.", "O equipamento executa o INTERAURA Research Operating System, IROS 3.7.12, associado ao identificador INT-JP-04 nos registros recuperados. A interface, os diretórios e os procedimentos de autenticação pertencem ao ambiente proprietário da antiga corporação. O ativo não corresponde à totalidade dos servidores da INTERAURA."]}, {"title": "ACESSO ANTERIOR / CREDENCIAL FORNECIDA POR REIKA", "paragraphs": ["A Dra. Reika Mizuhara forneceu seu login da antiga INTERAURA e auxiliou as primeiras sessões de consulta da SDAI. Durante um período, esse acesso permitiu obter informações valiosas sobre pesquisas, referências científicas e registros dos ex-cobaias. A colaboração foi efetiva e está registrada separadamente das tentativas sem resultado envolvendo a IIM.", "A credencial permitia acesso ao conteúdo disponível e às permissões daquele cadastro. Não restaurava todos os volumes, não supria arquivos ausentes nem convertia Reika em administradora de toda a rede. Não se atribui a Ariella Chiyomi participação nessas sessões: ela permaneceu sem fornecer qualquer ajuda à SDAI."]}, {"title": "SERVIDORES / RECUPERAÇÃO INCOMPLETA", "paragraphs": ["O ambiente consultado permanece incompleto. A estação é um ponto de acesso a cópias, índices e serviços legados; o equipamento apreendido não contém uma reconstrução integral da infraestrutura subterrânea. Parte do acervo depende de volumes e servidores ainda não recuperados.", "Uma cópia do ambiente de recuperação indicava servidor parcialmente operacional, integridade de 31%, sete volumes indisponíveis e indexação em andamento. Esses números são indicadores preservados daquele ambiente, não uma medição atual garantida de toda a rede. O último backup íntegro indicado era de 28/12/1999.", "A referência 29/12/1999 - 03:42 corresponde ao estado histórico exibido pelo sistema. Não constitui a data atual da operação SDAI, em 2019, nem comprova que todos os registros tenham deixado de receber sinais posteriores ao Incidente."]}, {"title": "PERDA DE AUTENTICAÇÃO / CADASTRO NÃO LOCALIZADO", "paragraphs": ["O login de Reika deixou misteriosamente de ser reconhecido. O cadastro anteriormente empregado nas consultas não é mais localizado pelo mecanismo de autenticação, e não é possível retomar a sessão por essa credencial. A ocorrência é tratada como desaparecimento do cadastro, sem uma causa homologada. Desde essa perda, a SDAI não possui mais acesso à rede INTERAURA. Não há canal alternativo disponível para novas consultas ou acompanhamento de atualizações.", "A falha não é apresentada como simples esquecimento de senha. A SDAI considera duas linhas principais: erro crítico ou corrupção no servidor da INTERAURA; ou exclusão manual do registro por um operador com acesso suficiente. Nenhuma hipótese foi confirmada.", "Não foi identificado responsável, terminal de origem ou cadeia de comandos que demonstre exclusão deliberada. A colaboração anterior de Reika e o fato de a credencial pertencer a ela não comprovam que a pesquisadora tenha apagado o próprio cadastro. Também não se atribui a ocorrência a Ariella, Adam ou a um ex-cobaia sem evidência."]}, {"title": "INFORMAÇÕES OBTIDAS / PRESERVAÇÃO DAS CÓPIAS", "paragraphs": ["As informações já extraídas pela SDAI continuam relevantes. Cópias, anotações de sessão e pareceres produzidos antes da perda de acesso permanecem no acervo, dentro do que foi efetivamente preservado. A impossibilidade de novo login não apaga automaticamente as informações anteriormente recuperadas.", "A documentação contém lacunas e dados históricos que exigem comparação com ocorrências atuais. Identificação de um código de módulo, último estado vital recebido e situação operacional contemporânea são campos distintos. Não completar arquivos ausentes com conclusões derivadas somente da aparência ou de uma manifestação aurítica semelhante.", "Os códigos MOD são conservados para correspondência documental. A classificação institucional utilizada pela SDAI permanece ex-cobaias da INTERAURA, sem que o vocabulário dos antigos pesquisadores determine as ordens atuais de captura, contenção ou eliminação."]}, {"title": "SINCRONIZAÇÃO LEGADA / REGISTROS ANTERIORES À PERDA DE ACESSO", "paragraphs": ["Os arquivos anteriormente consultados descrevem prontuários de preenchimento manual com exceções ligadas à telemetria individual, incluindo estado vital e vínculo com Contemplador. Essas informações documentam o funcionamento conhecido da rede antes da perda de acesso; não representam acompanhamento atual pela SDAI.", "O óbito de Albert Magnar / MOD-35 foi registrado por sincronização no sistema legado e cruzado pela SDAI com o desfecho da primeira perseguição em Osaka. Essa confirmação já havia sido obtida e permanece preservada. O evento ocorreu antes da Segunda Fase; não é um óbito atribuído ao Incidente de 1999.", "Depois que o login desapareceu, a SDAI deixou de conseguir acessar a rede e acompanhar novas alterações. As cópias anteriores não são uma fonte de atualização em tempo real. A situação atual dos servidores e a continuidade interna de seus serviços não podem ser verificadas por este terminal."]}, {"title": "BASE SUBTERRÂNEA / RECUPERAÇÃO FUTURA DOS SERVIDORES", "paragraphs": ["A recuperação dos servidores remanescentes exige uma futura expedição à antiga base subterrânea da INTERAURA. A instalação está abandonada, é de difícil passagem e permanece perigosa. A SDAI não dispõe, por este cadastro, de uma rota integralmente segura para alcançar os sistemas de origem.", "A proposta exige reconhecimento, avaliação das passagens, equipes de proteção e recursos técnicos para retirada e preservação dos equipamentos. Não registrar a necessidade de expedição como operação já realizada, ordem de partida emitida ou recuperação garantida.", "A retirada indiscriminada de componentes pode comprometer dados ou interromper serviços residuais. O interesse prioritário é recuperar os servidores e sua documentação de forma que permita estudar a rede e reconstruir o acervo, não somente transportar carcaças para a DAE."]}, {"title": "CUSTÓDIA / VALOR ESTRATÉGICO MANTIDO", "paragraphs": ["O computador permanece preservado sob custódia técnica. A perda de autenticação não autoriza descarte, restauração destrutiva ou substituição do sistema original. A estação ainda conserva valor como interface, fonte de vestígios e referência da arquitetura da antiga rede.", "Manter os registros das tentativas e preservar o estado encontrado. Alterações no equipamento devem ser documentadas pela P&D e acompanhadas pela Segurança. A ficha não fornece credencial alternativa funcional nem demonstra acesso administrativo recuperado.", "O ativo permanece distinto da IIM. O computador permite consulta ao ambiente legado dentro das condições disponíveis; possuir a estação não fornece automaticamente a sequência de operação da cadeira nem demonstra que as duas unidades estejam atualmente conectadas."]}, {"title": "PARECER ATUAL / AUTORIA DO DESAPARECIMENTO INDETERMINADA", "paragraphs": ["Situação: computador preservado; servidores parcialmente recuperados; acesso SDAI à rede INTERAURA interrompido após o desaparecimento do login de Reika. Sem novas consultas ou acompanhamento de atualizações. Causa da perda de cadastro: não determinada. Hipóteses principais: falha crítica do servidor ou exclusão manual.", "Prioridades: preservar os dados obtidos, localizar vestígios da antiga credencial, reconstruir a extensão da infraestrutura ausente e preparar os requisitos para a futura expedição. Não declarar sabotagem identificada, acesso restaurado ou recuperação total sem comprovação."]}]}},{"id": "LEG-0043", "title": "A.C.A / Arma de Carga Aurítica", "category": "Ativos Legados", "origin": "INTERAURA", "access": "P&D", "level": 4, "recordType": "legacyWeapon", "summary": "Arma de Carga Aurítica experimental da INTERAURA, de funcionamento análogo a uma railgun. Recuperada num depósito auxiliar em Osaka e mantida em contenção tecnológica na DAE ÁSIA; sem homologação para emprego operacional.", "detail": "Protótipo de armamento aurítico / custódia P&D e Segurança. Autoria individual e desempenho integral não consolidados.", "equipment": {"photo": "assets/71642b4dee9b53140675f342.png", "custodyEmblem": "assets/e4249b005919d080af0c4ce1.svg", "currentWork": "Exemplar preservado no Complexo de Ativos Legados da DAE ÁSIA. Pesquisa documental e avaliação técnica inconclusivas; não está liberado como arma de serviço.", "quickSummary": "Protótipo da INTERAURA que concentra uma carga aurítica para produzir um disparo de comportamento análogo ao de uma railgun. A SDAI o recolheu num depósito auxiliar abandonado em Osaka. A documentação incompleta e a ausência de homologação mantêm a unidade sob contenção para estudo futuro.", "fields": [["DESIGNAÇÃO", "A.C.A - Arma de Carga Aurítica"], ["ORIGEM", "INTERAURA / armamento experimental"], ["PRINCÍPIO", "Disparo por carga aurítica / análogo a railgun"], ["RECUPERAÇÃO", "Depósito auxiliar de superfície / Osaka"], ["CUSTÓDIA", "DAE ÁSIA / Complexo de Ativos Legados"], ["SITUAÇÃO", "Contido / sem liberação operacional"]], "sections": [{"title": "IDENTIFICAÇÃO / ARMA DE CARGA AURÍTICA", "paragraphs": ["A.C.A é a sigla de Arma de Carga Aurítica, um armamento experimental desenvolvido pela INTERAURA antes do Incidente de 29/12/1999. A unidade apreendida apresenta corpo compacto e volumoso, carcaça escura, estrutura superior reforçada e uma câmara lateral de componentes auríticos. O projeto não consta como equipamento padronizado da SDAI.", "A autoria individual, o número de exemplares produzidos e a conclusão dos ensaios originais não estão estabelecidos no acervo disponível. A classificação experimental é mantida; a existência do exemplar não comprova produção em série ou distribuição entre as antigas cobaias."]}, {"title": "RECUPERAÇÃO / DEPÓSITO AUXILIAR EM OSAKA", "paragraphs": ["A SDAI localizou a unidade durante suas operações iniciais de recolhimento de material da antiga INTERAURA, já após a constituição da organização. O exemplar estava acondicionado em uma caixa de transporte num depósito auxiliar de superfície em Osaka, separado do núcleo subterrâneo principal.", "O local apresentava sinais de abandono e movimentação interrompida de carga. Fragmentos de inventário e registros de transferência associavam o conjunto à INTERAURA. Não foram encontrados responsáveis capazes de esclarecer se a arma estava sendo enviada para teste, retirada de manutenção ou simplesmente armazenada.", "A equipe recolheu a caixa e encaminhou o material à custódia técnica. Essa recuperação não representa uma expedição concluída à antiga base subterrânea nem a retirada dos servidores que continuam ausentes. A procedência do exemplar foi consolidada pelo cruzamento documental disponível à SDAI."]}, {"title": "PRINCÍPIO REGISTRADO / DISPARO POR CARGA AURÍTICA", "paragraphs": ["A documentação descreve um sistema que concentra energia aurítica e a libera em um impulso de disparo. O comportamento pretendido é análogo ao de uma railgun, voltado à aceleração de um projétil por uma descarga concentrada, em vez de um mecanismo convencional baseado em pólvora.", "A SDAI conserva essa descrição como referência do projeto. Não possui parâmetros completos e validados de alcance, potência, estabilidade ou continuidade de disparo do exemplar recuperado. A aparência dos componentes não basta para estabelecer o desempenho real.", "A designação aurítica não significa que o armamento seja Anti-Aura. Também não há confirmação de que dependa obrigatoriamente de um ex-cobaia para operar, que possa ser empregado por qualquer usuário ou que utilize o mesmo sistema da Armadura Hakurei. Essas correspondências exigem evidência própria."]}, {"title": "AVALIAÇÃO SDAI / PROTÓTIPO SEM HOMOLOGAÇÃO", "paragraphs": ["A P&D registrou o estado de conservação e confrontou os identificadores do equipamento com cópias do acervo legado. O conjunto preserva componentes originais e sinais de uso ou manuseio anterior; o histórico de disparos da INTERAURA não foi reconstruído.", "A SDAI não homologou o exemplar para emprego operacional. Não há campanha de testes concluída que permita tratá-lo como arma regular, nem reprodução funcional aprovada do projeto. O valor do ativo permanece associado ao estudo do armamento aurítico original e à preservação de sua arquitetura.", "O estado aparente de repouso e a ausência de luminosidade na fotografia não demonstram que o equipamento esteja livre de energia residual ou plenamente compreendido. A imagem é um registro de inventário, não evidência de disparo, autonomia ou funcionamento validado."]}, {"title": "CONTENÇÃO / CUSTÓDIA DE ARMAMENTO LEGADO", "paragraphs": ["A unidade permanece em contenção tecnológica no Complexo de Ativos Legados da DAE ÁSIA, sob responsabilidade de P&D e Segurança. O inventário distingue a A.C.A das armas regulares da plataforma; não há autorização de distribuição, empréstimo a esquadrões ou retirada como equipamento de combate.", "A decisão de preservar o exemplar considera a documentação incompleta, o caráter experimental e o potencial energético ainda não caracterizado pela SDAI. Intervenções dependem de autorização técnica e registro dos responsáveis. Não tratar familiaridade com armamento convencional como domínio deste projeto.", "A contenção não implica classificação do objeto como ser vivo ou ex-cobaia. Trata-se de armamento recuperado, mantido sob custódia para impedir uso não autorizado e preservar um exemplar cuja reconstrução integral não foi demonstrada."]}, {"title": "ACERVO / LACUNAS DE ORIGEM E ABASTECIMENTO", "paragraphs": ["As cópias de documentos preservadas pela SDAI sustentam a identificação do projeto, mas não contêm sua documentação integral. A recuperação futura dos servidores da INTERAURA pode esclarecer histórico de ensaios, responsáveis e vínculos de fabricação; isso permanece uma possibilidade de investigação, não resultado garantido.", "O desaparecimento do cadastro de Reika interrompeu o acesso anteriormente utilizado ao ambiente legado. A investigação da A.C.A deve trabalhar com o material já preservado e com os dados que venham a ser recuperados, sem declarar que a credencial voltou a funcionar.", "A fonte original de abastecimento e a compatibilidade com recipientes auríticos atuais não estão consolidadas nesta ficha. Não atribuir ao projeto o padrão de cápsulas dos Saqueadores nem presumir intercambialidade com os sistemas da IIM. A origem comum na INTERAURA não demonstra equivalência técnica."]}, {"title": "DIRETRIZ ATUAL / PRESERVAR E MANTER CONTIDO", "paragraphs": ["Classificação: protótipo experimental de armamento aurítico. Situação: exemplar preservado sob custódia, sem liberação para serviço. Prioridades: conservar a unidade, reconstruir o histórico documental e esclarecer as limitações do projeto.", "A Segunda Fase da Lua Crescente Vermelha não constitui uma ordem de destruir este ativo nem autoriza sua utilização automática contra os ex-cobaias. A destinação de equipamentos legados e as ordens de captura, contenção ou eliminação de alvos permanecem determinações distintas."]}]}},{id:'LEG-0008',title:'Conjunto de arquivos do Projeto de Integração Modular',category:'Arquivos Legados',origin:'INTERAURA',access:'P&D',level:3,summary:'Documentação científica fragmentada, recuperada de instalações da INTERAURA.',detail:'Referências cruzadas a MOD-01, MOD-06, MOD-07 e MOD-24. Material parcialmente digitalizado e cópias preservadas pela SDAI. A recuperação integral depende de servidores ainda não recuperados; o login anteriormente fornecido por Reika está indisponível. Consultar LEG-0042.'},{id:'LEG-0029',title:'Tecnologia Anti-Aura de primeira geração',category:'Tecnologia',origin:'INTERAURA',access:'Segurança',level:2,summary:'Equipamentos iniciais produzidos a partir de pesquisas apreendidas.',detail:'Uso operacional descontinuado. Modelos atuais seguem padrões próprios da SDAI.'},{id:'INC-9912',title:'Incidente de 29/12/1999',category:'Arquivos Legados',origin:'INTERAURA',access:'Segurança',level:2,summary:'Encerramento das atividades da INTERAURA. Arquivo de referência histórica.',detail:'Parte dos dados permanece sob análise da Inteligência. Consulte arquivos legados para documentação técnica.'},{"id": "PES-2417", "title": "Dra. Ariella Chiyomi / desaparecida em ação", "category": "Pessoal", "origin": "P&D SDAI / CUSTÓDIA CIENTÍFICA LEGADA", "access": "Todas as divisões", "level": 2, "recordType": "employee", "summary": "Antiga cientista da INTERAURA, mantida presa por cerca de 19 anos sem falar ou ajudar a SDAI. A expressão exausta e vazia causava temor ao pessoal que lidava com ela. Aparenta profundo ódio à organização e ao que ocorreu após o Incidente. Desaparecida em ação, sem confirmação de vida ou morte; proibido qualquer contato com ex-cobaias.", "detail": "Cadastro administrativo de pessoal científico retido, sem exercício funcional. Última custódia interrompida pela queda do transporte; paradeiro, sobrevivência e circunstâncias posteriores não confirmados.", "employee": {"name": "Ariella Chiyomi", "japaneseName": "アリエラ・チヨミ", "age": "Não consolidada neste cadastro", "nationality": "Japonesa", "birthplace": "Não consolidada neste cadastro", "role": "Pesquisadora retida / sem exercício funcional na SDAI", "division": "Pesquisa e Desenvolvimento / vinculação administrativa", "station": "Último registro: transporte SDAI em Osaka / desaparecida em ação", "supervision": "Segurança SDAI / coordenação de P&D e Inteligência", "appointment": "Prisioneira científica / nenhuma colaboração obtida", "status": "Desaparecida em ação / vida ou morte não confirmadas", "previousRole": "INTERAURA / responsável pelo Projeto de Integração Modular, com Adam Chiyomi", "capture": "Pós-Incidente / início da atuação da SDAI em 2000", "clearance": "Sem acesso autônomo ou atribuição de serviço", "photo": "assets/92a723f736f6edc7ea347aff.png", "serviceLabel": "DESAPARECIDA EM AÇÃO / NÃO LOCALIZADA", "statusClass": "staff-missing", "photoNote": "ARQUIVO DE CUSTÓDIA / ANTERIOR À QUEDA", "specialty": "Pesquisa aurítica / Projeto de Integração Modular", "custodyRegime": "Prisão sob controle direto / anterior ao desaparecimento", "custodyTitle": "CADASTRO CIENTÍFICO NÃO EQUIVALE A COLABORAÇÃO", "custodyNote": "Ariella foi mantida predominantemente como prisioneira, sob regime mais severo que o dos antigos cientistas com privilégios condicionais. Não prestou serviço à SDAI. O uniforme de P&D documenta sua vinculação administrativa durante a custódia; não demonstra consentimento, função exercida ou lealdade. A custódia atual não está confirmada após a queda.", "currentTitle": "SITUAÇÃO ATUAL / ÚLTIMO REGISTRO", "currentWork": "Não há atividade de trabalho para a SDAI registrada. Após a queda do transporte em Osaka, Ariella foi classificada como desaparecida em ação. A SDAI ainda não sabe se está viva ou morta e aguarda avistamento verificável ou localização para esclarecer seu estado. Não há resgate ou recaptura confirmados.", "quickSummary": "Antiga cientista da INTERAURA, mantida presa por cerca de 19 anos sem falar ou ajudar a SDAI. A expressão exausta e vazia causava temor ao pessoal que lidava com ela. Aparenta profundo ódio à organização e ao que ocorreu após o Incidente. Desaparecida em ação, sem confirmação de vida ou morte; proibido qualquer contato com ex-cobaias.", "projectsTitle": "DEMANDAS DA SDAI / NENHUMA COLABORAÇÃO OBTIDA", "projects": [{"code": "ENT-ARI", "name": "Entrevistas e informações sobre a INTERAURA", "work": "A SDAI tentou obter esclarecimentos sobre o antigo projeto e seus registros. Nenhuma palavra foi obtida durante os aproximadamente 19 anos de custódia.", "state": "SEM RESPOSTA VERBAL"}, {"code": "P&D-ARI", "name": "Emprego científico pretendido", "work": "Tentativas de extrair auxílio para pesquisas da SDAI não resultaram em serviço prestado, relatório produzido ou orientação técnica fornecida pela retida.", "state": "NENHUM SERVIÇO PRESTADO"}, {"code": "CST-ARI", "name": "Controle e acompanhamento de custódia", "work": "Acompanhamento conduzido pelas equipes responsáveis antes da transferência. Não se trata de atividade desempenhada por Ariella.", "state": "HISTÓRICO / NÃO RESTABELECIDO"}, {"code": "LOC-ARI", "name": "Apuração após a queda do transporte", "work": "Verificar registros da transferência e informes posteriores ao acidente. A localização continua sem confirmação; esta demanda pertence à SDAI.", "state": "PARADEIRO NÃO CONFIRMADO"}, {"code": "IIM-ARI", "name": "Interpretação da IIM / tentativa frustrada", "work": "A SDAI tentou obter a ajuda da cocriadora para operar a interface. Ariella não forneceu qualquer palavra ou auxílio; nenhuma operação útil foi obtida. Não representa pesquisa realizada por ela para a SDAI.", "state": "NENHUMA COLABORAÇÃO OBTIDA"}], "identifications": [], "contactBlock": {"code": "SEGUNDA FASE DA LUA CRESCENTE VERMELHA / PROIBIÇÃO ABSOLUTA", "title": "ARIELLA CHIYOMI NÃO DEVE ENTRAR EM CONTATO COM NENHUM EX-COBAIA. SOB NENHUMA CIRCUNSTÂNCIA.", "body": "NÃO AUTORIZE ENCONTROS. NÃO TRANSMITA MENSAGENS. NÃO ESTABELEÇA UM CANAL DIRETO OU INDIRETO ENTRE ELA E OS EX-COBAIAS DA INTERAURA. A PROIBIÇÃO ABRANGE TODOS ELES, CONTIDOS, CONGELADOS, FORAGIDOS OU EMPREGADOS PELA SDAI. O GRUPO DE OSAKA ESTÁ INCLUÍDO. Qualquer tentativa identificada deve ser interrompida e comunicada imediatamente ao Alto Comando. O desaparecimento não suspende a determinação."}, "footer": "PES-2417 / P&D SDAI · CADASTRO DE CUSTÓDIA HISTÓRICO · DESAPARECIDA EM AÇÃO · CONTATO COM EX-COBAIAS PROIBIDO / SEGUNDA FASE", "referencesTitle": "REGISTROS RELACIONADOS / REFERÊNCIAS CRUZADAS", "references": [{"id": "LEG-0008", "label": "Arquivos do Projeto de Integração Modular →"}, {"id": "FAC-0010", "label": "Grupo terrorista de Osaka / restrição de contato →"}, {"id": "PES-2418", "label": "Reika Mizuhara / cientista sob regime distinto de custódia →"}, {"id": "LEG-0041", "label": "IIM / equipamento criado com Adam Chiyomi →"}], "referencesNote": "Os registros possuem suas próprias permissões. A comparação de regimes não atribui à Reika participação nos procedimentos aplicados a Ariella.", "sections": [{"title": "IDENTIFICAÇÃO / ANTIGA INTERAURA", "paragraphs": ["Ariella Chiyomi integrava a direção científica da antiga INTERAURA e era responsável, junto de Adam Chiyomi, pelo Projeto de Integração Modular, também referido como Projeto de Cobaias. É irmã de Adam. Seu conhecimento do projeto sustentou o interesse persistente da SDAI em mantê-la sob controle após o Incidente. Adam Chiyomi está morto; esta ficha não estabelece a data, as circunstâncias ou o responsável por sua morte.", "O cadastro não lhe atribui a direção dos projetos Cryptum e Armadura Hakurei, associados a Akira Hakurei. Conhecimento do Projeto de Cobaias não equivale a domínio automático de toda tecnologia recuperada da corporação. Idade e local de nascimento não estão consolidados nesta cópia operacional."]}, {"title": "CAPTURA / PÓS-INCIDENTE E CUSTÓDIA PROLONGADA", "paragraphs": ["Foi capturada depois do Incidente da INTERAURA de 29/12/1999, já durante a atuação inicial da SDAI. Permaneceu presa por aproximadamente 19 anos até os acontecimentos atuais de Osaka. A contagem é aproximada; este cadastro não estabelece uma data exata de captura.", "A SDAI a reteve pela importância de seu conhecimento e pela expectativa de obter informações sobre o projeto, os módulos e os arquivos remanescentes. Sua inclusão administrativa em P&D não converteu o aprisionamento em contratação voluntária."]}, {"title": "REGIME / PRISÃO MAIS SEVERA QUE A DOS DEMAIS CIENTISTAS", "paragraphs": ["Diferentemente dos antigos cientistas que conservaram privilégios condicionados à pesquisa e ao serviço prestado, Ariella foi tratada predominantemente como prisioneira. Não chegou a exercer uma rotina funcional comparável à de Reika Mizuhara.", "Deslocamentos e apresentação à equipe científica ocorriam sob controle da custódia. O uniforme com o emblema de P&D servia à identificação institucional da retida, sem lhe conceder credencial autônoma, acesso livre a laboratórios, posição militar ou direito de deixar a instalação.", "O cadastro em Pessoal conserva a origem científica e o interesse administrativo da SDAI. Não é um registro de serviços prestados, produtividade, recompensa ou adesão à organização."]}, {"title": "DEZENOVE ANOS / SILÊNCIO E AUSÊNCIA DE COLABORAÇÃO", "paragraphs": ["Durante os aproximadamente 19 anos em que permaneceu presa pela SDAI, Ariella não deu uma palavra e não prestou qualquer ajuda à organização. Não entregou orientação técnica, identificação de módulos, relatório, pesquisa ou informação verbal aproveitável. O histórico é de ausência completa de colaboração, não de serviço irregular ou recusa recente.", "A SDAI promoveu sucessivas tentativas de interrogatório, avaliação, pressão e obtenção de auxílio. Equipes foram substituídas, abordagens revistas e sessões repetidas. Nenhuma dessas iniciativas produziu a palavra ou o apoio que a instituição buscava.", "Não há declarações de Ariella transcritas neste cadastro. A aparente hostilidade, o esgotamento e o sentido atribuído ao silêncio resultam das observações dos responsáveis pela custódia; não são falas da própria pesquisadora."]}, {"title": "EXPRESSÃO / ESGOTAMENTO E TEMOR ENTRE OS EFETIVOS", "paragraphs": ["Os agentes descreviam uma expressão morta: olhar vazio, pálpebras pesadas, rosto cansado e escassa mudança de expressão diante de perguntas, instruções ou tentativas de provocar uma resposta. O silêncio prolongado e a dificuldade de obter reação deixavam desconfortáveis até integrantes habituados a procedimentos de contenção.", "Entre o pessoal da SDAI, dizia-se metaforicamente que ela parecia ter perdido a alma. A descrição registra o temor causado por sua aparência e comportamento. Não comprova morte, ausência literal de alma, influência sobrenatural ou diagnóstico clínico.", "O retrato é um arquivo anterior à queda do transporte. A expressão registrada não constitui uma imagem atual de seu paradeiro, tampouco confirma que continue nas mesmas condições após o acidente."]}, {"title": "AVALIAÇÃO DE CONDUTA / HOSTILIDADE APARENTE", "paragraphs": ["Ariella aparenta odiar profundamente a SDAI e o que ocorreu após o Incidente. A avaliação se baseia na recusa persistente de cooperação e na conduta observada durante a custódia; a pesquisadora não explicou suas motivações aos agentes.", "Não tratar o silêncio como concordância, incapacidade intelectual comprovada ou esquecimento do projeto. O cadastro também não estabelece se o comportamento decorre de trauma, resistência deliberada, esgotamento ou uma combinação de fatores.", "O receio que provocava no pessoal da SDAI não é apresentado como habilidade aurítica. Não há demonstração atribuída a este cadastro de controle mental, perda de vontade dos agentes ou outro efeito sobrenatural de seu olhar."]}, {"title": "TRANSFERÊNCIA / PRESENÇA NO TRANSPORTE QUE CAIU", "paragraphs": ["Ariella estava a bordo do transporte da SDAI que caiu em Osaka. A ocorrência rompeu a continuidade de sua custódia. Desde a queda, seu paradeiro não foi confirmado pela organização.", "O transporte acidentado é a nave de transporte SDAI, não a DAE ÁSIA. A plataforma principal permanece operacional; a referência visual do local da queda no mapa ampliado corresponde ao transporte.", "Este registro não atribui a Ariella a causa do acidente nem confirma fuga planejada, extração por terceiros ou envolvimento do grupo de Osaka na retirada da pesquisadora. A ausência de localização posterior não permite preencher essas lacunas."]}, {"title": "SITUAÇÃO ATUAL / DESAPARECIDA EM AÇÃO", "paragraphs": ["Classificação atual: desaparecida em ação, sem custódia restabelecida. A SDAI permanece sem confirmação de vida ou morte após o acidente. É necessário obter um avistamento verificável ou localizar a cientista para esclarecer sua condição; não há resgate, recaptura ou óbito confirmados.", "A aparência fatigada do retrato pertence ao histórico de custódia. O tempo transcorrido sob vigilância da SDAI não autoriza a organização a afirmar onde ela está ou o que está fazendo no momento atual.", "A consulta a este cadastro serve à identificação e ao acompanhamento da determinação de contato. Equipes devem preservar registros e encaminhar informações verificáveis pela cadeia responsável, sem declarar o caso encerrado pela ausência de resposta."]}, {"title": "SEGUNDA FASE / CONTATO TERMINANTEMENTE PROIBIDO", "paragraphs": ["Por autorização expressa do Alto Comando para comandar o protocolo Lua Crescente Vermelha, Arvensis / Marina Azevedo ordenou iniciar a Segunda Fase após a queda do transporte e o desaparecimento de Ariella. A cientista permanece desaparecida em ação; a SDAI não confirmou se sobreviveu ou morreu.", "A determinação da Segunda Fase da Lua Crescente Vermelha proíbe que Ariella entre em contato com qualquer ex-cobaia da INTERAURA. A abrangência não se limita aos integrantes do grupo terrorista de Osaka e não depende da situação de custódia ou de colaboração de cada módulo.", "Não facilitar encontro, comunicação por terceiros ou transmissão de mensagens entre ela e os ex-cobaias. Eventuais avistamentos ou localização não autorizam o pessoal a negociar esse contato por iniciativa própria. O desaparecimento da pesquisadora não revoga a proibição.", "A base integral da determinação não está exposta nesta cópia. O aviso não identifica Ariella como o Contemplador que dirige o grupo de Osaka e não atribui a ela a autoria do símbolo na mão de Janel.", "Ariella é registrada como cientista retida, não como ex-cobaia contida. O prazo de execução de dez horas existente nas fichas de módulos não é automaticamente atribuído a ela por este cadastro. A ficha conserva o estado de desaparecimento e a proibição de contato."]}, {"title": "CONTROLE DOCUMENTAL / SERVIÇO NÃO PRESTADO", "paragraphs": ["Não existem pareceres de identificação assinados por Ariella para a SDAI neste cadastro. As confirmações de MOD-11, MOD-28 e MOD-67 permanecem atribuídas a Reika Mizuhara, conforme as respectivas fichas de contenção.", "Arquivo anterior, cargo na INTERAURA e uniforme de P&D não devem ser convertidos em evidência de auxílio à SDAI. A ausência de colaboração abrange todo o período de custódia de aproximadamente 19 anos.", "Conservar separadas a localização anterior no transporte, a condição atual de desaparecida e a determinação da Segunda Fase. Nenhum desses campos comprova os acontecimentos posteriores à queda."]}]}},{id:'ATV-0007',title:'Janel Hakurei / MOD-07',category:'Alvos Procurados',origin:'INTELIGÊNCIA SDAI / INTERAURA',access:'Todas as divisões',level:0,summary:'Terrorista vinculada ao grupo de terroristas de Osaka, sem nome declarado. Foragida; ordem de eliminação vigente na Segunda Fase da Lua Crescente Vermelha.',detail:'Ficha operacional de identificação e procura.'},{"id": "ATV-0049", "title": "Hiriko / MOD-49 [EM REVISÃO]", "category": "Alvos Procurados", "origin": "INTELIGÊNCIA SDAI / INTERAURA", "access": "Todas as divisões", "level": 0, "summary": "Terrorista em atividade em Osaka. Participante do massacre no Clube da Noite; monitorado anteriormente por conflitos contra Yakuzas locais e Siegel.", "detail": "Ficha operacional de identificação e procura."},{"id": "ALV-0050", "title": "Onaya Keiko / captura prioritária", "category": "Alvos Procurados", "origin": "INTELIGÊNCIA SDAI / CAM-12", "access": "Todas as divisões", "level": 0, "summary": "Terrorista de 34 anos, ex-estudante de Direito em Osaka. Poder aurítico vinculado a uma tesoura; ordem de captura viva, prisão e contenção.", "detail": "Ficha operacional de identificação e captura."},{"id": "ATV-0042", "title": "Taiyo Fajara / dois perfis em investigação", "category": "Alvos Procurados", "origin": "INTELIGÊNCIA SDAI / MOD-42", "access": "Todas as divisões", "level": 0, "summary": "Duas Taiyos: raposa vinculada a MOD-42 e entidade com chifres. Matriarcado Fajara em revisão; diretrizes distintas por perfil.", "detail": "Dossiê conjunto de identificação e investigação de liderança."},{"id": "ALV-0051", "title": "Mascarada das Noites / identidade desconhecida", "category": "Alvos Procurados", "origin": "INTELIGÊNCIA SDAI / CAM-N08", "access": "Todas as divisões", "level": 0, "summary": "Ativa desde 2008. Confrontos com Siegel, Filhos de Naniwaku e Saqueadores; identidade e motivações desconhecidas. Captura prioritária; recompensa US$ 75.000.", "detail": "Ficha de identificação por equipamento e histórico de vigilância."},{"id": "ATV-0035", "title": "Albert Magnar / óbito confirmado", "category": "Alvos Procurados", "origin": "INTELIGÊNCIA SDAI / MOD-35", "access": "Todas as divisões", "level": 0, "summary": "MOD-35. Fabricante e traficante de armas; participante do massacre no Clube da Noite. Óbito sincronizado na INTERAURA durante a perseguição em Osaka; progressões militares homologadas.", "detail": "Arquivo operacional encerrado com confirmação de óbito e reconhecimento dos participantes."},{"id": "ALV-0053", "title": "Caveira / inimigo prioritário da SDAI", "category": "Alvos Procurados", "origin": "ALTO COMANDO / INTELIGÊNCIA SDAI", "access": "Todas as divisões", "level": 0, "summary": "Identidade desconhecida; maior inimigo da SDAI desde 2000. Hostilidade aparente às facções, sobretudo SDAI e Siegel; exceção observada: apoio ao grupo de Osaka. Independente.", "detail": "Ameaça máxima / identidade e capacidades não esclarecidas."},{"id": "ALV-0052", "title": "Encouraçado Desconhecido / tecnologia não identificada", "category": "Alvos Procurados", "origin": "INTELIGÊNCIA SDAI / COMPARAÇÃO HAK-MOD/F", "access": "Todas as divisões", "level": 0, "summary": "Associado ao grupo terrorista de Osaka. Energia aurítica extremamente elevada; semelhança forte com Armadura Hakurei. Operador, ciborgue ou robô em investigação. Conter e capturar; US$ 200.000.", "detail": "Identidade desconhecida. Não há módulo INTERAURA atribuído com segurança."},{"id": "ATV-0011", "title": "Billy Black / MOD-11 / criogenia ativa", "category": "Contenção", "origin": "CUSTÓDIA SDAI / MOD-11", "access": "Todas as divisões", "level": 0, "summary": "Capturado após o Incidente, identificado pela cientista Reika Mizuhara. Telecinese forte. Criogenado em 14/06/2000 (≈19 anos); execução em 10 horas pela Segunda Fase.", "detail": "Registro de contenção; vivo e congelado, execução pendente."},{"id": "CNT-0028", "title": "Runeko / MOD-28 / agente dupla sob custódia", "category": "Contenção", "origin": "CUSTÓDIA SDAI / INTELIGÊNCIA / MOD-28", "access": "Todas as divisões", "level": 0, "summary": "MOD-28 confirmada pela cientista Reika Mizuhara. Histórico de combate contra a SDAI; capturada na primeira perseguição após o massacre do clube. Agente dupla sob custódia; serviço em encerramento pela Segunda Fase. Viva; execução pendente em 10 horas.", "detail": "Colaboração operacional não revoga a condição de ex-cobaia contida."},{"id": "CNT-0067", "title": "Gabrijela Vlasic / MOD-67 / criogenia ativa", "category": "Contenção", "origin": "CUSTÓDIA SDAI / MOD-67", "access": "Todas as divisões", "level": 0, "summary": "Croata; cerca de 20 anos na captura. Escapou da INTERAURA durante o Incidente, localizada perdida em Osaka e capturada pela SDAI. Identificação confirmada pela cientista Reika Mizuhara. Atravessa paredes e materializa um grande braço de matéria desconhecida sob seu controle. Criogenia desde 22/06/2000; execução em 10 horas.", "detail": "Registro de contenção; viva e congelada, execução pendente."},{"id": "FAC-0001", "title": "Siegel", "category": "Facções Inimigas", "origin": "INTELIGÊNCIA SDAI", "access": "Todas as divisões", "level": 0, "summary": "Corporação fundada na década de 2000, com atuação na Ásia - Japão, Coreia do Sul e China - e considerável influência econômica e política no Japão. Opera nos setores de mobiliário, imóveis residenciais, armamentos, segurança e entretenimento. Mantém uma PMC própria. O apoio a usuários de Aura ocorre clandestinamente, sem reconhecimento público.", "detail": "Dossiê organizacional em consolidação.", "factionKey": "siegel", "factionType": "Corporação / força militar privada", "area": "Ásia · Japão, Coreia do Sul e China", "connections": [{"id": "ATV-0049", "note": "Confrontos anteriores com Hiriko"}, {"id": "ALV-0051", "note": "Confrontos com a Mascarada das Noites"}, {"id": "FAC-0002", "note": "Khabapol · aliança por interesse / ataques persistentes"}, {"id": "ALV-0050", "note": "Onaya Keiko · confrontos registrados em Osaka"}], "fileState": "DOSSIÊ ORGANIZACIONAL / OPOSIÇÃO À SDAI", "sections": [{"title": "PERFIL CORPORATIVO / ATUAÇÃO CIVIL", "paragraphs": ["A Siegel atua no Japão, na Coreia do Sul e na China, abrangendo aluguel de mobiliário e imóveis residenciais, armamentos, serviços de segurança e entretenimento. Sua inserção em atividades civis sustenta uma ampla rede de influência, especialmente no Japão.", "Publicamente, a corporação afirma que sua PMC exerce apenas funções de proteção corporativa, em conformidade com as leis aplicáveis. Não revela apoio a usuários de Aura. A avaliação da SDAI aponta que essa proteção ocorre por baixo dos panos, enquanto a empresa preserva sua imagem de segurança e justiça.", "A liderança é compartilhada por três CEOs: Nikiz, Xin Jie e Tazawa. A distribuição de responsabilidades entre eles ainda não está consolidada neste registro.", "Nikiz, Xin Jie e Tazawa possuem proteção pessoal pelo tratado com a SDAI. A hostilidade à corporação não autoriza ações contra os três CEOs, estejam ou não em seus prédios executivos."]}, {"title": "PMC / ESTRUTURA DE SEGURANÇA PRIVADA", "paragraphs": ["A força de segurança privada está dividida em Selo Preto, Selo Roxo e Selo Vermelho. Os emblemas divisionais estão registrados abaixo; efetivos, atribuições específicas e cadeia de comando ainda aguardam consolidação.", "A avaliação da SDAI diverge da narrativa oficial da corporação: suas forças privadas não se limitam às funções de segurança declaradas e infringem as leis que a empresa afirma respeitar. A divisão em selos não constitui comprovação de conformidade legal."]}, {"title": "AVALIAÇÃO SDAI / INFLUÊNCIA E CONTROLE DE IMAGEM", "paragraphs": ["A corporação dispõe de influência suficiente para encobrir conflitos e irregularidades, reduzir sua repercussão e preservar a apresentação pública de seus agentes como justiceiros. A imagem de legalidade deve ser tratada separadamente de sua conduta operacional.", "Seu crescimento ampliou o poder corporativo a ponto de disputar influência com instituições estatais. O governo japonês permanece em funcionamento e colabora com a SDAI no enfrentamento à Siegel; a corporação não é reconhecida neste registro como governo legítimo."]}, {"title": "RELAÇÕES / GOVERNO, SDAI E YAKUZAS", "paragraphs": ["A Siegel se opõe à SDAI e apoia clandestinamente usuários de Aura, sem declarar esse posicionamento ao público. O governo japonês mantém colaboração com a SDAI contra a corporação. Essa colaboração não elimina a existência de restrições decorrentes do acordo bilateral entre Siegel e SDAI, que também protege os três CEOs.", "A expansão da Siegel contribuiu para a diminuição do poder de organizações tradicionais, incluindo as yakuzas japonesas. A perda de influência dessas organizações não comprova sua eliminação nem permite presumir uma aliança comum contra a corporação.", "A Siegel mantém uma aliança instável com a máfia russa Khabapol. A cooperação em interesses e negócios específicos não impede ataques da Khabapol a ativos da corporação. Não há pacto geral de não agressão entre elas; a relação não altera o acordo separado Siegel–SDAI sobre centros de comando e proteção dos CEOs.", "Há registros de confrontos de Hiriko e Onaya Keiko com integrantes desta organização em Osaka. Os dois pareciam atuar como justiceiros. A SDAI mantém sua classificação de terroristas; esses episódios não comprovam participação de todos os integrantes do grupo de Osaka em cada confronto. Consultar ATV-0049, ALV-0050 e FAC-0010."]}, {"title": "ACORDO BILATERAL / PROTEÇÃO DOS CEOs E CENTROS DE COMANDO", "paragraphs": ["Após a escalada de conflitos e os prejuízos impostos a ambos os lados, Siegel e SDAI estabeleceram um acordo que protege os centros de comando e os três CEOs da corporação. A SDAI não deve atacar os prédios executivos abrangidos pelo tratado nem realizar ações contra Nikiz, Xin Jie ou Tazawa, inclusive quando estiverem fora desses prédios. Em contrapartida, a Siegel não deve atacar as Daedalus.", "A Siegel detinha segredos sobre atos de crimes de guerra cometidos pela SDAI e ameaçou revelá-los ao público. A corporação utilizou essas informações como instrumento de pressão: em troca da aceitação do acordo, comprometeu-se a não divulgar o material. A SDAI aceitou o pacto diante da ameaça de exposição.", "O pacto protege os locais e plataformas abrangidos e impede ações da SDAI contra os três CEOs. Não representa aliança, reconhecimento de legitimidade ou encerramento dos demais confrontos. A hostilidade contra as forças e operações da Siegel permanece ativa dentro desses limites. A proteção pessoal não depende da localização dos CEOs; não estão autorizadas sua captura, eliminação ou ações clandestinas contra eles.", "O compromisso de silêncio da Siegel integra a negociação. A existência do acordo não significa que a corporação tenha entregue ou destruído os registros; não há confirmação dessas medidas neste documento."]}, {"title": "HISTÓRICO / ATAQUES CONTRA A SDAI E AUTORIDADES NACIONAIS", "paragraphs": ["INTERCEPTAÇÃO DE COMBOIO / CORREDOR LOGÍSTICO DE OSAKA - Operadores da PMC atacaram um comboio da SDAI em deslocamento entre instalações de apoio. O ataque concentrou-se nos veículos de escolta e no bloqueio da via. Houve baixas, perda de suprimentos e interrupção temporária da rota; divisão responsável em apuração.", "EMBOSCADA A EQUIPE DE RECONHECIMENTO / ZONA COMERCIAL - Agentes identificados pelo conjunto de equipamentos da PMC abriram fogo contra uma patrulha da SDAI após conduzi-la a uma passagem de serviço. A retirada dos atacantes ocorreu entre vias civis. A atribuição se apoia no cruzamento de registros de campo, não somente na aparência cibergótica.", "SABOTAGEM DE COMUNICAÇÕES / POSTO AVANÇADO - Uma instalação periférica da SDAI teve seus enlaces interrompidos antes de um ataque contra o efetivo externo. Componentes recuperados e a movimentação registrada sustentam a atribuição à PMC da Siegel. A identificação dos executores permanece em investigação.", "RESTRIÇÃO VIGENTE - Estas ocorrências envolvem forças e instalações periféricas. Não constituem registro de ataque às Daedalus, aos prédios executivos protegidos ou aos três CEOs abrangidos pelo acordo bilateral. A hostilidade fora dos centros abrangidos pelo pacto permanece ativa.", "COAÇÃO E ATAQUE A AUTORIDADES / JAPÃO - Uma operação policial destinada a apreender armamento clandestino foi recebida com resistência armada por agentes ligados à PMC. Em episódio relacionado, investigadores sofreram intimidação e um veículo oficial foi atacado durante a retirada. A corporação apresentou os acontecimentos publicamente como ações de segurança; os relatórios da SDAI registram agressão às forças estatais.", "SABOTAGEM DE FISCALIZAÇÃO / COREIA DO SUL - Uma equipe que verificava movimentações de armamentos sofreu ataque durante a inspeção de uma estrutura de apoio. A investigação aponta operadores vinculados à rede da Siegel. A atribuição institucional não permite concluir que todo funcionário das operações civis da empresa participe das ações clandestinas.", "ATAQUE A OPERAÇÃO DE APREENSÃO / CHINA - Uma célula de segurança corporativa atacou forças locais durante a apreensão de uma remessa clandestina. O episódio integra os registros de atuação hostil na região; a cadeia de ordens e a responsabilidade individual dos três CEOs não foram estabelecidas neste relatório.", "CONTROLE DO REGISTRO - Ocorrências atribuídas à organização por relatórios de campo. A ficha registra os atos; autoria individual, totais de baixas e datas exatas permanecem sujeitos à consolidação dos respectivos relatórios. Não presumir participação pessoal da liderança em cada ataque."]}], "leadership": "Três CEOs: Nikiz, Xin Jie e Tazawa", "pmcDivisions": [{"key": "preto", "name": "SELO PRETO", "image": "assets/a8f2315f5c45ef085940f322.png", "uniformDescription": "Proteção tática em grafite e preto, placas segmentadas, capacete fechado de perfil angular e visor verde. Detalhes verdes acompanham o peitoral e os pontos de articulação.", "uniforms": [{"label": "PADRÃO TÁTICO", "photo": "assets/8df045b71c9ce9b9c1564872.png"}]}, {"key": "roxo", "name": "SELO ROXO", "image": "assets/d06447cd399f4716c4f8ac0e.png", "uniformDescription": "Apresentação cibergótica com predominância de preto e detalhes roxos. A variante masculina costuma utilizar terno com colete e máscara de gás roxa; a feminina registrada utiliza visor roxo e uniforme com detalhes da mesma cor. Esses elementos não são exclusivos da corporação.", "uniforms": [{"label": "VARIANTE MASCULINA", "photo": "assets/cf5a88a42dfd29ccac24ef7d.png"}, {"label": "VARIANTE FEMININA", "photo": "assets/620605a9c7a5c74363fe5f76.png"}], "identificationWarning": "ATENÇÃO / MODA NÃO CONFIRMA FILIAÇÃO. Não confundir qualquer cibergótico com um integrante da Siegel: civis podem estar apenas se divertindo e aderindo à moda. Uma identificação baseada somente na aparência pode provocar acidentes. O Selo Roxo aproveita essa semelhança para se camuflar entre as pessoas e é o selo com maior exposição cotidiana nas ruas. Confirmar o vínculo por outros elementos antes de atribuir filiação."}, {"key": "vermelho", "name": "SELO VERMELHO", "image": "assets/fd1993db8908d800e454cb8c.png", "uniformDescription": "Armadura de placas vermelhas sobre estrutura escura e cinza. Capacete integral arredondado, proteção distribuída pelos membros e pontos luminosos claros no visor e no peitoral. O conjunto de campo incorpora suporte peitoral com bolsas de munição, rádio, cinto utilitário e bolsa lateral fixada à coxa.", "uniforms": [{"label": "PADRÃO BLINDADO", "photo": "assets/c35680df4509de9387d720bb.png"}]}], "executives": [{"name": "Nikiz", "role": "CEO · Alemão", "caption": "Pronunciamento durante conferência pública da Siegel.", "photo": "assets/5dff247aa1e2d088f44c173b.png", "description": "Grande empresário alemão, amplamente reconhecido na Europa. Mantém um histórico de opiniões públicas negativas contra a SDAI."}, {"name": "Xin Jie", "role": "CEO · Chinês", "caption": "Intervenção durante sessão pública de perguntas.", "photo": "assets/f3118ab9cd093db11569308c.png", "description": "CEO chinês conhecido pela eloquência e pela habilidade de se expressar em público. Sua identidade pessoal permanece incerta devido ao uso constante de uma máscara. Nunca explicou publicamente o motivo de utilizá-la."}, {"name": "Tazawa", "role": "CEO · Japonesa", "caption": "Declaração à imprensa em conferência da corporação.", "photo": "assets/a6f98fd2464bb460f593d4c1.png", "description": "Empresária japonesa carismática e forte apoiadora do Cibergotismo, moda de grande expressão no Japão e estreitamente ligada à rebeldia. É reconhecida pelo público cibergótico como “Cybergod”."}], "organizationOrigin": "Japão · década de 2000"},{"id": "FAC-0002", "title": "KHABAPOL", "category": "Facções Inimigas", "origin": "INTELIGÊNCIA SDAI", "access": "Todas as divisões", "level": 0, "summary": "Máfia russa classificada como grupo terrorista pela SDAI. Controla o governo russo após um golpe de Estado e domina redes empresariais. Raízes soviéticas, ampla atuação aurítica e ataques internacionais por fins políticos. Liderada por Yaroslava Zorina. Inimiga declarada da SDAI; aliança instável com a Siegel.", "detail": "Dossiê consolidado / poder estatal, redes empresariais, Auras e operações internacionais.", "factionKey": "khabapol", "factionType": "Máfia russa / grupo terrorista de alcance internacional", "area": "Rússia · redes internacionais · presença hostil registrada em Osaka", "connections": [{"id": "ALV-0063", "note": "Yaroslava Zorina · líder procurada / captura bloqueada em território russo"}, {"id": "FAC-0001", "note": "Siegel · aliança instável / ataques persistentes"}, {"id": "FAC-0004", "note": "Los Elegidos · hostilidade"}], "organizationOrigin": "Redes com conexões à antiga União Soviética · data de fundação não consolidada", "leadership": "Yaroslava Zorina · comando central e estruturas regionais", "fileState": "DOSSIÊ CONSOLIDADO / AMEAÇA POLÍTICA E AURÍTICA", "leadershipSectionTitle": "LIDERANÇA / COMANDO DA KHABAPOL", "executives": [{"name": "Yaroslava Zorina", "role": "Líder da Khabapol / coordenação estratégica", "photo": "assets/bd6f5f341a34faf51d777bbd.png", "description": "Dirige a articulação entre a cúpula mafiosa, os interesses empresariais e o governo controlado pela organização. A Inteligência atribui à sua liderança a manutenção do equilíbrio entre estruturas regionais e projetos auríticos. Tem aproximadamente 70 anos; trajetória completa não consolidada. Possui os olhos negros característicos dos membros da Khabapol; possível componente biônico em investigação.", "caption": "IDENTIFICAÇÃO / RETRATO FRONTAL · OLHOS NEGROS / MARCA KHABAPOL"}], "sections": [{"title": "PERFIL / MÁFIA, PODER ESTATAL E TERRORISMO", "paragraphs": ["A Khabapol é uma máfia russa com domínio sobre redes empresariais e controle governamental na Rússia após o sucesso de um golpe de Estado. A SDAI a classifica como grupo terrorista pela combinação de violência política, ataques internacionais e emprego de recursos econômicos e estatais em sua campanha hostil. A organização não se limita a atividades clandestinas: influencia decisões administrativas, interesses empresariais e estruturas de segurança.", "Sua prioridade é transformar poder econômico em capacidade política duradoura. Empresas, canais de governo e operadores clandestinos desempenham funções complementares, permitindo que uma mesma disputa apareça como negócio, decisão oficial ou ataque atribuído a agentes sem vínculo público."]}, {"title": "RAÍZES / CONEXÕES COM A ANTIGA UNIÃO SOVIÉTICA", "paragraphs": ["A organização mantém conexões antigas com redes da União Soviética. Sua continuidade se manifesta em contatos de logística, antigos intermediários e relações com setores que sobreviveram à dissolução do Estado soviético. A existência dessas conexões não significa que todo integrante atual tenha servido ao regime soviético.", "A Inteligência avalia que antigos vínculos forneceram acesso a instalações, conhecimentos técnicos e relações pessoais posteriormente incorporados às operações da máfia. A data exata de fundação e a identificação de todos os responsáveis pela transformação dessas redes na Khabapol permanecem em investigação."]}, {"title": "GOLPE DE ESTADO / CONTROLE GOVERNAMENTAL", "paragraphs": ["O golpe de Estado conduzido pela Khabapol foi bem-sucedido: seu controle sobre o governo russo é tratado como situação estabelecida, e não como mera intenção. A organização preserva estruturas administrativas formais e utiliza interlocutores políticos para executar decisões de interesse da cúpula.", "O controle governamental permite proteger determinados negócios, restringir investigações e dificultar intervenções externas. Isso não demonstra controle absoluto sobre cada cidadão ou servidor: dissidências, resistências locais e disputas internas continuam possíveis. A data e a sequência detalhada do golpe não estão consolidadas nesta cópia.", "Yaroslava Zorina participa de sessões oficiais como parte reconhecida da estrutura governamental e exerce influência determinante sobre as decisões do Estado. Sua presença no congresso não é a de uma visitante tolerada: ela ocupa o espaço político com autoridade institucional. Sua condição de usuária de Aura não é tratada pelas autoridades russas como ameaça ou motivo para exclusão do espaço político. O registro de imprensa abaixo documenta sua presença no congresso, integrada ao ambiente institucional.", "A aparência de autonomia das instituições serve de cobertura ao comando da Khabapol. Para o público internacional, decisões são apresentadas como iniciativas próprias do governo russo; por trás dessa representação, a organização determina a orientação política e os interesses que essas decisões atendem. Esse reconhecimento confronta diretamente a doutrina da SDAI e agrava suas relações internacionais com a Rússia. Sob a orientação da Khabapol, o governo russo pode recusar pedidos de acesso, entrega de portadores de Aura e autorização para intervenções em seu território. Para a Inteligência, a proteção política da dirigente da Khabapol constitui uma preocupação internacional: a classificação de ameaça atribuída pela SDAI não garante cooperação das autoridades russas.", "A Rússia é, portanto, um país capaz de dizer “não” à SDAI e sustentar essa recusa por meios diplomáticos e estatais. A hostilidade entre as organizações continua, mas uma intervenção aberta confrontaria o próprio governo russo. Isso não autoriza operações clandestinas contra Yaroslava Zorina: qualquer ação para capturá-la ou eliminá-la em território russo permanece proibida pela diretriz individual ALV-0063."], "image": "assets/4eab5eea99d703e626e681f6.png", "imageAlt": "Yaroslava Zorina no congresso russo, com a mão apoiada no queixo.", "imageCaption": "REGISTRO DE IMPRENSA / PRESENÇA NO CONGRESSO RUSSO", "imageNote": "Participação reconhecida na estrutura governamental; influência decisiva da Khabapol sobre decisões apresentadas como iniciativas do Estado russo. A condição de usuária de Aura não resulta em afastamento ou detenção neste registro."}, {"title": "EMPRESAS / DOMINÂNCIA ECONÔMICA", "paragraphs": ["A Khabapol domina uma rede de empresas na Rússia por propriedade direta, intermediários, dependência financeira e intimidação. Transporte, armazenamento, contratos industriais e serviços de segurança oferecem cobertura para movimentação de recursos e proteção de operações sensíveis.", "Empresas de fachada e negócios economicamente funcionais coexistem. A SDAI distingue a direção comprometida com a organização dos trabalhadores sem participação comprovada; a simples presença de um nome empresarial num contrato não estabelece responsabilidade individual por terrorismo. A identificação de beneficiários finais é prioridade de Inteligência."]}, {"title": "LIDERANÇA / YAROSLAVA ZORINA", "paragraphs": ["Yaroslava Zorina concentra a direção estratégica e arbitra disputas entre as estruturas empresariais, regionais e auríticas. Sua autoridade depende da capacidade de manter essas frentes úteis umas às outras, evitando que a competição por recursos paralise os objetivos políticos.", "A imagem de comando é calculada: exposição seletiva, negociação por intermediários e associação com resultados concretos. Os representantes públicos não devem ser automaticamente confundidos com os responsáveis por decisões finais. A líder tem aproximadamente 70 anos. Seu percurso completo e suas capacidades auríticas pessoais não estão confirmados neste dossiê."]}, {"title": "ESTRUTURA / COMANDO CENTRAL E OPERADORES REGIONAIS", "paragraphs": ["A organização combina comando estratégico central com núcleos regionais que administram negócios, contatos e segurança. Células externas recebem objetivos políticos e apoio, mas não necessariamente acesso às informações de outras células. A compartimentação dificulta reconstruir toda a cadeia após uma prisão.", "A autonomia regional existe dentro de limites impostos pela cúpula. Conflitos entre operadores podem explicar ações divergentes, mas não devem ser usados para descartar responsabilidade da organização sem investigação. A estrutura é hierárquica e difere das gangues descentralizadas de Osaka."]}, {"title": "AURAS / PESQUISA, INFLUÊNCIA E EMPREGO", "paragraphs": ["A Khabapol é profundamente envolvida com Auras. Mantém recursos dedicados a pesquisa, observação de portadores e aquisição de equipamentos auríticos, tratando a energia como instrumento de vantagem militar, proteção de interesses e influência internacional.", "A Inteligência aponta integração entre técnicos, patrocinadores empresariais e operadores de campo. Equipamentos e portadores são avaliados conforme sua utilidade estratégica; os membros possuem Aura e apresentam os olhos negros característicos da Khabapol. Pessoas empregadas por empresas controladas não são automaticamente consideradas membros da máfia. A extensão dos laboratórios e a procedência de cada tecnologia permanecem parcialmente desconhecidas.", "A organização procura reduzir dependência de fornecedores externos e proteger o conhecimento acumulado. Relatos sobre projetos específicos exigem confirmação; este dossiê não atribui automaticamente Tecnologia Cryptum, conexão com Contempladores ou participação no Incidente da Interaura à sua liderança."]}, {"title": "OLHOS NEGROS / MARCA DOS MEMBROS", "paragraphs": ["Os membros da Khabapol possuem olhos negros, característica relacionada à presença de Aura e utilizada como marca reconhecível da organização. A líder apresenta o mesmo padrão. O escurecimento ocular não deve ser reduzido a maquiagem ou confundido com a cor de uma íris comum.", "Além da relação com a Aura, os olhos aparentam possuir natureza biônica. A Inteligência mantém essa hipótese em investigação: composição, origem e função dos possíveis componentes ainda não foram esclarecidas. Não há confirmação de visão ampliada, comunicação interna ou controle remoto por meio deles.", "A característica auxilia o reconhecimento, mas exige confirmação de vínculo. Um indivíduo com alteração ocular semelhante não deve ser atribuído à Khabapol apenas pela aparência; trabalhadores de empresas controladas também não são automaticamente membros."]}, {"title": "ATAQUES INTERNACIONAIS / FINS POLÍTICOS", "paragraphs": ["A Khabapol é responsável por diversos ataques terroristas ao redor do mundo com fins políticos. As ações procuram intimidar adversários, pressionar decisões de governo e interferir no equilíbrio entre organizações, em vez de se limitar a lucro imediato.", "A SDAI avalia campanhas de coerção, violência contra interlocutores e ataques a interesses institucionais como partes de uma estratégia comum. A escolha dos alvos pode acompanhar disputas econômicas, mas a vantagem política permanece central. Esta cópia não apresenta datas ou contagens individuais de vítimas ainda não consolidadas."]}, {"title": "SDAI / PRINCIPAL RIVAL", "paragraphs": ["A SDAI é o principal rival da Khabapol. A organização é totalmente contrária à SDAI e ao poder que ela exerce sobre portadores de Aura, fronteiras e pesquisas. A oposição deve ser entendida como conflito estratégico persistente, sem presumir motivação humanitária da máfia.", "A Khabapol considera a intervenção da SDAI uma ameaça à sua autonomia e ao controle de recursos auríticos. A disputa combina combate direto, pressões políticas e contestação da presença internacional da SDAI. A organização é capaz de usar discursos contra a repressão aurítica para defender os próprios interesses.", "A diretriz individual contra Yaroslava Zorina proíbe qualquer ação de captura ou eliminação enquanto ela estiver em território russo. A SDAI aguarda uma saída confirmada do país para avaliar a execução da ordem de captura. Consultar ALV-0063; a hostilidade contra a facção não suspende essa restrição."]}, {"title": "SIEGEL / ALIANÇA INSTÁVEL E ATAQUES", "paragraphs": ["A Khabapol mantém uma aliança estranha com a Siegel: coopera em negócios e interesses específicos, mas continua atacando a corporação. A relação não é um pacto geral de não agressão. Acordos pontuais podem coexistir com disputas por fornecedores, ativos e influência.", "A Inteligência interpreta essa cooperação como convergência limitada, sustentada pelo benefício imediato e pela utilidade de certos intermediários. Ataques contra a Siegel não anulam automaticamente todos os contatos comerciais; contatos comerciais não tornam os demais ativos da Siegel seguros.", "Essa relação é distinta do acordo Siegel–SDAI sobre centros de comando e proteção pessoal dos três CEOs. As restrições desse acordo bilateral não são transferidas à Khabapol. Intermediários e contratos devem ser examinados caso a caso, sem presumir lealdade permanente entre as duas organizações."]}, {"title": "LOS ELEGIDOS E YAKUZAS / RELAÇÕES EXTERNAS", "paragraphs": ["A Khabapol não gosta dos Los Elegidos. A SDAI registra hostilidade e competição por influência internacional, sem presumir que todo contato resulte em combate. O controle de governos por ambas as organizações não constitui, por si só, alinhamento entre elas.", "Diante das yakuzas, a postura é neutra. Não há aliança geral nem campanha de hostilidade estabelecida contra Fajara ou Madaru nesta ficha. Negociações locais, incidentes isolados e contatos de operadores não devem ser convertidos automaticamente em mudança da posição estratégica."]}, {"title": "OSAKA / PRESENÇA NO TEATRO ATUAL", "paragraphs": ["A Khabapol consta entre as forças inimigas presentes no campo de batalha de Osaka. A Inteligência acompanha a movimentação de operadores e possíveis interesses em recursos auríticos na cidade; a composição integral e os objetivos locais não estão confirmados.", "A presença em Osaka não comprova participação no massacre do Clube da Noite nem filiação ao grupo terrorista local. Nenhum apoio ao grupo é atribuído à Khabapol sem registro específico. A coincidência de inimigos comuns também não estabelece aliança."]}, {"title": "APRESENTAÇÃO / PADRÕES DE UNIFORME", "paragraphs": ["Os dois conjuntos abaixo servem como referências de identificação da Khabapol. A SDAI registra variações de corte e acessórios, mantendo a combinação de vestimenta formal e olhos negros como sinais recorrentes. A imagem de corpo inteiro mostra o padrão de uniforme, sem atribuir identidade individual ou patente ao membro representado."]}, {"title": "IDENTIFICAÇÃO / LIMITES DO RECONHECIMENTO", "paragraphs": ["Os padrões de vestimenta registrados incluem um traje formal preto e dourado e uma variante com camisa vermelha, colete e sobretudo ornamentado em bronze. Os retratos de referência apresentam ambos os padrões em enquadramento frontal de corpo inteiro, da cabeça aos calçados. As variantes compartilham a aparência formal e os olhos negros dos membros; não estabelecem, por si só, patente ou função específica.", "A identificação deve combinar registros de vínculo, cadeia de comando e comportamento documentado. O retrato da líder serve como referência de reconhecimento; símbolos ou imagens de fundo de materiais não verificados não são adotados como emblema oficial da organização."]}, {"title": "AVALIAÇÃO SDAI / PRIORIDADES DE INTELIGÊNCIA", "paragraphs": ["A combinação de poder empresarial, controle governamental e pesquisa aurítica permite à Khabapol absorver perdas locais sem necessariamente perder capacidade estratégica. A análise deve considerar financiamento, proteção política e continuidade das redes, além dos operadores de combate.", "Prioridades: confirmar estruturas de comando; identificar beneficiários finais das empresas; localizar centros de pesquisa; esclarecer os contatos com a Siegel; discriminar a presença em Osaka. A classificação terrorista da facção não substitui a emissão de diretrizes individuais para cada alvo."]}], "uniformGallery": [{"label": "KHABAPOL / TRAJE FORMAL - PRETO E DOURADO", "description": "Paletó grafite, camisa escura, colete e gravata em tons dourados. Olhos negros característicos; possível componente biônico sob investigação.", "photo": "assets/a4f69163ebe46e73a681bc6c.png"}, {"label": "KHABAPOL / TRAJE COM SOBRETUDO - VERMELHO E BRONZE", "description": "Camisa vermelha, colete escuro e sobretudo com ornamentação em bronze, broche e corrente. Olhos negros característicos; possível componente biônico sob investigação.", "photo": "assets/78b4ecc08335ea4db0f09455.png"}]},{"id": "FAC-0003", "title": "Irmandade", "category": "Facções Inimigas", "origin": "INTELIGÊNCIA SDAI", "access": "Todas as divisões", "level": 0, "summary": "Organização criminosa originada no Nordeste do Brasil durante a década de 1980. Após o Incidente da INTERAURA, passou a apresentar características mais ocultistas e tornou o estudo das Auras o centro de sua atuação. É a facção mais influente no crime ligado a práticas auríticas em escala mundial e a primeira e única a descobrir como estabelecer conexão com Contempladores.", "detail": "Dossiê organizacional em consolidação.", "factionKey": "irmandade", "factionType": "Organização criminosa / ocultismo aurítico", "area": "Brasil e América Latina · contatos internacionais", "connections": [{"id": "ATV-0007", "note": "Ex-integrante · Janel Hakurei / vínculo histórico; filiação atual ao grupo terrorista de Osaka"}, {"id": "ALV-0060", "note": "Líder · Nicole Antonelli"}], "leadership": "Nicole Antonelli", "fileState": "DOSSIÊ ORGANIZACIONAL / OCULTISMO AURÍTICO", "sections": [{"title": "ORIGEM / NORDESTE BRASILEIRO", "paragraphs": ["A Irmandade surgiu na década de 1980, no Nordeste do Brasil, em um contexto de fortalecimento de grandes forças do crime organizado. Seu histórico inclui assaltos a bancos, ataques a instalações públicas e ações contra políticos de destaque na sociedade brasileira.", "As características mais ocultistas se desenvolveram após o Incidente da INTERAURA, quando a organização passou a demonstrar interesse particular pelas Auras e pelo estudo de suas manifestações. Essa transformação é posterior à sua origem no crime organizado brasileiro."]}, {"title": "AURAS / OBSESSÃO E INFLUÊNCIA CRIMINOSA", "paragraphs": ["O estudo aprofundado das manifestações auríticas evoluiu para uma obsessão organizacional. A Irmandade se consolidou como a facção de maior influência mundial no crime relacionado a essas práticas, com ações responsáveis por distúrbios de grande escala no Brasil.", "A avaliação da SDAI trata sua capacidade de investigar e aplicar fenômenos auríticos como componente central da ameaça. A organização busca compreender essas manifestações, além de empregá-las em suas atividades."]}, {"title": "CONTEMPLADORES / CAPACIDADE EXCLUSIVA", "paragraphs": ["A Irmandade foi a primeira facção e permanece a única a descobrir como estabelecer conexão com Contempladores. Essa capacidade constitui um diferencial decisivo em relação às demais organizações criminosas.", "A existência dessa conexão não significa que todo integrante seja capaz de realizá-la. Os procedimentos, critérios e limites empregados pela organização ainda não estão esclarecidos neste dossiê. A exclusividade do conhecimento exige atenção especial da Inteligência SDAI."]}, {"title": "EXPANSÃO / CONTATOS SEM ALIANÇAS OFICIAIS", "paragraphs": ["Com o tempo, a Irmandade ampliou suas atividades para outros países da América Latina e procurou organizações criminosas de diferentes regiões do mundo interessadas em ocultismo aurítico.", "Esses contatos não constituem alianças oficiais. A organização preserva sua autonomia e prefere atuar de forma independente; proximidade, interlocução ou interesses em comum não devem ser registrados automaticamente como subordinação ou pacto permanente."]}, {"title": "LIDERANÇA / NICOLE ANTONELLI", "paragraphs": ["Nicole Antonelli lidera a Irmandade. Sua campanha contra autoridades brasileiras procura enfraquecer os setores que sustentam a cooperação com a SDAI. A Inteligência avalia os ataques como parte de uma tentativa de ampliar o controle político da organização; essa intenção não equivale à confirmação de que já controla o governo."]}, {"title": "RIVALIDADES / LOS ELEGIDOS E FAJARA", "paragraphs": ["A Irmandade mantém rivalidade com Los Elegidos. A presença de interesses ou contatos internacionais em comum não elimina essa oposição, nem estabelece uma aliança entre as duas organizações.", "A Irmandade também mantém rivalidade com a Yakuza Fajara. Essa hostilidade não implica aliança automática com a Madaru ou com outras facções que enfrentam Fajara."]}, {"title": "IDENTIFICAÇÃO / TATUAGEM NA BOCHECHA", "paragraphs": ["Todos os membros da Irmandade possuem a mesma tatuagem na bochecha, composta por parte do símbolo da organização. O desenho é padronizado entre os integrantes. Máscaras e outros equipamentos podem ocultar a marca.", "A tatuagem também pode permanecer após o afastamento de um integrante. Janel Hakurei conserva essa identificação em razão de seu passado na Irmandade; a marca isolada não confirma uma relação atual de comando."]}, {"title": "APRESENTAÇÃO / PADRÃO DE UNIFORME", "paragraphs": ["O padrão registrado combina moletom preto com capuz, máscara holográfica integral de aparência luminosa ciano, calças escuras de corte amplo, luvas e calçados claros reforçados. Bolsas azuis e pequenos compartimentos utilitários integram o conjunto.", "A máscara encobre o rosto e a tatuagem na bochecha. O registro visual abaixo serve para reconhecimento do conjunto; vestuário e acessórios devem ser avaliados junto a outros elementos de identificação.", "As máscaras holográficas apresentam alguma energia aurítica. A finalidade dessa presença de Aura e as intenções por trás de seu emprego permanecem desconhecidas para a SDAI. Não há confirmação de função ofensiva, defensiva ou de conexão com Contempladores."]}, {"title": "DIRETRIZ OPERACIONAL / LIDERANÇA", "paragraphs": ["Nicole Antonelli deve ser capturada viva e interrogada. Após a conclusão do interrogatório, a diretriz determina sua eliminação. A execução não substitui a prioridade inicial de captura."]}, {"title": "HISTÓRICO / ATAQUES CONTRA A SDAI E AUTORIDADES NACIONAIS", "paragraphs": ["ATAQUE A POSTO DE CONTENÇÃO / NORDESTE DO BRASIL - Integrantes da Irmandade atacaram uma instalação da SDAI utilizada na custódia temporária de detidos auríticos. A ação incluiu sabotagem do fornecimento elétrico e confronto com a equipe de guarda. Foram registradas mortes, danos à estrutura e retirada de detidos; destino posterior em investigação.", "EMBOSCADA A CONVOIO / TRANSFERÊNCIA DE CUSTÓDIA - Um comboio de transporte da SDAI foi bloqueado em uma rota terrestre brasileira e atacado por múltiplas direções. O relatório registra emprego de manifestações auríticas e máscaras holográficas. O mecanismo específico dessas máscaras não foi determinado.", "ATAQUE A EQUIPE DE INVESTIGAÇÃO / ÁREA URBANA - Uma equipe da SDAI que apurava mortes de autoridades favoráveis à organização sofreu uma emboscada. Registros recuperados vincularam os executores à Irmandade. A conexão operacional com a campanha de Nicole é investigada; não há confirmação de que tenha participado pessoalmente do confronto.", "CONFRONTOS EM OSAKA - Unidades da SDAI registram ataques e resistência armada de integrantes da Irmandade em setores urbanos. A presença da facção é distinta do grupo terrorista sem nome. O passado de Janel na Irmandade não permite atribuir automaticamente suas ações atuais ao comando de Nicole.", "ATAQUES CONTRA AUTORIDADES / BRASIL - A campanha de Nicole inclui assassinatos de políticos brasileiros importantes, sobretudo daqueles que apoiam plenamente a SDAI. Os atos são avaliados como tentativa de desestabilizar o governo e abrir caminho para o controle político da Irmandade; o domínio do governo brasileiro não está confirmado.", "ATAQUE A INSTALAÇÃO PÚBLICA / NORDESTE BRASILEIRO - Integrantes armados atacaram uma instalação administrativa durante uma ação de intimidação contra representantes locais. Houve mortes, interrupção dos serviços e danos à estrutura. A ocorrência se soma ao histórico de assaltos a bancos e ataques a instalações públicas da organização.", "EMBOSCADA A FORÇAS LOCAIS / AMÉRICA LATINA - Uma ação policial contra uma estrutura ligada ao ocultismo aurítico foi alvo de emboscada. Os relatórios identificaram integrantes da Irmandade no ataque. O país e os executores não estão discriminados nesta cópia regional; o episódio não constitui prova de aliança com outras facções.", "CONTROLE DO REGISTRO - Ocorrências atribuídas à organização por relatórios de campo. A ficha registra os atos; autoria individual, totais de baixas e datas exatas permanecem sujeitos à consolidação dos respectivos relatórios. Não presumir participação pessoal da liderança em cada ataque."]}], "leadershipSectionTitle": "LIDERANÇA / IDENTIFICAÇÃO", "executives": [{"name": "Nicole Antonelli", "role": "Líder da Irmandade · Italiana", "description": "Italiana, reconhecida internacionalmente pela SDAI como terrorista após ataques contra o governo brasileiro e contra a própria SDAI. Tentou desestabilizar o governo por diferentes meios, incluindo o assassinato de políticos brasileiros importantes, especialmente aqueles que apoiavam plenamente a SDAI. Suas ações aparentam ter como objetivo assumir o controle do atual governo brasileiro.", "caption": "RETRATO DE IDENTIFICAÇÃO / NICOLE ANTONELLI", "photo": "assets/7bf1ac23ab132e571d0836d2.png"}], "uniformGallery": [{"label": "IRMANDADE / PADRÃO DE UNIFORME", "photo": "assets/1c99285fbdb7618f0c4427a0.png"}], "organizationOrigin": "Nordeste do Brasil · década de 1980"},{"id": "FAC-0004", "title": "Los Elegidos", "category": "Facções Inimigas", "origin": "INTELIGÊNCIA SDAI", "access": "Todas as divisões", "level": 0, "summary": "Cartel mexicano com presença desde a década de 1970. Originalmente ligado ao tráfico de drogas e a sequestros, transformou sua atuação após o Incidente da INTERAURA. Interpreta as Auras como um presente divino associado a Deus e à Santa Muerte. Atua mundialmente em crimes auríticos e tráfico de pessoas, sob a liderança de Regina “La Patrona” Carrillo. O governo mexicano encontra-se completamente submetido à organização.", "detail": "Dossiê organizacional em consolidação.", "factionKey": "elegidos", "factionType": "Cartel mexicano / organização criminosa", "area": "Atuação mundial · México sob domínio do cartel · presença em Osaka", "connections": [{"id": "ALV-0061", "note": "Líder · Regina Carrillo"}, {"id": "ALV-0062", "note": "Vice-líder e sucessora · Valeria Salazar"}], "organizationOrigin": "México · década de 1970", "leadership": "Regina “La Patrona” Carrillo · vice-líder: Valeria “La Heredera” Salazar", "fileState": "DOSSIÊ ORGANIZACIONAL / CARTEL TRANSNACIONAL", "sections": [{"title": "ORIGEM / MÉXICO · DÉCADA DE 1970", "paragraphs": ["Os Los Elegidos são uma organização criminal mexicana de longa data, com presença desde a década de 1970. Seu histórico inicial é marcado por tráfico de drogas e sequestros. A atuação ligada às Auras pertence à transformação posterior ao Incidente da INTERAURA."]}, {"title": "TRANSFORMAÇÃO / PÓS-INCIDENTE INTERAURA", "paragraphs": ["Após o Incidente da INTERAURA, o cartel adaptou-se de forma notável às Auras e desenvolveu uma visão própria sobre suas manifestações. As novas capacidades foram incorporadas à atuação criminosa e à interpretação religiosa da organização."]}, {"title": "DOUTRINA / DEUS, SANTA MUERTE E AURAS", "paragraphs": ["A organização busca estabelecer uma conexão entre Deus, Santa Muerte e as Auras, considerando estas um “presente” divino de Deus. Essa interpretação distingue sua visão das adotadas pelas demais facções.", "O dossiê registra a crença professada pelo cartel. A associação religiosa não constitui confirmação científica da origem das Auras nem comprovação de conexão com Contempladores. A Irmandade permanece a primeira e única facção conhecida a descobrir como estabelecer essa conexão."]}, {"title": "ATUAÇÃO / CRIMES AURÍTICOS E TRÁFICO DE PESSOAS", "paragraphs": ["Atualmente, os Los Elegidos estão fortemente envolvidos em crimes relacionados às Auras ao redor do mundo, além do tráfico de pessoas. A presença registrada em Osaka integra sua atuação internacional; não constitui a origem da organização."]}, {"title": "DOMÍNIO POLÍTICO / GOVERNO MEXICANO", "paragraphs": ["O cartel domina completamente o governo mexicano, que se encontra submetido à organização. O controle não se limita à influência sobre autoridades isoladas: o governo está de joelhos perante os Los Elegidos. Esse domínio deve ser considerado na avaliação das autoridades locais e da atuação do cartel no país.", "Apesar do domínio do cartel sobre o governo mexicano, a SDAI pode agir contra Regina Carrillo dentro do México. Não há, neste caso, bloqueio territorial equivalente ao da diretriz de Yaroslava Zorina na Rússia. A ordem vigente contra Regina continua sendo de eliminação, inclusive em território mexicano."]}, {"title": "IDENTIFICAÇÃO / OBSESSÃO POR OURO", "paragraphs": ["A organização demonstra grande obsessão por ouro. Objetos, veículos e armamentos adornados com esse metal são elementos recorrentes de sua apresentação. A preferência estética acompanha sua exibição de poder e riqueza.", "O uso de ouro, isoladamente, não confirma filiação. Os padrões visuais registrados abaixo devem ser avaliados em conjunto com a iconografia, o vestuário e os demais elementos de reconhecimento."]}, {"title": "LIDERANÇA / REGINA “LA PATRONA” CARRILLO", "paragraphs": ["Regina “La Patrona” Carrillo é a líder terrorista do cartel, com idade estimada próxima dos 50 anos. Registros e referências públicas sugerem que anteriormente atuava na política mexicana. A reconstrução documental de sua carreira permanece em investigação.", "A principal linha de investigação aponta que Regina construiu influência por meio de intermediários, financiamento político e redes locais de favorecimento. A aproximação com operadores do cartel teria transformado esses contatos em uma estrutura de proteção a negócios criminosos. A passagem exata de intermediária política a dirigente dos Los Elegidos ainda não está esclarecida.", "A Inteligência avalia que sua experiência no ambiente político favoreceu a submissão de autoridades ao cartel, combinando pressão, recompensas e dependência institucional. Esse histórico constitui uma reconstrução investigativa; não há cronologia completa homologada. O domínio atual dos Los Elegidos sobre o governo mexicano está registrado separadamente como condição estabelecida."]}, {"title": "RELAÇÕES / IRMANDADE E TEATRO DE OSAKA", "paragraphs": ["Os Los Elegidos mantêm rivalidade com a Irmandade. A SDAI confronta ambas as organizações no campo de batalha ativo de Osaka; sua presença na mesma cidade não estabelece uma aliança entre elas nem com o grupo terrorista de Osaka sem nome declarado.", "A Khabapol mantém hostilidade contra os Los Elegidos e compete com a organização por influência internacional. Não há aliança entre elas."]}, {"title": "APRESENTAÇÃO / PADRÕES DE VESTUÁRIO", "paragraphs": ["Os integrantes apresentam variantes de vestuário, em vez de um uniforme único: coletes e jaquetas com imagens religiosas, peças vermelhas ou azuis, faixas e correntes douradas, trajes com torso exposto e camisas florais. Tatuagens e componentes de aparência protética também aparecem nas referências registradas.", "A prancha reúne cinco variantes observadas, sem atribuir patentes ou divisões internas a cada traje. Alguns elementos dourados são puramente cosméticos e expressam a identidade da facção. Outros parecem corresponder a componentes cibernéticos ou a tecnologias que amplificam as Auras de seus usuários. A composição, a origem e os limites desses equipamentos não estão esclarecidos pela SDAI; aparência dourada não implica, por si só, capacidade de amplificação."]}, {"title": "DIRETRIZ OPERACIONAL / LIDERANÇA", "paragraphs": ["Regina “La Patrona” Carrillo é alvo de eliminação da SDAI. Esta é a diretriz vigente contra a liderança identificada neste dossiê."]}, {"title": "CADEIA DE COMANDO / VICE-LIDERANÇA E SUCESSÃO", "paragraphs": ["Valeria “La Heredera” Salazar exerce a vice-liderança dos Los Elegidos. Sua posição é subordinada à de Regina “La Patrona” Carrillo, atual comandante do cartel.", "Valeria é a sucessora designada para assumir a organização caso Regina não esteja mais no comando. O registro descreve uma previsão de continuidade da liderança, e não uma disputa sucessória confirmada ou uma troca de comando já ocorrida."]}, {"title": "HISTÓRICO / ATAQUES CONTRA A SDAI E AUTORIDADES NACIONAIS", "paragraphs": ["ATAQUE A INSTALAÇÃO LOGÍSTICA / MÉXICO - Um entreposto da SDAI foi atacado após informações sobre a movimentação de pessoal circularem por canais institucionais locais. Houve perda de material e baixas entre as equipes de proteção. A atuação dos Los Elegidos foi identificada no relatório; a participação de autoridades na divulgação das rotas continua em apuração.", "EMBOSCADA A OPERAÇÃO ANTITRÁFICO / ROTA INTERNACIONAL - Forças do cartel atacaram a SDAI durante a interceptação de um transporte ligado ao tráfico de pessoas. Os registros apontam fogo coordenado e manifestações auríticas. Foram observados componentes dourados nos atacantes, sem comprovação de que cada um funcionasse como amplificador.", "ASSALTO A DEPÓSITO DE EQUIPAMENTOS / REDE DE APOIO - Uma célula dos Los Elegidos invadiu um depósito periférico da SDAI e retirou equipamentos antes de provocar danos à instalação. O inventário confirma perdas; não foi estabelecido que as tecnologias de amplificação usadas pelo cartel tenham origem nesse material.", "CONFRONTOS EM OSAKA - Equipes da SDAI enfrentam células dos Los Elegidos em rotas urbanas e posições de apoio. Esses registros não estabelecem subordinação do grupo terrorista de Osaka ao cartel. A rivalidade com a Irmandade permanece registrada.", "ATAQUES E COAÇÃO CONTRA AUTORIDADES / MÉXICO - Os Los Elegidos empregaram ataques, sequestros e intimidação contra autoridades que resistiam aos seus interesses. A campanha de submissão institucional contribuiu para a condição atual de domínio completo do cartel sobre o governo mexicano.", "ATAQUE A FISCALIZAÇÃO / ROTA DE TRÁFICO DE PESSOAS - Agentes estatais que interceptaram um transporte clandestino foram atacados por uma célula do cartel. O objetivo registrado era romper a apreensão e preservar a rota. A ocorrência envolve forças locais e não deve ser confundida com a emboscada distinta contra a SDAI.", "CONFRONTO COM FORÇAS JAPONESAS / OSAKA - Uma célula dos Los Elegidos atacou unidades locais durante uma ação contra posições de apoio ao cartel. O episódio integra o campo de batalha ativo de Osaka e confirma hostilidade às forças do país, além dos confrontos com a SDAI.", "CONTROLE DO REGISTRO - Ocorrências atribuídas à organização por relatórios de campo. A ficha registra os atos; autoria individual, totais de baixas e datas exatas permanecem sujeitos à consolidação dos respectivos relatórios. Não presumir participação pessoal da liderança em cada ataque."]}, {"title": "PERFIL DE COMANDO / VALERIA “LA HEREDERA” SALAZAR", "paragraphs": ["Valeria Salazar ocupa a segunda posição na cadeia de comando. A Inteligência SDAI atribui a ela a articulação entre células regionais, a transmissão de instruções de Regina e o acompanhamento da continuidade de rotas e estruturas de apoio. Seu posto não representa autonomia em relação à líder atual.", "Os registros sugerem que sua ascensão ocorreu pela capacidade de manter operações funcionando durante apreensões, perdas de pessoal e interrupções de comunicação. A proximidade com Regina consolidou sua posição como sucessora designada. Não há confirmação de parentesco entre as duas nem informação suficiente para reconstruir sua trajetória anterior ao cartel.", "O codinome “La Heredera” está associado à sucessão de comando, não a uma relação familiar confirmada. A retirada de Regina do comando não deve ser tratada como garantia de desarticulação dos Los Elegidos: Salazar representa uma estrutura prevista de continuidade da liderança.", "Salazar é identificada como uma jovem adulta. Sua idade exata, origem civil detalhada e capacidades auríticas ainda não estão estabelecidas neste dossiê. A vice-liderança e a designação sucessória estão registradas separadamente dessas pendências."]}], "leadershipSectionTitle": "LIDERANÇA / IDENTIFICAÇÃO", "executives": [{"name": "Regina “La Patrona” Carrillo", "role": "Líder do cartel · Mexicana", "description": "Líder terrorista dos Los Elegidos, com idade estimada próxima dos 50 anos, aparentemente uma antiga política mexicana. A Inteligência SDAI investiga sua passagem da atuação pública à liderança do cartel. Ordem vigente: eliminar.", "caption": "RETRATO DE IDENTIFICAÇÃO / REGINA CARRILLO", "photo": "assets/693c577b1ea91190869cc59e.png"}, {"name": "Valeria “La Heredera” Salazar", "role": "Vice-líder · Sucessora designada", "description": "Jovem adulta, com idade ainda não confirmada. Vice-líder dos Los Elegidos e sucessora designada de Regina. A Inteligência atribui a Salazar a articulação entre células regionais e a transmissão de instruções do comando. Mantém a continuidade operacional do cartel sob a autoridade de La Patrona; a sucessão ainda não ocorreu.", "caption": "RETRATO DE IDENTIFICAÇÃO / VALERIA SALAZAR", "photo": "assets/5ac4482f976e5c0dc4c07895.png"}], "uniformGallery": [{"label": "LOS ELEGIDOS / CINCO VARIANTES DE IDENTIFICAÇÃO", "photo": "assets/b71a355b328017aad5c1bc6e.png"}]},{"id": "FAC-0005", "title": "Yakuza Fajara", "category": "Facções Inimigas", "origin": "INTELIGÊNCIA SDAI", "access": "Todas as divisões", "level": 0, "summary": "Antiga potência yakuza de Osaka, responsável pela morte do antigo primeiro-ministro japonês. Ressurgiu em 2016, preservando suas tradições enquanto incorpora o uso de Auras. Atua contra a Siegel e a SDAI e mantém forte rivalidade com a Yakuza Madaru. A identidade da liderança atual permanece sob investigação.", "detail": "Dossiê operacional / ressurgimento e liderança em investigação.", "factionKey": "fajara", "factionType": "Yakuza", "area": "Osaka, Japão · redes locais em reconstituição", "connections": [{"id": "ATV-0042", "note": "Vínculo em investigação · perfis A e B"}, {"id": "ALV-0050", "note": "Vínculos históricos da família Keiko em investigação"}, {"id": "ALV-0051", "note": "Possível ligação em investigação"}], "organizationOrigin": "Osaka, Japão · organização anterior ao Incidente da INTERAURA", "leadership": "Não esclarecida · dois perfis associados ao nome Taiyo Fajara", "fileState": "ORGANIZAÇÃO ATIVA / LIDERANÇA EM INVESTIGAÇÃO", "sections": [{"title": "HISTÓRICO / A ANTIGA GRANDE FAJARA", "paragraphs": ["A Fajara foi, em tempos passados, a maior e mais influente yakuza de Osaka. Sua estrutura combinava vínculos familiares, autoridade tradicional e controle de atividades criminosas, sustentando o prestígio da antiga grande Fajara.", "A organização é responsável pela morte do antigo primeiro-ministro do Japão. O assassinato permanece como um dos marcos centrais de seu histórico e de sua notoriedade nacional. Os documentos legados da INTERAURA vinculam Taiyo Fajara, identificada como MOD-42, à antiga matriarca e a esse episódio. Essa referência histórica não resolve a identidade de quem exerce o comando atual."]}, {"title": "RESSURGIMENTO / 2016", "paragraphs": ["A Fajara ressurgiu das cinzas em 2016. Desde então, demonstra uma adaptação gradual às mudanças sociais e ao uso de Auras, sem abandonar as raízes tradicionais nem o legado da organização original.", "A Inteligência avalia que a reconstrução combina antigos vínculos de lealdade com novas formas de atuação aurítica. A extensão da rede recuperada e a correspondência entre a estrutura antiga e a atual ainda não estão completamente mapeadas. Seu ressurgimento não equivale à recuperação integral do poder que possuía no passado."]}, {"title": "ESTRUTURA / TRADIÇÃO E ADAPTAÇÃO AURÍTICA", "paragraphs": ["A organização está envolvida em atividades ilícitas relacionadas às Auras. A adoção dessas capacidades integra sua retomada operacional, coexistindo com códigos tradicionais de autoridade e pertencimento.", "Relatórios sugerem a utilização de intermediários e células locais para recompor influência sem expor toda a cadeia de comando. A distribuição de poderes auríticos entre os integrantes e os critérios internos de recrutamento permanecem em investigação."]}, {"title": "LIDERANÇA / COMO TAIYO FAJARA AINDA ESTÁ VIVA?", "paragraphs": ["A aparente presença de Taiyo Fajara na atualidade provoca perplexidade entre a população japonesa. O nome remete à antiga matriarca, mas os avistamentos recentes não produziram uma explicação pública consistente sobre sua sobrevivência, reaparição ou continuidade no comando.", "A SDAI mantém dois perfis distintos: o perfil A, com características de raposa e correspondência aos registros de MOD-42; e o perfil B, com chifres e aparência descrita nos relatórios como demoníaca. A Inteligência não estabeleceu qual delas lidera a Fajara atual, nem se o nome é reivindicado por ambas.", "A documentação histórica favorece a associação do perfil A à antiga matriarca. Entretanto, esse perfil também participou do Massacre do Clube da Noite junto ao grupo terrorista de Osaka, e esse grupo foi registrado em combate contra a própria Fajara. A contradição impede tratar a associação histórica como confirmação de comando presente.", "O perfil B foi avistado atacando a Yakuza Madaru e esquadrões da SDAI junto a integrantes da Fajara. Esses registros indicam atuação conjunta, mas não bastam para confirmar que ela seja a verdadeira matriarca ou explicar sua relação com o perfil A.", "As linhas de investigação incluem sucessão, disputa interna e utilização do mesmo nome como recurso de autoridade. São hipóteses concorrentes, sem conclusão estabelecida. A SDAI não possui explicação confirmada para a coexistência dos dois perfis.", "A Inteligência investiga se a organização está dividida e se existem duas estruturas que se apresentam como Fajara, possivelmente associadas a cada perfil de Taiyo. Também permanece aberta a possibilidade de uma única organização com uma disputa de liderança. A existência de duas Fajaras não está confirmada; a cadeia de comando continua sem conclusão."]}, {"title": "RELAÇÕES / MADARU, SIEGEL E GRUPO DE OSAKA", "paragraphs": ["A Fajara mantém forte rivalidade com a Yakuza Madaru. A disputa envolve influência local, redes criminosas e ações violentas, agravadas pela adaptação das organizações às Auras.", "A Siegel é alvo de ataques da Fajara. A Inteligência interpreta parte desses confrontos como uma reação à expansão da corporação e à redução do espaço antes ocupado pelas organizações yakuza tradicionais. Isso não estabelece uma aliança entre a Fajara e outros inimigos da Siegel.", "O grupo terrorista de Osaka deve ser analisado separadamente. A presença de Taiyo, perfil A, nesse grupo e seus confrontos contra a Fajara tornam a relação contraditória. A Mascarada das Noites aparenta auxiliar o grupo e, segundo uma hipótese de investigação, receber ordens do perfil A; a SDAI continua tratando as duas como pessoas distintas.", "Referências antigas à família Keiko, de Onaya, apresentam possíveis vínculos com a Fajara e feitos do passado. A investigação permanece aberta; sobrenome e antecedentes familiares não confirmam filiação atual de Onaya.", "A Fajara também mantém rivalidade com a Irmandade. Essa hostilidade não estabelece aliança entre seus demais adversários."]}, {"title": "HISTÓRICO / ATAQUES CONTRA A SDAI E FORÇAS RIVAIS", "paragraphs": ["EMBOSCADA A PATRULHA / OSAKA - Relatórios atribuem a integrantes da Fajara uma ação contra uma equipe da SDAI que acompanhava movimentações auríticas em uma área de influência da organização. Os atacantes utilizaram acessos laterais e dispersão para interromper a perseguição. A autoria individual permanece em apuração.", "CONFRONTO COM ESQUADRÕES / PERFIL B - Taiyo, perfil B, foi registrada em ação contra esquadrões da SDAI junto à Fajara. A ocorrência reforça a avaliação de hostilidade operacional, sem esclarecer sua posição hierárquica.", "ATAQUE À SEGURANÇA PRIVADA / SIEGEL - Células atribuídas à Fajara atacaram equipes da corporação em deslocamento por Osaka. A investigação aponta disputa por influência local; o registro não estabelece ataque a instalações centrais protegidas pelo acordo entre Siegel e SDAI.", "OFENSIVA CONTRA A MADARU / OSAKA - Confrontos contra a yakuza rival incluem a presença registrada do perfil B junto a membros da Fajara. A extensão da operação e a identidade de quem emitiu as ordens permanecem em investigação.", "ASSASSINATO POLÍTICO / HISTÓRICO NACIONAL - A morte do antigo primeiro-ministro japonês é atribuída à Fajara e integra seu histórico consolidado. A ligação histórica da antiga matriarca com esse ato não resolve as dúvidas sobre o comando da organização ressurgida."]}, {"title": "APRESENTAÇÃO / PADRÃO DE UNIFORME", "paragraphs": ["O padrão visual registrado combina terno preto, colete escuro, camisa em tom grafite e gravata clara com prendedor metálico. Calças sociais e calçados escuros completam o conjunto. A máscara de raposa preta, com orelhas pontiagudas e desenhos dourados discretos, é o elemento mais característico da referência.", "A máscara é um acessório do uniforme; seu formato não indica, por si só, características físicas de raposa nem identifica um dos perfis de Taiyo. Não há confirmação neste registro de função aurítica ou tecnológica da máscara.", "O traje é uma referência de reconhecimento, não uma identificação individual automática. Vestimenta formal ou máscara semelhante, isoladamente, não comprova filiação à Fajara.", "Os dois perfis de Taiyo devem ser consultados na ficha vinculada. Observações sobre aparência, capacidades e diretrizes individuais não devem ser transferidas automaticamente de um perfil para o outro."]}], "uniformGallery": [{"label": "FAJARA / REFERÊNCIA DE UNIFORME", "photo": "assets/e0c38da7e07cf9672f13f5b6.png"}], "leadershipSectionTitle": "LIDERANÇA / PERFIS EM INVESTIGAÇÃO", "executives": [{"name": "Taiyo Fajara / Perfil A", "role": "Raposa · vínculo histórico com MOD-42", "description": "Associada à antiga matriarca nos arquivos da INTERAURA. Sua participação no grupo terrorista de Osaka e os confrontos desse grupo contra a Fajara impedem confirmar que comande a organização atual.", "caption": "COMANDO ATUAL NÃO CONFIRMADO", "photo": "assets/577e03afe6be11c16eabc518.png"}, {"name": "Taiyo Fajara / Perfil B", "role": "Perfil com chifres · atuação junto à Fajara", "description": "Avistada junto a integrantes da Fajara em ataques contra Madaru e esquadrões da SDAI. A atuação conjunta não esclarece se exerce o matriarcado, disputa o comando ou lidera uma estrutura distinta.", "caption": "COMANDO ATUAL NÃO CONFIRMADO", "photo": "assets/b117e1641dccc9328b80ba6c.png"}]},{"id": "FAC-0006", "title": "Yakuza Madaru", "category": "Facções Inimigas", "origin": "INTELIGÊNCIA SDAI", "access": "Todas as divisões", "level": 0, "summary": "Yakuza originária de Tóquio, historicamente ligada à proteção do governo japonês. O acordo foi rompido pelo governo após o Incidente da INTERAURA. A Madaru preservou sua estabilidade e incorporou práticas auríticas. Sua liderança humana foi substituída por Vela'tha e Aelu'a, duas figuras aparentemente não humanas, cuja possível origem infernal permanece sob investigação. A facção mantém hostilidade declarada contra a SDAI. Seus combatentes se destacam pelo uso intensivo de amplificadores de Aura no corpo, elevada carga aurítica e extrema agressividade.", "detail": "Dossiê operacional / liderança, hostilidade contra a SDAI e amplificação aurítica.", "factionKey": "madaru", "factionType": "Yakuza", "area": "Tóquio e outras áreas do Japão · presença nos conflitos de Osaka", "connections": [{"id": "ATV-0042", "note": "Perfil B · ataques registrados"}, {"id": "ATV-0049", "note": "Hiriko · confrontos registrados em Osaka"}, {"id": "ALV-0050", "note": "Onaya Keiko · confrontos registrados em Osaka"}], "organizationOrigin": "Tóquio, Japão · organização anterior ao Incidente da INTERAURA", "leadership": "Vela'tha e Aelu'a · liderança conjunta · aparentemente irmãs", "fileState": "ORGANIZAÇÃO ATIVA / VÍNCULOS INFERNAIS EM INVESTIGAÇÃO", "leadershipSectionTitle": "LIDERANÇA / IDENTIFICAÇÃO", "executives": [{"name": "Vela'tha", "role": "Co-líder · Dama Carmesim", "description": "Uma das duas figuras que substituíram a antiga liderança humana da Madaru. Características físicas e relatos sustentam a avaliação de natureza não humana. Idade, origem e capacidades individuais ainda não estão consolidadas. Aparentemente irmã da outra co-líder; parentesco ainda em investigação.", "caption": "ORIGEM INFERNAL SOB INVESTIGAÇÃO", "photo": "assets/6685ca40fa2973ba9c30658d.png"}, {"name": "Aelu'a", "role": "Co-líder · Dama Pálida", "description": "Integra o comando conjunto da Madaru. A Inteligência investiga a hipótese de que tenha vindo diretamente do Inferno manifestado após o Incidente. Os mecanismos de sua chegada e a distribuição de autoridade entre as duas líderes permanecem obscuros. Aparentemente irmã da outra co-líder; parentesco ainda em investigação.", "caption": "ORIGEM INFERNAL SOB INVESTIGAÇÃO", "photo": "assets/79c2e06b82fc177e5c1c9c27.png"}], "sections": [{"title": "HISTÓRICO / DOMÍNIO EM TÓQUIO", "paragraphs": ["A Madaru surgiu em Tóquio e possui uma longa história comparável à da Fajara. Enquanto a rival se tornou uma grande potência de Osaka, a Madaru concentrou maior controle e domínio na capital japonesa.", "Historicamente, a organização protegia fielmente o governo japonês sob um acordo que sustentava essa relação. Essa colaboração pertence a um período anterior à ruptura e não representa a posição atual do governo em relação à Madaru."]}, {"title": "RUPTURA / GOVERNO JAPONÊS E PÓS-INCIDENTE", "paragraphs": ["Após o Incidente da INTERAURA, o governo japonês rompeu o acordo com a Madaru. A quebra encerrou a antiga relação de proteção, mas não provocou o colapso da organização.", "Ao contrário da Fajara, a Madaru preservou sua estabilidade e continuou ativa durante as mudanças do período. A Inteligência avalia que a manutenção de redes locais, recursos e estruturas de lealdade facilitou sua adaptação ao novo cenário. O antigo acordo não constitui autorização vigente, proteção estatal atual ou restrição operacional da SDAI."]}, {"title": "ADAPTAÇÃO / INFLUÊNCIA AURÍTICA", "paragraphs": ["A organização passou a demonstrar forte envolvimento com Auras, tornando-se influente nesse meio no Japão. A adaptação ocorreu sobre uma estrutura criminal que permaneceu funcional, sem uma reconstrução equivalente ao ressurgimento da Fajara.", "Relatórios sugerem que a influência aurítica foi incorporada às relações de autoridade e às atividades ilícitas da Madaru. A proporção de integrantes com poderes, os métodos de transmissão de práticas e o alcance das capacidades da organização ainda não foram completamente mapeados."]}, {"title": "COMBATE / AMPLIFICADORES DE AURA", "paragraphs": ["Entre as facções monitoradas, os soldados da Madaru são os que mais utilizam amplificadores de Aura acoplados ao corpo. Múltiplos dispositivos são usados simultaneamente, concentrados em cintos, antebraços e conexões próximas ao tronco. O conjunto sustenta uma carga aurítica elevada durante os confrontos.", "Os registros de combate descrevem investidas agressivas, pressão contínua e resistência em abandonar uma ofensiva. A Inteligência associa esse comportamento à combinação de doutrinação interna e uso intensivo dos amplificadores; os efeitos fisiológicos de cada dispositivo ainda não foram determinados.", "A possibilidade de sobrecarga, desgaste e dependência dos dispositivos permanece sob investigação. A agressividade observada não comprova ausência de comando: há relatos de coordenação entre combatentes mesmo durante descargas auríticas intensas."]}, {"title": "PRÁTICAS / INDÍCIOS DE CANIBALISMO", "paragraphs": ["Há indícios de práticas canibais relacionadas às Auras manipuladas por integrantes da Madaru. Os relatos justificam investigação, mas não permitem estabelecer uma regra comum a todos os membros.", "A SDAI não confirmou se essas práticas possuem função ritual, efeito sobre capacidades auríticas ou outra finalidade. Não se deve atribuir à Madaru o mesmo mecanismo de cura registrado no perfil A de Taiyo apenas pela semelhança superficial entre os relatos."]}, {"title": "CONEXÕES / DEMÔNIOS E INFERNO", "paragraphs": ["A Madaru apresenta ligações com demônios e com o Inferno manifestado após o Incidente da INTERAURA. Os detalhes de como esses vínculos foram estabelecidos permanecem obscuros.", "A Inteligência considera que essas conexões podem ter alterado a estrutura de comando e a posição da organização no cenário aurítico japonês. A existência de contatos não esclarece, por si só, sua extensão, suas condições nem o grau de dependência da Madaru em relação a entidades externas.", "Não há base para atribuir à Madaru a conexão com Contempladores descoberta pela Irmandade. Vínculos infernais e conexões com Contempladores permanecem classificados como fenômenos distintos."]}, {"title": "LIDERANÇA / SUBSTITUIÇÃO DO COMANDO HUMANO", "paragraphs": ["Vela'tha e Aelu'a exercem a liderança atual, substituindo dirigentes que anteriormente eram humanos. O destino dos antigos líderes e os detalhes da transferência de comando ainda não foram consolidados.", "As duas aparentemente não são humanas. A principal hipótese de investigação aponta que sejam demônias vindas diretamente do Inferno. Essa origem permanece uma avaliação da Inteligência, não uma conclusão documental sobre o mecanismo de sua chegada.", "Os nomes registrados não possuem sobrenomes confirmados. Não estão estabelecidos idade, identidade civil anterior ou uma relação de subordinação entre as duas. O dossiê registra liderança conjunta, sem presumir uma comandante principal e uma sucessora.", "Vela'tha é referida entre integrantes da Madaru como Dama Carmesim; Aelu'a, como Dama Pálida. A Inteligência classifica essas denominações como apelidos atribuídos pela organização, não sobrenomes ou confirmação de identidade civil.", "As duas aparentemente são irmãs. Essa relação é sustentada por referências recolhidas sobre o comando, mas não foi confirmada por documentação ou análise biológica. CLASSIFICAÇÃO DE PARENTESCO: IRMÃS - EM INVESTIGAÇÃO. A origem infernal presumida não esclarece como esse vínculo deve ser interpretado."]}, {"title": "RELAÇÕES / FAJARA E CENÁRIO JAPONÊS", "paragraphs": ["A Madaru manifesta ódio aberto à SDAI, tratada internamente como inimiga da organização e de sua autoridade aurítica. A antiga proteção ao governo japonês foi substituída por uma postura de enfrentamento contra agentes, operações de contenção e estruturas de repressão. Sua hostilidade contra a SDAI é atual e não se limita à rivalidade com a Fajara.", "A Madaru mantém forte rivalidade com a Fajara. O conflito envolve influência, estruturas criminosas e a disputa por espaço em um Japão transformado pelas Auras.", "Taiyo, perfil B, foi registrada atacando a Madaru junto à Fajara. Esse confronto não estabelece parentesco, origem comum ou aliança entre o perfil B e as líderes da Madaru, apesar das características descritas como demoníacas.", "O histórico de proteção ao governo japonês não deve ser confundido com colaboração atual. A ruptura pós-Incidente marca a distinção entre a antiga relação política e a atuação contemporânea da organização. Não há aliança consolidada com Siegel, Irmandade, Los Elegidos ou o grupo terrorista de Osaka neste registro.", "Há registros de confrontos de Hiriko e Onaya Keiko com integrantes desta organização em Osaka. Os dois pareciam atuar como justiceiros. A SDAI mantém sua classificação de terroristas; esses episódios não comprovam participação de todos os integrantes do grupo de Osaka em cada confronto. Consultar ATV-0049, ALV-0050 e FAC-0010."]}, {"title": "HISTÓRICO / ATAQUES E CONFRONTOS REGISTRADOS", "paragraphs": ["CONFRONTO COM A FAJARA / OSAKA - Unidades locais da Madaru estiveram envolvidas em confrontos com integrantes da rival. Há registro de participação de Taiyo, perfil B, no lado da Fajara; as ordens emitidas pelas líderes da Madaru nessa ocorrência ainda não foram reconstruídas.", "EMBOSCADA A EQUIPE SDAI / TÓQUIO - Relatórios atribuem a uma célula da Madaru uma ação contra uma equipe que investigava movimentações auríticas em sua área de influência. O ataque interrompeu a diligência e permitiu a dispersão dos suspeitos. A participação pessoal de Vela'tha ou Aelu'a não está confirmada.", "ATAQUE A OPERAÇÃO POLICIAL / TÓQUIO - Integrantes atribuídos à organização reagiram a uma operação das autoridades japonesas contra uma estrutura criminal local. A ocorrência exemplifica a ruptura com a antiga função de proteção ao governo, sem demonstrar uma ofensiva coordenada contra toda a administração nacional.", "DISPUTA DE INFLUÊNCIA / REDES LOCAIS - Relatórios de intimidação e ataques a intermediários rivais sugerem ações para preservar o controle de recursos e vínculos da organização. A conexão de cada episódio com práticas canibais ou entidades infernais exige comprovação própria."]}, {"title": "RECONHECIMENTO / IDENTIFICAÇÃO E LACUNAS", "paragraphs": ["Os retratos das líderes mostram trajes associados ao comando yakuza: Vela'tha em preto e vinho, Aelu'a em marfim e grafite. Os uniformes dos combatentes são registrados separadamente nas referências abaixo.", "Aparência, chifres e referências ao Inferno não bastam para atribuir filiação à organização. Informações sobre capacidades individuais e a distribuição interna de funções aguardam investigação específica."]}, {"title": "APRESENTAÇÃO / MÁSCARAS E UNIFORMES", "paragraphs": ["Máscaras de demônio são recorrentes entre os soldados da Madaru, variando entre coberturas integrais com chifres e máscaras que cobrem a parte inferior do rosto. A aparência da máscara não confirma natureza demoníaca do usuário: integrantes humanos também adotam esse padrão.", "A variante tradicional combina vestimenta preta de gola alta, camada externa com bordados florais claros e dourados, luvas escuras e máscara demoníaca integral preta com detalhes dourados. Amplificadores corporais são integrados sob as camadas do traje e em suportes nos antebraços e na cintura.", "A variante contemporânea combina uniforme branco com painéis vermelhos, cintos e ferragens metálicas, luvas e máscara demoníaca clara com detalhes vermelhos e dourados. Módulos amplificadores e conexões aparentes acompanham a cintura e os braços, mantendo mobilidade para confrontos rápidos.", "As duas referências registram padrões observados, sem estabelecer divisões oficiais ou patentes. As máscaras reforçam a identidade intimidatória da organização; uma função aurítica própria desses acessórios não foi confirmada."]}], "uniformGallery": [{"label": "MADARU / VARIANTE TRADICIONAL - MÁSCARA INTEGRAL", "description": "A variante tradicional combina vestimenta preta de gola alta, camada externa com bordados florais claros e dourados, luvas escuras e máscara demoníaca integral preta com detalhes dourados. Amplificadores corporais são integrados sob as camadas do traje e em suportes nos antebraços e na cintura.", "photo": "assets/305f7e3eeab8ea4c91b29253.png"}, {"label": "MADARU / VARIANTE CONTEMPORÂNEA - MÁSCARA PARCIAL", "description": "A variante contemporânea combina uniforme branco com painéis vermelhos, cintos e ferragens metálicas, luvas e máscara demoníaca clara com detalhes vermelhos e dourados. Módulos amplificadores e conexões aparentes acompanham a cintura e os braços, mantendo mobilidade para confrontos rápidos.", "photo": "assets/09603018866c1eee745f436f.png"}]},{"id": "FAC-0007", "title": "Saqueadores", "category": "Facções Inimigas", "origin": "INTELIGÊNCIA SDAI", "access": "Todas as divisões", "level": 0, "summary": "Gangue originária de Osaka, fundada entre 2006 e 2007. Sequestra portadores de Aura para extração forçada e fatal de energia aurítica, armazenada em cápsulas de fabricação própria e vendida no mercado negro. Estrutura aparentemente descentralizada; há vítimas inocentes, incluindo crianças e adolescentes.", "detail": "Dossiê operacional / sequestros, extração aurítica, comércio clandestino e reconhecimento visual.", "factionKey": "saqueadores", "factionType": "Gangue local / tráfico de energia aurítica", "area": "Osaka · células e pontos de venda clandestinos", "connections": [{"id": "ALV-0051", "note": "Confrontos registrados"}, {"id": "FAC-0008", "note": "Facção rival · Filhos de Naniwaku"}, {"id": "ATV-0049", "note": "Hiriko · confrontos registrados em Osaka"}, {"id": "ALV-0050", "note": "Onaya Keiko · confrontos registrados em Osaka"}], "organizationOrigin": "Osaka, Japão · entre 2006 e 2007", "leadership": "Aparentemente descentralizada · sem líder central identificado", "fileState": "DOSSIÊ ORGANIZACIONAL / EXTRAÇÃO E TRÁFICO AURÍTICO", "sections": [{"title": "ORIGEM / OSAKA - 2006 A 2007", "paragraphs": ["Os Saqueadores surgiram em Osaka entre 2006 e 2007, anos após o Incidente da INTERAURA. A gangue consolidou sua atuação em torno de crimes relacionados à Aura, explorando a demanda clandestina por energia aurítica armazenada.", "A cronologia de formação é aproximada. Não há fundador identificado nem registro confiável de uma sede original; a presença em diferentes bairros não comprova uma expansão coordenada por um comando único."]}, {"title": "ESTRUTURA / CÉLULAS DESCENTRALIZADAS", "paragraphs": ["Os registros disponíveis apontam para um grupo descentralizado, aparentemente sem líder central. Núcleos locais organizam sequestros, custódia das vítimas, circulação de cápsulas e negociação com intermediários. A existência de responsáveis por uma operação não implica autoridade sobre toda a gangue.", "A Inteligência avalia que parte das células coopera por interesses comerciais e acesso a equipamentos. Contatos compartilhados e padrões visuais semelhantes sustentam a associação entre núcleos, mas não estabelecem uma hierarquia geral.", "A prisão ou neutralização de um responsável local não deve ser apresentada como desmantelamento integral dos Saqueadores. A extensão da rede e as relações entre seus pontos de atuação permanecem em investigação."]}, {"title": "ATIVIDADE CRIMINOSA / SEQUESTRO E EXTRAÇÃO DE AURA", "paragraphs": ["A principal atividade registrada é o sequestro de portadores de Aura para retirar à força sua energia aurítica, armazená-la em cápsulas de energia e comercializar o material. O processo utilizado pelos Saqueadores sempre provoca a morte da vítima. As pessoas sequestradas são tratadas como fonte de rendimento, sem consentimento ou finalidade terapêutica.", "A gangue está associada a diversos desaparecimentos em Osaka. Há registros envolvendo pessoas inocentes, incluindo crianças e adolescentes; idade, ausência de filiação a facções ou falta de histórico criminal não constituem proteção contra a seleção como vítima.", "Os próprios Saqueadores fabricam as cápsulas, seguindo sempre o mesmo padrão de formato. A fabricação compartilhada desse modelo não implica a existência de um líder central. A origem dos extratores permanece desconhecida; não atribuir esses dispositivos automaticamente à INTERAURA, à SDAI ou a outra facção.", "A SDAI confirmou mortes decorrentes da extração forçada e confiscou cápsulas contendo energia retirada dessas vítimas. A extração praticada pela gangue é fatal em todos os casos. O paradeiro de outros desaparecidos permanece em investigação, sem confirmação de que todos tenham sido submetidos ao processo."]}, {"title": "COMÉRCIO CLANDESTINO / CÁPSULAS DE ENERGIA", "paragraphs": ["As cápsulas são negociadas como mercadoria aurítica. A avaliação da SDAI aponta para vendas por intermediários e circulação entre pontos clandestinos, permitindo que células se beneficiem da extração sem manter contato direto com o comprador final.", "Compradores, volumes comercializados e destinos finais ainda não estão consolidados. A venda de energia não comprova aliança permanente com uma facção, nem permite atribuir a todos os compradores conhecimento da origem de cada cápsula.", "A movimentação de recipientes, isoladamente, não identifica um Saqueador: cápsulas também existem fora dessa rede criminosa. A atribuição depende de vínculos com sequestros, custódia ilegal e transações investigadas."]}, {"title": "EVIDÊNCIA CONFISCADA / PADRÃO DE CÁPSULAS CONFIRMADO", "paragraphs": ["A SDAI confiscou e inspecionou cápsulas de energia aurítica fabricadas pelos próprios Saqueadores e comercializadas no mercado negro de Auras. Os integrantes seguem sempre o mesmo padrão de formato: câmara cilíndrica transparente, reforços metálicos, proteções externas e identificação gráfica de máscara de gás. A inspeção confirmou esse padrão de fabricação da gangue.", "O lote registrado contém energia extraída de vítimas que morreram durante o processo. A procedência foi estabelecida pela investigação da apreensão; a aparência da energia, isoladamente, não identifica a pessoa de origem nem comprova um óbito.", "A fotografia foi registrada por uma câmera da SDAI durante a inspeção, com foco nas cápsulas sobre a bancada e no lote acondicionado ao fundo. O enquadramento não expõe os responsáveis pela análise. O registro documenta material já confiscado e o padrão de comercialização; não representa extração nem atribui esse modelo a todas as cápsulas existentes no mercado.", "O símbolo impresso integra a identificação do produto dos Saqueadores. Semelhança visual exige cruzamento com o contexto da apreensão; não revela por si só o fabricante individual ou a célula responsável."], "image": "assets/64a03669444c81b7eb10739b.png", "imageAlt": "Fotografia institucional SDAI de inspeção de cápsulas auríticas confiscadas dos Saqueadores", "imageCaption": "REGISTRO FOTOGRÁFICO SDAI / INSPEÇÃO DE MATERIAL CONFISCADO", "imageNote": "PADRÃO CONFIRMADO · SAQUEADORES · COMERCIALIZAÇÃO NO MERCADO NEGRO DE AURAS"}, {"title": "RELAÇÕES / SDAI E OUTRAS ORGANIZAÇÕES", "paragraphs": ["Os Saqueadores mantêm rivalidade com os Filhos de Naniwaku em Osaka. Essa rivalidade entre gangues é distinta dos confrontos registrados com a Mascarada das Noites e da hostilidade contra a SDAI. Motivações específicas e extensão dos confrontos entre as células ainda não foram consolidadas.", "Os Saqueadores atuam de forma hostil contra a SDAI, resistindo a operações que ameaçam seus pontos de extração, estoques e ganhos. Há relatos de emboscadas e tentativas de recuperar material apreendido; a autoria deve ser atribuída à célula identificada em cada ocorrência.", "A Mascarada das Noites possui registros de confrontos com integrantes da gangue. A relação é de enfrentamento observado; não indica filiação ou colaboração comercial da Mascarada com os Saqueadores.", "Não há aliança consolidada com a Siegel ou sua PMC. O uso de máscaras de gás não comprova vínculo com o Selo Roxo, com a corporação ou com a cultura cibergótica. Relações comerciais específicas com outras organizações permanecem em apuração.", "Há registros de confrontos de Hiriko e Onaya Keiko com integrantes desta organização em Osaka. Os dois pareciam atuar como justiceiros. A SDAI mantém sua classificação de terroristas; esses episódios não comprovam participação de todos os integrantes do grupo de Osaka em cada confronto. Consultar ATV-0049, ALV-0050 e FAC-0010."]}, {"title": "HISTÓRICO / ATAQUES E OCORRÊNCIAS EM OSAKA", "paragraphs": ["SEQUESTROS E DESAPARECIMENTOS / ÁREAS RESIDENCIAIS - Relatos de familiares e registros de vigilância associam núcleos da gangue ao desaparecimento de moradores. Entre as vítimas registradas há adultos, crianças e adolescentes, sem vínculo criminoso estabelecido.", "CUSTÓDIA CLANDESTINA / IMÓVEIS ADAPTADOS - Investigações localizaram indícios de confinamento e equipamentos ligados ao armazenamento de energia aurítica em instalações improvisadas. O uso temporário dos locais dificulta relacionar uma única instalação a toda a rede.", "RESISTÊNCIA A APREENSÃO / FORÇAS LOCAIS - Integrantes associados à gangue reagiram a uma operação policial voltada ao desaparecimento de moradores e à circulação de cápsulas. O episódio envolve uma célula local; comando e autoria individual seguem em apuração.", "EMBOSCADA A EQUIPE SDAI / RETIRADA DE MATERIAL - Uma equipe que transportava equipamentos apreendidos foi atacada durante a retirada de um ponto investigado. A tentativa de recuperar a carga reforça o interesse comercial da célula no material; não identifica uma liderança central.", "CONFRONTOS COM A MASCARADA / REGISTROS CRUZADOS - Avistamentos documentam enfrentamentos entre a Mascarada das Noites e membros dos Saqueadores. Os registros integram o histórico da gangue e a ficha ALV-0051, sem esclarecer a identidade da Mascarada.", "CONTROLE DO REGISTRO - Datas, totais de vítimas e responsáveis por cada ocorrência ainda aguardam consolidação. Não somar relatos potencialmente referentes ao mesmo desaparecimento como vítimas distintas."]}, {"title": "APRESENTAÇÃO / MÁSCARAS DE GÁS E VESTIMENTA", "paragraphs": ["Máscaras de gás de design exótico são um traço recorrente entre os integrantes. A referência visual mostra lentes circulares claras, conjunto frontal saliente e mangueiras corrugadas, combinados com vestimenta utilitária. A capacidade de filtragem ou função aurítica da máscara não foi confirmada.", "O padrão registrado inclui casaco ocre de gola alta, correias escuras, cinto com bolsas, luvas, calças escuras com proteção nas pernas e botas. Equipamentos e recipientes aparentes não têm função determinada apenas pela imagem.", "Não confundir os Saqueadores com cibergóticos: máscaras de gás também aparecem nessa cultura e em outras forças. A identificação exige o conjunto visual e o contexto operacional, especialmente vínculos com a rede de sequestro e extração.", "A imagem registra uma apresentação observada, sem estabelecer uniforme obrigatório, patente ou divisão interna. Variações entre células são compatíveis com a estrutura descentralizada investigada."]}], "uniformGallery": [{"label": "SAQUEADORES / REFERÊNCIA VISUAL DE INTEGRANTE", "description": "Retrato de referência de integrante: máscara de gás com lentes circulares e mangueira conectada ao conjunto dorsal; casaco ocre, correias, bolsas e vestimenta utilitária escura. Sem identidade individual ou liderança atribuída.", "photo": "assets/b99a25a913f9266c3b2192ad.png"}]},{"id": "FAC-0008", "title": "Filhos de Naniwaku", "category": "Facções Inimigas", "origin": "INTELIGÊNCIA SDAI", "access": "Todas as divisões", "level": 0, "summary": "Gangue descentralizada surgida no distrito de Naniwaku, Osaka, durante o lockdown e a evacuação associados ao Incidente da INTERAURA. Atua na revenda clandestina de doses de Anti-Aura obtidas de origem desconhecida, prioriza lucro e se apresenta como justiceira. Rival dos Saqueadores.", "detail": "Dossiê operacional / origem na evacuação, comércio de Anti-Aura, estrutura descentralizada e identificação por emblema.", "factionKey": "naniwaku", "factionType": "Gangue local / comércio clandestino de Anti-Aura", "area": "Osaka · distrito de Naniwaku e pontos discretos nas áreas urbanas", "connections": [{"id": "ALV-0051", "note": "Confrontos registrados"}, {"id": "FAC-0007", "note": "Facção rival · Saqueadores"}, {"id": "ATV-0049", "note": "Hiriko · confrontos registrados em Osaka"}, {"id": "ALV-0050", "note": "Onaya Keiko · confrontos registrados em Osaka"}], "organizationOrigin": "Distrito de Naniwaku, Osaka · Incidente da INTERAURA / 29/12/1999", "leadership": "Descentralizada · sem comando central identificado", "fileState": "DOSSIÊ ORGANIZACIONAL / REVENDA CLANDESTINA DE ANTI-AURA", "sections": [{"title": "ORIGEM / LOCKDOWN E EVACUAÇÃO DE OSAKA", "paragraphs": ["Os Filhos de Naniwaku emergiram nas ruas de Osaka, especialmente no distrito de Naniwaku, durante o Incidente da INTERAURA de 29/12/1999. Sua formação coincidiu com o lockdown e a evacuação da cidade, em um período de caos, pânico e deslocamento de moradores.", "O grupo se organizou para permanecer na cidade evacuada e explorar os imóveis e estabelecimentos deixados para trás. Saques a comércios, propriedades privadas e objetos de valor integram seu histórico de origem. A permanência durante a evacuação não é registrada como operação de auxílio à população.", "Esse período antecede a criação da SDAI. Os atos de origem pertencem ao contexto do Incidente e da evacuação, sem atribuir à organização uma atuação que ainda não existia."]}, {"title": "ESTRUTURA / GRUPO DESCENTRALIZADO", "paragraphs": ["A gangue possui estrutura descentralizada. Núcleos locais mantêm contatos comerciais e pontos de revenda, sem um líder central identificado. Responsáveis por um ponto ou uma negociação não devem ser tratados automaticamente como comandantes de toda a organização.", "O uso compartilhado do nome e do emblema permite reconhecer uma identidade comum entre integrantes com roupas e rotinas distintas. A rede pode cooperar para circulação de mercadorias e proteção de interesses locais sem estabelecer uma hierarquia única.", "O lucro constitui o principal objetivo de suas atividades. A atuação comercial deve ser distinguida da narrativa de auxílio que a gangue utiliza para justificar suas práticas."]}, {"title": "ATIVIDADE ATUAL / REVENDA DE DOSES DE ANTI-AURA", "paragraphs": ["Os Filhos de Naniwaku vendem clandestinamente doses de Anti-Aura em pontos discretos das áreas urbanas de Osaka. A gangue obtém seringas já produzidas e as revende; não fabrica o produto.", "O local de fabricação, os fornecedores e as rotas de abastecimento permanecem desconhecidos. Não atribuir as doses à SDAI, à INTERAURA ou a outra facção sem confirmação de procedência. A posse de uma seringa não esclarece sua origem.", "Integrantes justificam a venda como uma forma de ajudar pessoas que possuem Aura e desejam viver pacificamente na sociedade. Essa justificativa é uma declaração da própria gangue; não comprova gratuidade, finalidade humanitária ou assistência médica.", "A Inteligência SDAI avalia a rede como comércio criminoso relacionado à Aura. Sob a perspectiva institucional, sua circulação clandestina permite que portadores permaneçam fora dos procedimentos de captura e contenção da organização e dificulta a identificação dos fornecedores."]}, {"title": "DISCURSO PÚBLICO / JUSTICEIROS E INTERESSE FINANCEIRO", "paragraphs": ["Os Naniwakus se autodeclaram uma gangue justiceira que ajuda os que estão sofrendo. A apresentação procura aproximar seus vendedores de pessoas que temem perseguição por possuir Aura e de moradores que buscam alternativas à intervenção da SDAI.", "A cobrança pelas doses e a prioridade atribuída ao ganho financeiro sustentam a avaliação de que o discurso de auxílio também funciona como justificativa comercial. A ficha não presume que todos os integrantes tenham a mesma motivação pessoal, mas registra o lucro como objetivo principal da organização.", "A SDAI mantém a classificação criminosa independentemente dessa autodeclaração. O discurso da gangue e a posição institucional são apresentados separadamente, sem tratar a avaliação da SDAI como prova de que todo comprador pretende cometer crimes."]}, {"title": "RELAÇÕES / SAQUEADORES, MASCARADA E SDAI", "paragraphs": ["Os Filhos de Naniwaku mantêm forte rivalidade com os Saqueadores. São organizações distintas: os Naniwakus revendem doses de Anti-Aura adquiridas de fonte desconhecida; os Saqueadores sequestram portadores, realizam extração fatal e fabricam cápsulas para venda de energia aurítica.", "A rivalidade não comprova que os Naniwakus tenham abandonado o interesse financeiro ou que todas as suas ações contra os Saqueadores tenham finalidade de resgate. A extensão dos conflitos e as decisões de cada núcleo continuam em apuração.", "Há registros de confrontos com a Mascarada das Noites, conforme a ficha ALV-0051. Esse vínculo representa enfrentamento observado, não filiação ou colaboração.", "A gangue se opõe às intervenções da SDAI que ameaçam seus pontos de venda e abastecimento. Resistência local e proteção da rede comercial não indicam comando central nem uma aliança geral entre as facções de Osaka.", "Há registros de confrontos de Hiriko e Onaya Keiko com integrantes desta organização em Osaka. Os dois pareciam atuar como justiceiros. A SDAI mantém sua classificação de terroristas; esses episódios não comprovam participação de todos os integrantes do grupo de Osaka em cada confronto. Consultar ATV-0049, ALV-0050 e FAC-0010."]}, {"title": "HISTÓRICO / ATAQUES E OCORRÊNCIAS EM OSAKA", "paragraphs": ["SAQUES DURANTE A EVACUAÇÃO / 1999 - Integrantes permaneceram em áreas evacuadas e retiraram mercadorias, bens privados e objetos de valor. As ocorrências compõem o histórico de formação da gangue, anterior à SDAI.", "COMÉRCIO CLANDESTINO / PONTOS URBANOS - Registros posteriores documentam a oferta de seringas de Anti-Aura por vendedores ligados à rede. A mudança de pontos de encontro dificulta acompanhar o abastecimento e não identifica o local de fabricação.", "RESISTÊNCIA A APREENSÃO / REDE COMERCIAL - Um núcleo reagiu à tentativa de apreensão de doses e retirada de vendedores pela SDAI, buscando preservar o estoque e permitir a fuga de seus integrantes. Autoria individual e responsáveis pelo abastecimento seguem em investigação.", "CONFRONTOS ENTRE GANGUES / SAQUEADORES - Relatórios associam os dois grupos a confrontos em Osaka. A rivalidade está confirmada; causas e resultados de cada episódio devem ser apurados sem presumir uma campanha unificada de todos os núcleos.", "CONFRONTOS COM A MASCARADA / REGISTROS CRUZADOS - Avistamentos documentam enfrentamentos com a Mascarada das Noites. Esses registros não esclarecem sua identidade nem estabelecem vínculo de comando sobre a gangue."]}, {"title": "IDENTIFICAÇÃO VISUAL / EMBLEMA DISCRETO NA ROUPA", "paragraphs": ["Os Filhos de Naniwaku não possuem uniforme comum. Os integrantes utilizam roupas variadas; muitos aplicam discretamente o pequeno emblema da gangue em uma peça de vestimenta.", "A referência mostra o símbolo em um pequeno patch claro em forma de losango, com caligrafia negra, fixado a uma jaqueta de uso cotidiano. A peça fotografada é um exemplo de aplicação, sem estabelecer cor, modelo de roupa ou posição obrigatórios para toda a gangue.", "O emblema auxilia o reconhecimento, mas sua ausência não exclui vínculo com o grupo. A avaliação deve combinar o contexto do avistamento com registros de atuação; uma peça de roupa isolada não identifica a pessoa nem sua função na rede."], "image": "assets/6413a18613aab2101ce166ab.png", "imageAlt": "Detalhe do pequeno emblema dos Filhos de Naniwaku aplicado a uma jaqueta", "imageCaption": "REFERÊNCIA DE RECONHECIMENTO / EMBLEMA NA VESTIMENTA", "imageNote": "ROUPAS VARIADAS · SEM UNIFORME COMUM · IDENTIFICAÇÃO DISCRETA"}]},{"id": "FAC-0010", "title": "Grupo terrorista de Osaka", "category": "Facções Inimigas", "origin": "INTELIGÊNCIA SDAI", "access": "Todas as divisões", "level": 0, "summary": "Dossiê recente consolidado após o massacre no Clube da Noite e atualizado para a Segunda Fase da Lua Crescente Vermelha. Grupo sem nome declarado, composto por alvos identificados e vinculado a apoio hostil sob investigação. Albert Magnar possui óbito confirmado; as diretrizes atuais variam conforme o alvo. Vínculo com um Contemplador não identificado confirmado; a entidade dirige o grupo em seus atos terroristas. Contato com Ariella Chiyomi terminantemente proibido.", "detail": "Dossiê recente / composição, cronologia, capacidades, relações e diretrizes individuais.", "factionKey": "osaka", "factionType": "Grupo terrorista / designação operacional SDAI", "area": "Osaka · localização atual dos integrantes não confirmada", "connections": [{"id": "ATV-0007", "note": "Integrante · Janel Hakurei"}, {"id": "ATV-0049", "note": "Integrante · Hiriko"}, {"id": "ALV-0050", "note": "Integrante · Onaya Keiko"}, {"id": "ATV-0042", "note": "Perfil A · participação registrada"}, {"id": "ATV-0035", "note": "Integrante · Albert Magnar / óbito confirmado"}, {"id": "ALV-0052", "note": "Associado · Encouraçado Desconhecido"}, {"id": "ALV-0051", "note": "Apoio observado · vínculo em investigação"}, {"id": "ALV-0053", "note": "Caveira · apoio observado no massacre / sem afiliação"}, {"id": "CNT-0028", "note": "Runeko · apoio histórico / capturada na primeira perseguição"}], "organizationOrigin": "Formação e data de origem desconhecidas · atuação conjunta documentada em Osaka", "leadership": "Direção por Contemplador não identificado · hierarquia humana não estabelecida", "fileState": "DOSSIÊ RECENTE / ATUALIZADO NA SEGUNDA FASE", "sections": [{"title": "ABERTURA DO DOSSIÊ / DESIGNAÇÃO SDAI", "paragraphs": ["Este registro organizacional foi aberto recentemente após o massacre no Clube da Noite e consolidado a partir das fichas individuais, dos avistamentos e dos relatórios da operação Osaka. A atualização incorpora a declaração da Segunda Fase da Lua Crescente Vermelha.", "Grupo terrorista de Osaka é uma designação atribuída pela SDAI. Não há nome, emblema ou declaração de fundação apresentados pelo próprio grupo. O identificador gráfico exibido neste terminal também é atribuído pela Inteligência, sem comprovar adoção pelos investigados.", "A abertura recente da ficha não significa que o grupo tenha acabado de se formar. Data de origem, recrutamento e primeiros contatos entre seus integrantes permanecem desconhecidos."]}, {"title": "OCORRÊNCIA CENTRAL / MASSACRE NO CLUBE DA NOITE", "paragraphs": ["Janel Hakurei, Hiriko, Onaya Keiko, Taiyo Fajara do Perfil A e Albert Magnar participaram do massacre no Clube da Noite, em Osaka, junto de outros integrantes ainda não individualizados neste índice. A ocorrência fundamentou a classificação desses envolvidos como terroristas pela SDAI.", "Alguns alvos já possuíam histórico de monitoramento e crimes anteriores. A declaração após o massacre não representa o início de toda atividade hostil: Hiriko já era perseguido por confrontos com yakuzas e Siegel; Magnar já atuava no tráfico de armas.", "A associação posterior do Encouraçado e o apoio observado da Mascarada não confirmam participação deles no massacre. A responsabilidade de cada alvo deve acompanhar as evidências de sua ficha individual."]}, {"title": "COMPOSIÇÃO / INTEGRANTES IDENTIFICADOS", "paragraphs": ["JANEL HAKUREI / MOD-07 - Integrante em atividade, brasileira e ex-cobaia confirmada. Materializa lâminas históricas e armazena armas no corpo. Ex-integrante da Irmandade; esse passado não estabelece filiação atual nem comando de Nicole sobre suas ações. Foragida após nova fuga da SDAI.", "HIRIKO / MOD-49 EM REVISÃO - Integrante em atividade com manifestação elétrica e emprego de arma branca. O código MOD-49 é operacional; há forte suspeita de correspondência com MOD-49-1. O óbito do módulo original no Incidente não confirma a morte de Hiriko. Esposo de Onaya Keiko.", "ONAYA KEIKO - Integrante em atividade, japonesa, 34 anos e esposa de Hiriko. Ex-estudante de Direito; abandonou o curso após a declaração de terrorismo. Capacidade ligada a uma tesoura aparentemente capaz de cortar qualquer coisa, com limites desconhecidos. A classificação atual não a identifica como ex-cobaia, mas permanece sob revisão documental.", "TAIYO FAJARA / PERFIL A - Integrante em atividade, com traços de raposa e vínculo confirmado ao registro MOD-42. Possui teleporte observado; os documentos legados registram sensibilidade a odores e recuperação associada ao canibalismo. O vínculo histórico ao matriarcado Fajara não confirma liderança atual.", "ALBERT MAGNAR / MOD-35 - Integrante histórico, britânico, manipulador de metais e fabricante de armas. Óbito confirmado durante a primeira perseguição após o massacre, antes da Segunda Fase. A SDAI reconhece sua união com Janel pela convivência, sem documentação civil localizada. Sua ficha permanece como registro encerrado."], "profileRecords": ["ATV-0007", "ATV-0049", "ALV-0050", "ATV-0042", "ATV-0035"]}, {"title": "ASSOCIADOS E APOIO / VÍNCULOS DISTINTOS", "paragraphs": ["ENCOURAÇADO DESCONHECIDO - Unidade humanoide associada ao grupo e registrada como apoio hostil. Energia aurítica excepcionalmente elevada, camuflagem observada e forte semelhança com a Armadura Hakurei. Operador, módulo, identidade e natureza orgânica ou mecânica não foram determinados. Não é atribuído um comando sobre os integrantes.", "MASCARADA DAS NOITES - Apoio observado, com vínculo organizacional em investigação. Atua desde 2008 e possui teleporte confirmado. A SDAI a trata como pessoa distinta de Taiyo raposa; a hipótese de que receba ordens do Perfil A permanece sem confirmação.", "Caveira - Maior inimigo da SDAI, ativo desde 2000 e responsável por numerosas mortes de pessoas importantes da organização. Até o massacre do Clube da Noite, sempre atuou sozinho contra a SDAI. Surgiu de repente durante o massacre e, PELA PRIMEIRA VEZ, apoiou um grupo. A ruptura desse padrão provocou temor manifesto entre os responsáveis pela resposta da SDAI: o inimigo que sozinho já causava perdas enormes agora estava ajudando os terroristas de Osaka. Permanece sem afiliação; apoio não comprova subordinação ou vínculo com o Contemplador. Eliminar; US$ 100.000.000 e ingresso garantido no Alto Comando por participação efetiva comprovada.", "Runeko / MOD-28 - Presente no Clube da Noite; aparentemente pretendia se encontrar com alguém da Siegel para ingressar na corporação. Após o massacre, acompanhou os terroristas e ofereceu algum apoio, por motivo desconhecido. Capturada na primeira perseguição. Posteriormente empregada com sucesso como agente dupla pela SDAI; permanece sob custódia, com encerramento do serviço e execução em 10 horas determinados pela Segunda Fase. Apoio histórico não estabelece filiação ao grupo.", "Outros participantes do massacre ainda não individualizados não devem receber automaticamente identidade, capacidades ou ordem operacional pertencentes a um dos alvos conhecidos."], "profileRecords": ["ALV-0052", "ALV-0051", "ALV-0053", "CNT-0028", null], "profileNotes": ["", "", "", "", ""]}, {"title": "CONTEMPLADOR NÃO IDENTIFICADO / VÍNCULO CONFIRMADO", "paragraphs": ["A SDAI confirmou a existência de um Contemplador não identificado vinculado ao grupo e responsável por dirigi-lo para esses atos terroristas. O nome da entidade, sua origem e o mecanismo pelo qual exerce essa direção ainda não foram estabelecidos.", "O símbolo registrado no dorso da mão de Janel Hakurei integra a evidência desse vínculo. A fotografia foi obtida durante sua custódia anterior, após o massacre e antes da Segunda Fase; é um registro histórico e não indica que ela esteja atualmente presa.", "A marca é distinta da caveira da Irmandade na bochecha de Janel. O vínculo confirmado do grupo com uma entidade não comprova que seus integrantes tenham descoberto ou dominem o método de conexão conhecido pela Irmandade. Não atribuir o símbolo a Krytux ou a outro Contemplador identificado sem confirmação.", "O alcance da influência sobre cada integrante e a forma de comunicação permanecem em investigação. A existência da direção externa não determina que todas as capacidades do grupo procedam da mesma fonte."], "image": "assets/afd28cf26e975d977aebefbe.png", "imageAlt": "Registro histórico SDAI do símbolo de um Contemplador não identificado no dorso da mão de Janel Hakurei", "imageCaption": "REGISTRO DÉRMICO / JANEL HAKUREI / CUSTÓDIA ANTERIOR", "imageNote": "VÍNCULO CONFIRMADO · CONTEMPLADOR NÃO IDENTIFICADO · DIREÇÃO EXTERNA DO GRUPO"}, {"title": "CRONOLOGIA / CUSTÓDIA E SEGUNDA FASE", "paragraphs": ["ANTERIOR AO MASSACRE - Há registros individuais de perseguição a Hiriko, tráfico de armas por Magnar e histórico legado dos ex-cobaias. Esses antecedentes não estabelecem a data de formação do grupo.", "CLUBE DA NOITE E PRIMEIRA PERSEGUIÇÃO - Após o massacre, os participantes foram declarados terroristas. Magnar morreu na primeira perseguição, atingido por uma pá do helicóptero redirecionado pelo piloto Advancer Renji Kuroda, ADV-017. A ordem então vigente era captura viva; o resultado fatal não a transforma retroativamente em ordem de eliminação.", "CUSTÓDIA DA JANEL / ANTES DA SEGUNDA FASE - Após o massacre, Janel foi capturada e mantida presa. A SDAI tentou empregá-la como agente duplo e preparou um uniforme específico. Ela escapou novamente antes da declaração da Segunda Fase. A tentativa não comprova colaboração efetiva.", "ATIVAÇÃO DA SEGUNDA FASE - Após a queda do transporte SDAI e o desaparecimento de Ariella Chiyomi, que estava a bordo, Arvensis / Marina Azevedo, autorizada pelo Alto Comando a comandar o protocolo, ordenou iniciar a Segunda Fase da Lua Crescente Vermelha. A cientista permanece desaparecida em ação, sem confirmação de vida ou morte. A SDAI aguarda avistamento verificável ou localização para esclarecer sua condição. A recuperação com vida é prioridade operacional; a queda não é atribuída a um integrante deste grupo sem comprovação.", "REGISTRO ATUAL - Osaka é campo de batalha ativo. A DAE Ásia já sobrevoa a cidade de Osaka e coordena a intervenção no espaço aéreo urbano. Os informes representam o momento fixo deste registro; os avistamentos históricos não estabelecem posições atuais."]}, {"title": "CAPACIDADES CONJUNTAS / AVALIAÇÃO OPERACIONAL", "paragraphs": ["O conjunto de capacidades conhecidas reúne materialização de lâminas, eletricidade, corte aurítico, teleporte e apoio de uma unidade encouraçada com camuflagem. Essa combinação oferece meios para romper barreiras, deslocar-se rapidamente e dificultar o acompanhamento visual. A avaliação deriva das fichas individuais, sem confirmar uma doutrina compartilhada.", "Está confirmado que um Contemplador não identificado dirige o grupo para seus atos terroristas. A hierarquia entre os integrantes humanos, a distribuição fixa de funções e a sede atual continuam desconhecidas. Vínculos conjugais e presença conjunta não estabelecem, por si só, autoridade de um integrante sobre os demais.", "A capacidade de fabricar e traficar armas pertence ao histórico de Magnar, já morto. Não há confirmação de que outro integrante tenha assumido sua produção, estoque ou rede de compradores.", "Imagens de rua, alterações de assinatura aurítica e registros de deslocamento devem ser cruzados entre ocorrências. Aparência semelhante, uniforme ou máscara isolados não substituem identificação individual."]}, {"title": "RELAÇÕES / FACÇÕES E VÍNCULOS HISTÓRICOS", "paragraphs": ["HIRIKO E ONAYA / ATUAÇÃO CONJUNTA - Ambos entravam em conflito com Fajara, Madaru, Siegel, Saqueadores e Filhos de Naniwaku. Pareciam tentar agir como justiceiros. Essa aparência não altera sua classificação pela SDAI nem comprova motivação exclusivamente altruísta.", "FAJARA - O grupo foi observado combatendo Fajara, embora Taiyo raposa possua vínculo histórico com seu matriarcado. A divergência sustenta investigação sobre liderança e possíveis disputas internas, sem confirmar divisão, infiltração ou sucessão.", "IRMANDADE / VÍNCULO HISTÓRICO - Janel foi integrante da Irmandade e conserva sua marca na bochecha. A atuação atual do grupo de Osaka não é automaticamente atribuída à organização ou a Nicole Antonelli.", "SIEGEL E YAKUZAS - Os confrontos anteriores de Hiriko e os registros da Mascarada integram a avaliação de hostilidade. Não presumir que todos os integrantes tenham participado de cada episódio individual nem que essas ocorrências estabeleçam aliança com outras facções.", "SAQUEADORES E FILHOS DE NANIWAKU - A Mascarada possui confrontos registrados com ambas as gangues, que também são rivais entre si. Esses registros não comprovam uma campanha coordenada de todo o grupo de Osaka contra as duas organizações.", "O abastecimento clandestino de armas por Magnar não comprova filiação ou pacto com cada comprador. Não há aliança geral entre as facções hostis à SDAI registrada neste dossiê."]}, {"title": "DIRETRIZES INDIVIDUAIS / ORDENS E RECOMPENSAS", "paragraphs": ["JANEL / HIRIKO / TAIYO PERFIL A - Ordem vigente de eliminação na Segunda Fase. Recompensa civil individual de US$ 250.000 para cada alvo, mediante contribuição decisiva, resultado correspondente e validação da Inteligência.", "ONAYA KEIKO - Capturar viva, prender, manter em contenção aurítica e interrogar. Recompensa civil de US$ 250.000. A ordem permanece de captura durante a Segunda Fase.", "ENCOURAÇADO DESCONHECIDO - Conter e capturar a unidade, preservando componentes para análise. Recompensa civil de US$ 200.000. A forte suspeita de operador ex-cobaia não autoriza transferir automaticamente a ordem de eliminação a este registro.", "MASCARADA DAS NOITES - Capturar viva, prender e manter contida. Recompensa civil de US$ 75.000. O apoio investigado não equivale à identificação como MOD-42.", "ALBERT MAGNAR - Óbito confirmado, procura encerrada e progressões militares homologadas. Não há recompensa aberta por novos avistamentos.", "As ordens são individuais: a classificação organizacional como terrorista não cria uma ordem única de eliminação para todos. Promoção de rank/patente garantida aos soldados que contribuírem diretamente para o cumprimento da respectiva diretriz, após comprovação e homologação. Recompensas civis são benefícios distintos; não atribuem função de combate ao colaborador."]}, {"title": "SITUAÇÃO ATUAL / PENDÊNCIAS DE INTELIGÊNCIA", "paragraphs": ["Janel, Hiriko, Onaya e Taiyo do Perfil A permanecem em atividade e sem custódia confirmada. O Encouraçado não foi contido; a Mascarada permanece procurada. Magnar está morto. Não há localização precisa atual estabelecida para os alvos ativos.", "Prioridades de apuração: identificar o Contemplador que dirige o grupo, determinar como transmite suas ordens, identificar participantes ainda desconhecidos e a hierarquia humana, concluir o cruzamento MOD-49-1, esclarecer a liderança Fajara, determinar a natureza do Encouraçado e investigar o vínculo da Mascarada. Impedir qualquer contato de Ariella Chiyomi com os alvos.", "Billy Black / MOD-11 e Gabrijela Vlasic / MOD-67 estão contidos e não possuem envolvimento confirmado com este grupo. O aviso de execução em 10 horas pertence às diretrizes gerais de contenção da Segunda Fase, sem transformá-los em integrantes do grupo de Osaka.", "Este registro é recente e permanece sujeito a novas evidências. Atualizações devem preservar a diferença entre fato confirmado, vínculo observado e hipótese de investigação."]}], "contactBlock": {"title": "ARIELLA CHIYOMI NÃO DEVE ENTRAR EM CONTATO COM ESTE GRUPO. SOB NENHUMA CIRCUNSTÂNCIA.", "body": "Determinação vigente da Segunda Fase da Lua Crescente Vermelha: NÃO AUTORIZE APROXIMAÇÃO. NÃO TRANSMITA MENSAGENS. NÃO ESTABELEÇA UM CANAL ENTRE ELES. Qualquer tentativa de contato deve ser interrompida e comunicada imediatamente ao Alto Comando. Esta determinação permanece em vigor mesmo sob alegação de negociação ou cooperação. A proibição geral também abrange todos os demais ex-cobaias da INTERAURA, mesmo fora deste grupo. Ariella está desaparecida em ação após a queda do transporte SDAI, sem confirmação de vida ou morte; sua custódia não foi restabelecida.", "code": "SEGUNDA FASE DA LUA CRESCENTE VERMELHA / INTERDIÇÃO ABSOLUTA"}}],notices:[{tag:'ORDEM PRIORITÁRIA',date:'SEGUNDA FASE · PRAZO: 10 HORAS',title:'Execução dos ex-cobaias contidos e congelados',body:'Abertura do protocolo determinada por Arvensis / Marina Azevedo, sob autorização do Alto Comando, após a queda do transporte e o desaparecimento de Ariella Chiyomi. As execuções dos ex-cobaias contidos e congelados já estavam previstas na Segunda Fase. Com a declaração da Segunda Fase da Lua Crescente Vermelha, todos os ex-cobaias contidos ou congelados sob custódia da SDAI serão executados em 10 horas. Manter contenção até o procedimento designado. MOD-11 / Billy Black, MOD-67 / Gabrijela Vlasic e MOD-28 / Runeko estão incluídos. O emprego de Runeko como agente dupla está em encerramento; sua colaboração não a exclui da diretriz. Execuções ainda pendentes. O prazo corresponde ao momento fixo deste registro operacional; não é uma contagem regressiva em tempo real.'},{tag:'MANUTENÇÃO',date:'25 SET · 22:40',title:'Serviço programado na estação T-31',body:'Acesso ao Distrito de Pesquisa redirecionado entre 23:00 e 02:00. Utilize a transferência da Estação Central 07.'},{tag:'LOGÍSTICA',date:'25 SET · 18:15',title:'Inspeção de carga no Macrosetor Oriental',body:'Volumes destinados às instalações científicas estão sujeitos à conferência adicional.'},{tag:'SEGURANÇA',date:'24 SET · 09:10',title:'Atualização de procedimentos para acesso técnico',body:'Equipes de manutenção devem manter a credencial visível em corredores de serviço.'}]};

